  ui_story_5036_50360101_49_dialog_content = "「發現漂流巨像接下來將繼續南下，沿金河向影鎮駛來。」",
  ui_story_5036_50360101_50_dialog_content = "「此前該巨像忽然出現在北境上空，據推測是從暗面駛出。」",
