  ui_story_5036_50360101_52_dialog_content = "「有消息稱，該巨像上沒有導航員或乘客，亦沒有任何殺傷性武器。」",
  ui_story_5036_50360101_53_dialog_content = "「但巨像外部尤其是底部，安裝有大量遠古科技製成的巨大螢幕與音響設備。」",
  ui_story_5036_50360101_54_dialog_content = "「目前，啟光與白夜城正在進一步調查如何截停漂流巨像……」",
