  ui_story_5036_50360101_61_dialog_content = "抱歉，PlayerName，我也記不清楚了。",
  ui_story_5036_50360101_62_dialog_content = "不過你也別沮喪，我現在就去問問貢露長官。",
  ui_story_5036_50360101_63_dialog_content = "憑貢露長官對巨像的了解，她一定會告訴我們更多資訊的！",
  ui_story_5036_50360101_64_dialog_content = "不用那麼麻煩了。",
