  ui_story_5036_50360101_67_dialog_content = "幾天前我看到漂流巨像的新聞，覺得十分古怪，就一直泡在圖書館裡翻閱資料。",
  ui_story_5036_50360101_68_dialog_content = "看樣子妳一定是找到了什麼有價值的線索吧？",
  ui_story_5036_50360101_69_dialog_content = "要不然也不會匆匆忙忙地跑過來見我們……",
  ui_story_5036_50360101_70_dialog_content = "嗯，我找到了一條一百多年前的記錄。",
