  ui_story_5036_50360101_72_dialog_content = "沒錯，一百多年前的空裔一族偏安一隅，與光靈並沒有太多接觸。",
  ui_story_5036_50360101_73_dialog_content = "但是有一天，空裔卻忽然向白夜城、啟光等地發傳送求助。",
