  ui_story_5036_50360101_105_option_content = "全速前進！",
  ui_story_5036_50360101_106_dialog_content = "天啊天啊，這就是空裔PlayerName啟動巨像的帥氣時刻嗎？",
  ui_story_5036_50360101_107_dialog_content = "我要趕快記下來！",
  ui_story_5036_50360101_108_dialog_content = "<color=#e8d9bb>「警告！警告！指令無效。」</color>",
  ui_story_5036_50360101_109_dialog_content = "欸？",
  ui_story_5036_50360101_110_dialog_content = "<color=#e8d9bb>「請輸入目的地坐標。」</color>",
  ui_story_5036_50360101_111_dialog_content = "啊，那個……",
