  ui_story_5036_50360101_125_dialog_content = "巨像真的飛起來了！",
  ui_story_5036_50360101_126_dialog_content = "那個天天罵我寫不出好新聞、不能轉正的編輯老師，肯定想破腦袋都想不到吧？",
  ui_story_5036_50360101_127_dialog_content = "整個影鎮有那麼多追著寫空裔故事的記者，但只有我搶佔先機坐進了巨像。",
