  ui_story_5036_50360101_138_dialog_content = "呃……也……也不用這麼誇張啦，哈哈哈。",
  ui_story_5036_50360101_139_dialog_content = "嗯？那個是？",
  ui_story_5036_50360101_140_dialog_content = "珀蘭蒂，好像有張海報從妳的包裡掉出來了。",
  ui_story_5036_50360101_141_dialog_content = "啊哈哈哈，真的呢，我這就收起來。謝謝啦！",
  ui_story_5036_50360101_142_dialog_content = "咦，海報上的人看上去好像有點眼熟？",
  ui_story_5036_50360101_143_dialog_content = "啊？真的欸！這不是歌爾蒂嗎？",
  ui_story_5036_50360101_144_dialog_content = "《探祕尖叫屋》上映以後，我們還在「安德森尖叫屋」門口見過一面呢。",
  ui_story_5036_50360101_145_dialog_content = "電影的反響那麼好，她卻說自己不打算演電影了。",
  ui_story_5036_50360101_146_dialog_content = "也不知道她最近在忙些什麼？",
  ui_story_5036_50360101_147_dialog_content = "不過感覺最近歌爾蒂在影鎮越來越紅了，走到哪裡都能看到她的海報呢。",
  ui_story_5036_50360101_148_dialog_content = "我的這份海報和街上的那些可不一樣。",
  ui_story_5036_50360101_149_dialog_content = "這個是限量珍藏版的！",
  ui_story_5036_50360101_150_dialog_content = "原來珀蘭蒂也是歌爾蒂的粉絲？",
  ui_story_5036_50360101_151_dialog_content = "我……我不算是「蒂蒂人」吧。",
  ui_story_5036_50360101_152_dialog_content = "「蒂蒂人」？",
  ui_story_5036_50360101_153_dialog_content = "「蒂蒂人」就是歌爾蒂的粉絲。我真的不是「蒂蒂人」啦！",
  ui_story_5036_50360101_154_dialog_content = "只是《探祕尖叫屋》上映後我去採訪過歌爾蒂嘛。",
  ui_story_5036_50360101_155_dialog_content = "當時就覺得她好樂觀、好善良，好像一陣清風把我生活中的陰霾都吹散了。",
  ui_story_5036_50360101_156_dialog_content = "要不然我也沒辦法堅持在《十字街祕聞快訊》做這麼久的實習記者。",
  ui_story_5036_50360101_157_dialog_content = "所以後來會稍微留意一下歌爾蒂的作品，僅此而已。",
  ui_story_5036_50360101_158_dialog_content = "哈哈，這不就是粉絲嗎？",
  ui_story_5036_50360101_159_dialog_content = "算......算嗎？還好吧，而且最近很多小道消息說歌爾蒂有暴力傾向。",
  ui_story_5036_50360101_160_dialog_content = "說起來，也許很多公眾人物都有不為人知的一面吧。",
  ui_story_5036_50360101_161_dialog_content = "但我……不想喜歡一個暴力狂。",
  ui_story_5036_50360101_162_dialog_content = "歌爾蒂是暴力狂？不會吧？",
  ui_story_5036_50360101_163_dialog_content = "最近很多小道消息都很離譜的，應該是莫須有的造謠吧？",
  ui_story_5036_50360101_164_dialog_content = "PlayerName在《影鎮小報》上都快被寫成三頭六臂的怪物了。",
  ui_story_5036_50360101_165_dialog_content = "對啊，我真的是深受其害！",
  ui_story_5036_50360101_166_dialog_content = "珀蘭蒂，妳可不能像那些捕風捉影的人一樣隨便寫我的故事啊。",
  ui_story_5036_50360101_167_dialog_content = "放心吧！",
  ui_story_5036_50360101_168_dialog_content = "我只會報導我親眼看到的真相。",
  ui_story_5036_50360101_169_dialog_content = "真希望影鎮都是像妳一樣的好記者啊。",
  ui_story_5036_50360101_170_dialog_content = "好記者？我……我嗎？嘿嘿嘿……",
  ui_story_5036_50360101_171_dialog_content = "<color=#e8d9bb>「請注意！請注意！偵測到前方有不明飛行物。」</color>",
  ui_story_5036_50360101_172_dialog_content = "<color=#e8d9bb>「請下達指令，及時避開！」</color>",
  ui_story_5036_50360101_173_dialog_content = "不明……飛行物？",
  ui_story_5036_50360101_174_dialog_content = "雖然外形和臨空者號大不相同……",
  ui_story_5036_50360101_175_dialog_content = "但那種在陽光下閃光的材質，那種結構和造型，明明就是艘巨像吧！？",
  ui_story_5036_50360101_176_dialog_content = "螢幕……",
  ui_story_5036_50360101_177_dialog_content = "啊，看到了！那些碩大的方形物體就是螢幕嗎？",
  ui_story_5036_50360101_178_dialog_content = "果然不是我們這個時代的產物！",
  ui_story_5036_50360101_179_dialog_content = "一定就是它！這一定就是報紙上所說的漂流巨像！",
  ui_story_5036_50360101_180_dialog_content = "可是，為什麼臨空者號無法識別這艘巨像的名字？",
  ui_story_5036_50360101_181_dialog_content = "為什麼我感應不到巨像導航員的訊息？",
  ui_story_5036_50360101_182_dialog_content = "你真的是一百多年消失的那艘歌頌者號？",
  ui_story_5036_50360101_183_dialog_content = "♪啦……啦啦啦……♪",
  ui_story_5036_50360101_184_dialog_content = "（誰？誰在唱歌？）",
  ui_story_5036_50360101_185_dialog_content = "欸，你們聽到了嗎？",
  ui_story_5036_50360101_186_dialog_content = "聽到什麼？",
  ui_story_5036_50360101_187_dialog_content = "♪嗚嗚嗚嗚……♪",
  ui_story_5036_50360101_188_dialog_content = "歌聲……有人在唱歌？",
  ui_story_5036_50360101_189_dialog_content = "嗯？沒有呀。",
  ui_story_5036_50360101_190_dialog_content = "♪哦啦啦啦……♪",
  ui_story_5036_50360101_191_dialog_content = "（是妳嗎……「歌頌者號」的導航員？）",
  ui_story_5036_50360101_192_dialog_content = "♪嗚嗚嗚嗚……♪",
  ui_story_5036_50360101_193_dialog_content = "（妳為什麼拋下了妳的巨像？）",
  ui_story_5036_50360101_194_dialog_content = "♪啦……啦啦……♪",
  ui_story_5036_50360101_195_dialog_content = "（為什麼……）",
  ui_story_5036_50360101_196_dialog_content = "<color=#e8d9bb>「請注意！請注意！偵測到前方有不明飛行物。」</color>",
  ui_story_5036_50360101_197_dialog_content = "<color=#e8d9bb>「為迴避碰撞風險，巨像將於三秒後自動更改飛行路線。」</color>",
  ui_story_5036_50360101_198_dialog_content = "<color=#e8d9bb>「三……」</color>",
  ui_story_5036_50360101_199_dialog_content = "<color=#e8d9bb>「二……」</color>",
  ui_story_5036_50360101_200_dialog_content = "停止路線更改。",
  ui_story_5036_50360101_201_dialog_content = "調整到與「不明飛行物」相同的飛行方向和飛行速度。",
  ui_story_5036_50360101_202_dialog_content = "隨時校正。",
  ui_story_5036_50360201_1_dialog_content = "<color=#e8d9bb>「注意！注意！正在靠近不明飛行物。」</color>",
  ui_story_5036_50360201_2_dialog_content = "巨像晃動得好厲害！難道是撞到漂流巨像了！？",
  ui_story_5036_50360201_3_dialog_content = "不用害怕，臨空者號只是在減速罷了。",
  ui_story_5036_50360201_4_dialog_content = "啊？好可惜！還以為能拍到兩艘巨像相撞的瞬間呢。",
  ui_story_5036_50360201_5_dialog_content = "那麼精彩的照片一定能登上所有報紙的頭版頭條！",
  ui_story_5036_50360201_6_dialog_content = "如果真的有那種事情發生，恐怕妳根本來不及拍照片。",
  ui_story_5036_50360201_7_dialog_content = "假設！只是一種假設而已啦。",
  ui_story_5036_50360201_8_dialog_content = "不過珀蘭蒂的攝影機看起來倒真是很特別呢。",
  ui_story_5036_50360201_9_dialog_content = "薇絲小姐可真是有眼光！",
  ui_story_5036_50360201_10_dialog_content = "攝影機可不是誰都能擁有的高級設備。",
  ui_story_5036_50360201_11_dialog_content = "更何況我一直在更換它的零件，以追求更驚豔的拍攝效果。",
  ui_story_5036_50360201_12_dialog_content = "當時能進入報社實習，也是多虧了有這台攝影機呢。",
  ui_story_5036_50360201_13_dialog_content = "哇！妳的攝影機是不是能把人拍得更漂亮一點呀？",
  ui_story_5036_50360201_14_dialog_content = "漂亮不漂亮我不敢說，但我保證它拍出來的照片能還原最真實的現場！",
  ui_story_5036_50360201_15_dialog_content = "<color=#e8d9bb>「調整成功，飛行方向與速度已與不明飛行物保持一致。」</color>",
  ui_story_5036_50360201_16_dialog_content = "走吧。",
  ui_story_5036_50360201_17_dialog_content = "欸，這裡距離漂流巨像還有好遠吧？",
  ui_story_5036_50360201_18_dialog_content = "我們要怎麼過去啊！",
  ui_story_5036_50360201_19_dialog_content = "當然是飛過去囉。",
  ui_story_5036_50360201_20_dialog_content = "<anim type=Shake>啊！！！</anim>",
  ui_story_5036_50360201_21_dialog_content = "真……真的飛過來了！？",
  ui_story_5036_50360201_22_dialog_content = "我還是第一次乘坐飛空艇呢，好刺激啊！",
  ui_story_5036_50360201_23_dialog_content = "而且，我現在真的踩在漂流巨像上嗎？",
  ui_story_5036_50360201_24_dialog_content = "天啊，這是多少記者夢寐以求的新聞第一現場！",
  ui_story_5036_50360201_25_dialog_content = "哦不過，就算是再激動，專業的記者也不能忘記自己的專訪對象。",
  ui_story_5036_50360201_26_dialog_content = "讓我來問問此時PlayerName先生的心情吧！",
  ui_story_5036_50360201_27_dialog_content = "PlayerName先生，請問……？",
  ui_story_5036_50360201_28_dialog_content = "……",
  ui_story_5036_50360201_29_dialog_content = "欸，您的臉色好差？這是您對啟光和白夜城無聲的抗議嗎？",
  ui_story_5036_50360201_30_dialog_content = "暗能！忽然有好多暗能的氣息！",
  ui_story_5036_50360201_31_dialog_content = "唔！？難道我們找錯地方了？",
  ui_story_5036_50360201_32_dialog_content = "不可能。這個坐標是伊倫汀審判長親自告訴我的，不會有錯。",
  ui_story_5036_50360201_33_dialog_content = "來不及想那些了，眼前有更需要我們解決的問題！",
  ui_story_5036_50360201_34_dialog_content = "<size=45>吼！！！</size>",
  ui_story_5036_50360202_1_dialog_content = "♪啦……啦啦啦……♪",
  ui_story_5036_50360202_2_dialog_content = "（又是這個歌聲？）",
  ui_story_5036_50360202_3_dialog_content = "（為什麼我從來沒有聽過類似的旋律，卻會莫名地覺得熟悉。）",
  ui_story_5036_50360202_4_dialog_content = "（彷彿這段旋律一直都流淌在我的血液裡，只是現在才想起它。）",
  ui_story_5036_50360202_5_dialog_content = "♪嗚嗚嗚嗚……♪",
  ui_story_5036_50360202_6_dialog_content = "♪哦啦啦啦……♪",
  ui_story_5036_50360202_7_dialog_content = "妳……妳是？",
  ui_story_5036_50360202_8_dialog_content = "……區區空裔，竟然敢忘記我堂堂馬太審判官的大名嗎？",
  ui_story_5036_50360202_9_dialog_content = "在白夜城還沒有人敢這麼忽視我的存在！恥辱，真是奇恥大辱！",
  ui_story_5036_50360202_10_dialog_content = "洛維，你說……嗯？洛維你在幹什麼？",
  ui_story_5036_50360202_11_dialog_content = "卡蓮殿下，您還好嗎？",
  ui_story_5036_50360202_12_dialog_content = "我很好，這點暗鬼不算什麼。",
  ui_story_5036_50360202_13_dialog_content = "也多虧了你們及時趕來，才能這麼快就消滅掉這些暗鬼。",
  ui_story_5036_50360202_14_dialog_content = "嘖，我以前還真沒看出來。",
  ui_story_5036_50360202_15_dialog_content = "洛維，你竟然已經學會搶先一步邀功論賞了？",
  ui_story_5036_50360202_16_dialog_content = "調查還未結束。",
  ui_story_5036_50360202_17_dialog_content = "有人卻想回家。",
  ui_story_5036_50360202_18_dialog_content = "又來了！",
  ui_story_5036_50360202_19_dialog_content = "洛維不知道從哪裡學會了這種逢迎諂媚、排擠同僚的把戲。",
  ui_story_5036_50360202_20_dialog_content = "卡蓮殿下，別讓他的胡言亂語污染了您的耳朵。",
  ui_story_5036_50360202_21_dialog_content = "這些天，我十分妥當、有序地推進了白夜城調查團對漂流巨像的調查工作。",
  ui_story_5036_50360202_22_dialog_content = "不久之後，您就能坐在白夜城柔軟的天鵝絨坐墊上，讀到我撰寫的調查報告了。",
  ui_story_5036_50360202_23_dialog_content = "哦？你一直纏著我們的希諾普，該不會是想抄作業過關吧？",
  ui_story_5036_50360202_24_dialog_content = "貢露長官，請放心。",
  ui_story_5036_50360202_25_dialog_content = "我會小心保管調查資料的。",
  ui_story_5036_50360202_26_dialog_content = "計畫露餡，此路不通。",
  ui_story_5036_50360202_27_dialog_content = "我是為了核對我們的調查資料，不懂就別插嘴！",
  ui_story_5036_50360202_28_dialog_content = "貢露長官，希諾普老師！",
  ui_story_5036_50360202_29_dialog_content = "原來是你們在這艘漂流巨像上執行任務？",
  ui_story_5036_50360202_30_dialog_content = "讓我看看，我們的小薇絲最近是不是又瘦了？",
  ui_story_5036_50360202_31_dialog_content = "欸，有嗎？",
  ui_story_5036_50360202_32_dialog_content = "PlayerName，你再這麼虧待薇絲，就別怪我橫刀奪愛囉？",
  ui_story_5036_50360202_33_dialog_content = "我……我沒有啊……",
  ui_story_5036_50360202_34_dialog_content = "是嗎？嘿嘿嘿～",
  ui_story_5036_50360202_35_dialog_content = "話說回來，你們來得也太晚了吧？",
  ui_story_5036_50360202_36_dialog_content = "我差點以為PlayerName已經放棄對這艘巨像的調查了呢。",
  ui_story_5036_50360202_37_dialog_content = "可是據我所知……",
  ui_story_5036_50360202_38_dialog_content = "白夜城和啟光聯邦此前一直都沒有以官方管道通知過PlayerName關於漂流巨像的事情吧？",
  ui_story_5036_50360202_39_dialog_content = "哦唷？這裡有一位面生的小姑娘呢。",
  ui_story_5036_50360202_40_dialog_content = "您好，我是《十字街祕聞快訊》的實習記者珀蘭蒂。",
  ui_story_5036_50360202_41_dialog_content = "現在正在對PlayerName進行貼身採訪，希望您能回答我剛才的問題。",
  ui_story_5036_50360202_42_dialog_content = "為什麼你們都沒有通知PlayerName關於漂流巨像的事情呢？",
  ui_story_5036_50360202_43_dialog_content = "啟光和白夜城想要背著空裔將巨像瓜分的消息是真的嗎？",
  ui_story_5036_50360202_44_dialog_content = "小記者，請問通知PlayerName是我們啟光的義務嗎？",
  ui_story_5036_50360202_45_dialog_content = "貢露長官？",
  ui_story_5036_50360202_46_dialog_content = "哎呀，看把你們給嚇的。",
  ui_story_5036_50360202_47_dialog_content = "呼呼呼，我好好回答妳就是嘛。",
  ui_story_5036_50360202_48_dialog_content = "我們得到漂流巨像的訊息後，就立刻派遣了人數眾多的調查團隊。",
  ui_story_5036_50360202_49_dialog_content = "無論是附近的空域、還是地面，我們也都部署了大批支援部隊。",
  ui_story_5036_50360202_50_dialog_content = "但我們的首要目的並不是妳猜想的那樣，想要將巨像據為己有。",
  ui_story_5036_50360202_51_dialog_content = "而是要評估這樣一艘從暗面漂流而來的巨像，究竟會對啟光有什麼樣的威脅。",
  ui_story_5036_50360202_52_dialog_content = "畢竟這艘巨像是從暗面漂流而來的，沒人知道這上面究竟乘載著什麼<color=#FFB400>「乘客」</color>。",
  ui_story_5036_50360202_53_dialog_content = "在這一點上，白夜城也抱有同樣的想法。",
  ui_story_5036_50360202_54_dialog_content = "不過究竟是為什麼我總被派來做這種要出滿身臭汗的工作？",
  ui_story_5036_50360202_55_dialog_content = "漂流巨像出現的消息並沒有被封鎖。",
  ui_story_5036_50360202_56_dialog_content = "至於為什麼PlayerName不知道漂流巨像這件事，我也很好奇呢。",
  ui_story_5036_50360202_57_dialog_content = "是……是有一點原因啦。",
  ui_story_5036_50360202_58_dialog_content = "哦吼？",
  ui_story_5036_50360202_59_dialog_content = "沒關係啦，看樣子我們來得也不算太晚嘛。",
  ui_story_5036_50360202_60_dialog_content = "但我仍感到很奇怪，為什麼漂流巨像的通道入口會出現暗鬼？",
  ui_story_5036_50360202_61_dialog_content = "卡蓮殿下，十分抱歉讓您剛剛抵達此處就受到驚嚇。",
  ui_story_5036_50360202_62_dialog_content = "恕我直言，這艘漂流巨像的確也不適合您久留。",
  ui_story_5036_50360202_63_dialog_content = "這裡不僅結滿了充滿灰塵的蜘蛛網，還潛伏著無數骯髒的暗鬼。",
  ui_story_5036_50360202_64_dialog_content = "不過也請您不用太過擔心我們的安危。",
  ui_story_5036_50360202_65_dialog_content = "經過這些天的努力，我們已將大部分暗鬼限制在巨像尾部的<color=#FFB400>封鎖區</color>。",
  ui_story_5036_50360202_66_dialog_content = "請您放心！",
  ui_story_5036_50360202_67_dialog_content = "我已經派人加強了對暗鬼的清理力度。我向您保證！",
  ui_story_5036_50360202_68_dialog_content = "那些骯髒的東西不會再出來打攪您的。",
  ui_story_5036_50360202_69_dialog_content = "辛苦你了，馬太審判官。",
  ui_story_5036_50360202_70_dialog_content = "這是我的榮幸。",
  ui_story_5036_50360202_71_dialog_content = "這麼說，目前這艘漂流巨像暫且還算是安全的？",
  ui_story_5036_50360202_72_dialog_content = "只要不踏進名為<color=#FFB400>封鎖區</color>的困難關卡，大家都丟不掉小命哦～",
  ui_story_5036_50360202_73_dialog_content = "貢露，我想了解這艘巨像的……",
  ui_story_5036_50360202_74_option_content = "控制系統",
  ui_story_5036_50360202_75_dialog_content = "也許我可以試著讓這艘巨像降落。",
  ui_story_5036_50360202_76_dialog_content = "我也這麼想過哦，所以我們對漂流巨像的艦橋做了詳細的調查。",
  ui_story_5036_50360202_77_dialog_content = "但是發現它的控制系統、導航系統甚至意識模組都已經被破壞。",
  ui_story_5036_50360202_78_dialog_content = "現在就算是你，估計也沒辦法控制這艘巨像。",
  ui_story_5036_50360202_79_dialog_content = "怎麼會這樣？那……",
  ui_story_5036_50360202_80_option_content = "動力核心",
  ui_story_5036_50360202_81_dialog_content = "巨像還在漂流，說明它的動力核心還是完好的吧？",
  ui_story_5036_50360202_82_dialog_content = "說動力核心完好，也算對。",
  ui_story_5036_50360202_83_dialog_content = "畢竟它還能為這艘巨像供能，使其處於飛行狀態。",
  ui_story_5036_50360202_84_dialog_content = "說動力核心不完好，也沒錯。",
  ui_story_5036_50360202_85_dialog_content = "因為它曾經遭受過暗鬼的攻擊。",
  ui_story_5036_50360202_86_dialog_content = "雖然不至於突然斷能，但是能量的轉化效率的確會受到一定程度的影響。",
  ui_story_5036_50360202_87_dialog_content = "那……應該也可以修好吧？",
  ui_story_5036_50360202_88_dialog_content = "維修動力核心不是一件簡單的工作。",
  ui_story_5036_50360202_89_dialog_content = "至少需要先讓這艘巨像停止運轉，再關閉動力核心。",
  ui_story_5036_50360202_90_dialog_content = "我們才有足夠的時間進行調查和維修。",
  ui_story_5036_50360202_91_dialog_content = "然而我們現在還沒有找到可以讓巨像停止飛行的辦法。",
  ui_story_5036_50360202_92_dialog_content = "怎麼會這樣？那……",
  ui_story_5036_50360202_93_option_content = "螢幕和音響",
  ui_story_5036_50360202_94_dialog_content = "我看見這艘巨像的外部安裝了一些貌似是螢幕和音響的東西。",
  ui_story_5036_50360202_95_dialog_content = "嗯哼，那些是貨真價實的螢幕和音響哦～",
  ui_story_5036_50360202_96_dialog_content = "而且是遠遠超越目前技術水平的高科技設備！",
  ui_story_5036_50360202_97_dialog_content = "雖然已經陳舊不堪，但卻意外地維持得非常完備。",
  ui_story_5036_50360202_98_dialog_content = "多虧了有希諾普的幫助，我們已經掌握了開啟這些螢幕和音響的方法唷～",
  ui_story_5036_50360202_99_dialog_content = "那麼大的螢幕，如果能播放電影一定很震撼吧？",
  ui_story_5036_50360202_100_dialog_content = "還有……",
  ui_story_5036_50360202_100X1_dialog_content = "還有什麼問題嗎？",
  ui_story_5036_50360202_100X2_option_content = "有",
  ui_story_5036_50360202_100X3_option_content = "沒有了",
  ui_story_5036_50360202_101_dialog_content = "對了……",
  ui_story_5036_50360202_102_dialog_content = "你們沒有發現任何空裔、或者空裔的遺物嗎？",
  ui_story_5036_50360202_103_dialog_content = "唔，目前為止還沒有。",
  ui_story_5036_50360202_104_dialog_content = "哦，對了對了，說到這個……",
  ui_story_5036_50360202_105_dialog_content = "我可愛的助手希諾普幫我們在歷史資料中查到了關於這艘漂流巨像的記載哦。",
  ui_story_5036_50360202_106_dialog_content = "無論是從外形還是規模來看，這艘巨像就是一百多年前空裔曾經報告失聯的那艘——",
  ui_story_5036_50360202_107_dialog_content = "<color=#FFB400>歌頌者號？</color>",
  ui_story_5036_50360202_108_dialog_content = "什麼嘛，原來你早就知道了？",
  ui_story_5036_50360202_109_dialog_content = "可惜，就算知道名字也是無濟於事。",
  ui_story_5036_50360202_110_dialog_content = "這艘載滿了邪惡科技的巨像還是需要被摧毀。",
  ui_story_5036_50360202_111_dialog_content = "摧毀？誰要摧毀歌頌者號？",
  ui_story_5036_50360202_112_dialog_content = "別誤會，這可不是我一個人的決定。",
  ui_story_5036_50360202_113_dialog_content = "這是目前我們大部分人都讚成的最佳方案。",
  ui_story_5036_50360202_114_dialog_content = "喂，你這個看起來就像是大反派的傢伙……",
  ui_story_5036_50360202_115_dialog_content = "這樣說會不會太早了？我可還沒有同意呢。",
  ui_story_5036_50360202_116_dialog_content = "哼哼，恐怕到最後妳不同意也要同意了。",
  ui_story_5036_50360202_117_dialog_content = "馬太審判官，這是怎麼回事？請你解釋清楚。",
  ui_story_5036_50360202_118_dialog_content = "卡蓮殿下，想必剛才您也聽到了。",
  ui_story_5036_50360202_119_dialog_content = "這艘漂流巨像沒有任何利用價值，還蟄居著許多不可控的暗鬼。",
  ui_story_5036_50360202_120_dialog_content = "如果放任它繼續漂流，對整片艾斯特拉大陸上生存的人來說都是一個威脅。",
  ui_story_5036_50360202_121_dialog_content = "還有……",
  ui_story_5036_50360202_122_dialog_content = "它就這麼在天上飛，萬一撞到白夜城可怎麼辦？",
  ui_story_5036_50360202_123_dialog_content = "摧毀這艘漂流的巨像，就是守護我們的白夜城。",
  ui_story_5036_50360202_124_dialog_content = "我想您比我更加清楚，如果城主大人在場也一定會做出同樣的判斷。",
  ui_story_5036_50360202_125_dialog_content = "我們的搜索小隊在荒野上一直不停地搜尋著巨像的遺跡。",
  ui_story_5036_50360202_126_dialog_content = "現在好不容易有這樣一艘仍在運作的巨像，我們真的要……摧毀它嗎？",
  ui_story_5036_50360202_127_dialog_content = "薇絲，別聽那個大反派胡說八道啦。",
  ui_story_5036_50360202_128_dialog_content = "我們已經計算過了，這艘巨像的飛行路線根本不會碰撞到白夜城。",
  ui_story_5036_50360202_129_dialog_content = "只要我們繼續清理，巨像上面的暗鬼也肯定可以清理完。",
  ui_story_5036_50360202_130_dialog_content = "而且，歌頌者號也不像大反派說的那麼一文不值。",
  ui_story_5036_50360202_131_dialog_content = "它身上的每一個部分都擁有非常強大的科研價值。",
  ui_story_5036_50360202_132_dialog_content = "雖然很多地方都被破壞了，修復起來會很困難……",
  ui_story_5036_50360202_133_dialog_content = "但是哪怕付出多大的代價，我認為都是值得的！",
  ui_story_5036_50360202_134_dialog_content = "可妳也知道，對於你們來說……",
  ui_story_5036_50360202_135_dialog_content = "拆走想要研究的部分再擊沉巨像，付出的代價會更小吧？",
  ui_story_5036_50360202_136_dialog_content = "為什麼非要留著這麼個無法控制的大傢伙在天上亂飛呢？",
  ui_story_5036_50360202_137_dialog_content = "完整的研究樣本才更有價值！",
  ui_story_5036_50360202_138_dialog_content = "那妳能現在就拿出證據，證明這艘巨像有修復的可能麼？",
  ui_story_5036_50360202_139_dialog_content = "我……我還需要時間！",
  ui_story_5036_50360202_140_dialog_content = "時間可不等人。",
  ui_story_5036_50360202_141_dialog_content = "等的越久，花出去的經費也就越多。",
  ui_story_5036_50360202_142_dialog_content = "我們擊落巨像，完成任務、結束出差、各回各家，這樣不好嗎？",
  ui_story_5036_50360202_143_dialog_content = "原來你只是想回家？",
  ui_story_5036_50360202_144_dialog_content = "卡蓮殿下，這是我的談判策略，請您不要誤會啊……",
  ui_story_5036_50360202_145_dialog_content = "歌頌者號是我們空裔一族的東西，我絕對不會讓任何人擊落它！",
  ui_story_5036_50360202_146_dialog_content = "我可以幫忙清理暗鬼！",
  ui_story_5036_50360202_147_dialog_content = "也會努力證明給你們看，它真正的價值！",
  ui_story_5036_50360202_148_dialog_content = "沒錯，我也會幫忙。",
  ui_story_5036_50360202_149_dialog_content = "卡蓮殿下？您這是……",
  ui_story_5036_50360202_150_dialog_content = "嗯嗯～看來白夜城的公主殿下也捨不得眼睜睜地看著歌頌者號被擊落呢。",
  ui_story_5036_50360202_151_dialog_content = "親愛的～世上哪有這麼多「捨不得」呀？",
  ui_story_5036_50360202_152_dialog_content = "如果有……那就是錢沒有給到位。",
  ui_story_5036_50360202_153_dialog_content = "呃唔？",
  ui_story_5036_50360202_154_dialog_content = "雖然不介意女孩子對我這麼親暱，但還是出了一身雞皮疙瘩。",
  ui_story_5036_50360202_155_dialog_content = "涉女士？",
  ui_story_5036_50360202_156_dialog_content = "這不是我們的貴賓PlayerName嗎？",
  ui_story_5036_50360202_157_dialog_content = "是不是好久都沒有來浮空商會看我了？",
  ui_story_5036_50360202_158_dialog_content = "那也不用跑到這種地方來找我推銷商品吧？",
  ui_story_5036_50360202_159_dialog_content = "哈哈哈，我們可愛的PlayerName可真是越來越……有趣了呢。",
  ui_story_5036_50360202_160_dialog_content = "從某種意義上來說，也許還真被你說對了。",
  ui_story_5036_50360202_161_dialog_content = "這次嗎，我想要推銷一點不一樣的～",
  ui_story_5036_50360202_162_dialog_content = "親愛的，過來吧！",
  ui_story_5036_50360202_163_dialog_content = "嗯？叫我？",
  ui_story_5036_50360202_164_dialog_content = "不怕受傷也不怕失敗。",
  ui_story_5036_50360202_165_dialog_content = "只要堅持就有好運來。",
  ui_story_5036_50360202_166_dialog_content = "不用灰心也不用喪氣。",
  ui_story_5036_50360202_167_dialog_content = "請把目光交給歌爾蒂！",
  ui_story_5036_50360202_168_dialog_content = "巨像上的友友們，請大家多多指教哦～",
  ui_story_5036_50360202_169_dialog_content = "這……這不是歌爾蒂嗎？",
  ui_story_5036_50360202_170_dialog_content = "呀吼～PlayerName，好久不見，別來無恙哦？",
  ui_story_5036_50360202_171_dialog_content = "欸？",
  ui_story_5036_50360202_172_dialog_content = "歌爾蒂怎麼會出現在這裡？",
  ui_story_5036_50360202_173_dialog_content = "既然大家都認識，那生意就好談多了。",
  ui_story_5036_50360202_174_dialog_content = "涉女士，妳太看得起我了。",
  ui_story_5036_50360202_175_dialog_content = "我還僱不起大明星為我表演節目呢。",
  ui_story_5036_50360202_176_dialog_content = "親愛的，我坐著高價借來的飛空艇，親自帶著當紅的偶像歌手找到這裡……",
  ui_story_5036_50360202_177_dialog_content = "可不是只為了向你一個人推銷的哦。",
  ui_story_5036_50360202_178_dialog_content = "突然就這樣說出來，可能會讓大家吃驚，嘿嘿。",
  ui_story_5036_50360202_179_dialog_content = "但我們打算在漂流巨像上，舉辦一場震驚艾斯特拉的、獨一無二的演唱會。",
  ui_story_5036_50360202_180_dialog_content = "等巨像沿著金河漂流到影鎮上空的時候……",
  ui_story_5036_50360202_181_dialog_content = "我會站在巨像之上，為大家獻上我的歌聲和祝福！",
  ui_story_5036_50360202_182_dialog_content = "到那時，整個影鎮和白夜城都能透過漂流巨像的螢幕欣賞到我的表演哦～",
  ui_story_5036_50360202_183_dialog_content = "呵，庶民不愧是庶民，白日夢都做得越來越誇張了。",
  ui_story_5036_50360202_184_dialog_content = "這位把蛋糕裱花穿在身上的小姐，妳該不會以為生著一張嘴，就能宣稱自己會唱歌吧？",
  ui_story_5036_50360202_185_dialog_content = "「偶像」又是什麼奇怪的低級詞彙？莫名其妙。",
  ui_story_5036_50360202_186_dialog_content = "哎呀～所以說白夜城的人天天宅在小島上也不是一件好事呢。",
  ui_story_5036_50360202_187_dialog_content = "連「偶像」是什麼都不知道，就敢隨便指手畫腳。",
  ui_story_5036_50360202_188_dialog_content = "妳……竟敢嘲笑我無知？",
  ui_story_5036_50360202_189_dialog_content = "聽到實話，氣急敗壞。",
  ui_story_5036_50360202_190_dialog_content = "希諾普，來為這位審判官簡要分享一下關於「偶像」的研究報告吧。",
  ui_story_5036_50360202_191_dialog_content = "好的，貢露長官。",
  ui_story_5036_50360202_192_dialog_content = "在影鎮和紅油沙漠地區，「偶像」是一種新興的職業。",
  ui_story_5036_50360202_193_dialog_content = "他們主要從事歌唱、舞蹈、表演、司儀等演藝事業。",
  ui_story_5036_50360202_194_dialog_content = "與傳統的歌唱家、舞蹈家、演員相比，他們更願意貼近觀看表演的粉絲。",
  ui_story_5036_50360202_195_dialog_content = "他們憑藉個人魅力贏得粉絲的喜愛，為粉絲灌注積極向上的精神力量。",
  ui_story_5036_50360202_196_dialog_content = "哈哈哈，大概就是這樣沒錯哦。",
  ui_story_5036_50360202_197_dialog_content = "我們家歌爾蒂確實非常全能，但現在我們主要把重心放在歌唱事業上。",
  ui_story_5036_50360202_198_dialog_content = "原來如此……",
  ui_story_5036_50360202_199_dialog_content = "啊不是，這些庶民的事情我可沒興趣知道！",
  ui_story_5036_50360202_200_dialog_content = "歌爾蒂能走到今天，多虧了一直支持我鼓勵我的「蒂蒂人」。",
  ui_story_5036_50360202_201_dialog_content = "我想讓「蒂蒂人」們看到，他們支持的偶像可以站在最大的舞台上為大家表演！",
  ui_story_5036_50360202_202_dialog_content = "嘻嘻，雖然我對偶像開演唱會沒有意見……",
  ui_story_5036_50360202_203_dialog_content = "但是要在這艘漂流巨像上開，是不是還是有點異想天開了呢。",
  ui_story_5036_50360202_204_dialog_content = "親愛的長官，您剛才說螢幕和音響都是完好無損的，對嗎？",
  ui_story_5036_50360202_205_dialog_content = "像您這樣對巨像充滿熱愛的人，一定也很想親眼看看這些機器煥發生機的樣子吧？",
  ui_story_5036_50360202_206_dialog_content = "唔……",
  ui_story_5036_50360202_207_dialog_content = "請大家想像一下，熙熙攘攘的人們聚集在金河河畔，只需稍微仰望……",
  ui_story_5036_50360202_208_dialog_content = "就可以看到巨大螢幕上轉播的舞台效果。",
  ui_story_5036_50360202_209_dialog_content = "坐上飛空艇，人們甚至還能從高空中向下俯瞰舞台。",
  ui_story_5036_50360202_210_dialog_content = "簡直是艾斯特拉大陸的狂歡節……",
  ui_story_5036_50360202_211_dialog_content = "沒錯，艾斯特拉大陸的狂歡！PlayerName，我很喜歡你的描述哦～",
  ui_story_5036_50360202_212_dialog_content = "其實剛才聽到你們稱這艘漂流巨像叫「歌頌者號」，我真是大吃一驚呢。",
  ui_story_5036_50360202_213_dialog_content = "也許這孩子曾經也是為了傳遞歌聲才被製造出來的吧。",
  ui_story_5036_50360202_214_dialog_content = "如果它難逃被摧毀的命運……",
  ui_story_5036_50360202_215_dialog_content = "我希望可以讓它在彌留之際，向世界傳遞最後一次歌聲！",
  ui_story_5036_50360202_216_dialog_content = "！！！",
  ui_story_5036_50360202_217_dialog_content = "可惜啊。",
  ui_story_5036_50360202_218_dialog_content = "漂流巨像明天就要飛過一片無人區，那裡是擊落巨像的最佳地點。",
  ui_story_5036_50360202_219_dialog_content = "估計沒時間留給你們開演唱會了。",
  ui_story_5036_50360202_220_dialog_content = "各位大人，也不用那麼著急嘛。",
  ui_story_5036_50360202_221_dialog_content = "等到漂流巨像路過影鎮，再沿著金河一直向前……",
  ui_story_5036_50360202_222_dialog_content = "會到達一片更廣闊的無人區，不是嗎？",
  ui_story_5036_50360202_223_dialog_content = "妳的意思是……大海？",
  ui_story_5036_50360202_224_dialog_content = "把巨像擊落進大海裡？",
  ui_story_5036_50360202_225_dialog_content = "貢露長官，我認為這是一個機會。",
  ui_story_5036_50360202_226_dialog_content = "如果演唱會成功，便可以證明巨像的價值，避免巨像被擊落。",
  ui_story_5036_50360202_227_dialog_content = "我們也能爭取到更多的時間，尋找修理巨像的辦法。",
  ui_story_5036_50360202_228_dialog_content = "如果演唱會失敗，在海上擊落巨像也還來得及。",
  ui_story_5036_50360202_229_dialog_content = "而且在海上擊落也不會給大陸帶來任何危險。",
  ui_story_5036_50360202_230_dialog_content = "歌爾蒂鄭重地請求各位！",
  ui_story_5036_50360202_231_dialog_content = "請延後摧毀這艘漂流巨像……",
  ui_story_5036_50360202_232_dialog_content = "讓我們在巨像上搭建舞台，舉辦一場盛況空前的演唱會吧！",
  ui_story_5036_50360301_1_dialog_content = "<color=#e8d9bb>距離演唱會開始還有六天</color>",
  ui_story_5036_50360301_2_dialog_content = "嗯……左邊有些低了，再往上一點。",
  ui_story_5036_50360301_3_dialog_content = "這樣呢？",
  ui_story_5036_50360301_4_dialog_content = "現在右邊又有些低了。",
  ui_story_5036_50360301_5_dialog_content = "唔？我覺得斜著貼海報，也蠻好看的呢。",
  ui_story_5036_50360301_6_dialog_content = "你說呢，PlayerName？",
  ui_story_5036_50360301_7_dialog_content = "呃，我……我也不是專業的。要不……我們問問歌爾蒂吧？",
  ui_story_5036_50360301_8_dialog_content = "汪！",
  ui_story_5036_50360301_9_dialog_content = "好！可！愛！每次見到棉花糖都好想揉一揉牠呀～",
  ui_story_5036_50360301_10_dialog_content = "棉花糖也很喜歡有人幫牠做按摩呢，哈哈哈。",
  ui_story_5036_50360301_11_dialog_content = "汪汪汪！",
  ui_story_5036_50360301_12_dialog_content = "好啦好啦，乖哦，棉花糖，我待會兒再陪你玩。",
  ui_story_5036_50360301_13_dialog_content = "我們先好好在這裡和大家說說話，好嗎？",
  ui_story_5036_50360301_14_dialog_content = "汪！",
  ui_story_5036_50360301_15_dialog_content = "所以，你們急急忙忙地過來想問我什麼呀？",
  ui_story_5036_50360301_16_dialog_content = "其實我們正在幫忙貼海報，但是不知道怎麼貼比較好……",
  ui_story_5036_50360301_17_dialog_content = "欸？這些事情不用麻煩大家的啦。",
  ui_story_5036_50360301_18_dialog_content = "歌爾蒂不用跟我們客氣。",
  ui_story_5036_50360301_19_dialog_content = "要不是歌爾蒂想辦演唱會，歌頌者號現在也許已經被他們摧毀了。",
  ui_story_5036_50360301_20_dialog_content = "調整設備之類的工作我們也做不來，只能幫忙貼貼海報了。",
  ui_story_5036_50360301_21_dialog_content = "其實大家已經幫歌爾蒂很大很大的忙了。",
  ui_story_5036_50360301_22_dialog_content = "要不是有大家，我真的很擔心啟光和白夜城不會同意我的提案呢。",
  ui_story_5036_50360301_23_dialog_content = "雖然大元帥把漂流巨像的事全權交給我負責……",
  ui_story_5036_50360301_24_dialog_content = "但我還是需要再研究一下才能給你答覆。",
  ui_story_5036_50360301_25_dialog_content = "研究？還研究什麼？這根本就是天方夜譚。",
  ui_story_5036_50360301_26_dialog_content = "白夜城的貴族們怎麼會稀罕這種庶民的「偶像」？",
  ui_story_5036_50360301_27_dialog_content = "我知道我現在的實力還遠遠不夠，所以這場演出不會是我個人的獨角戲。",
  ui_story_5036_50360301_28_dialog_content = "我想邀請各地的偶像，一起參加這場空中演唱會！",
  ui_story_5036_50360301_29_dialog_content = "白夜城和啟光的各位大人們，也許不認同我們的「偶像」定義……",
  ui_story_5036_50360301_30_dialog_content = "但是沒關係，你們也可以找你們心中的偶像來參加！",
  ui_story_5036_50360301_31_dialog_content = "我贊成！",
  ui_story_5036_50360301_32_dialog_content = "嗯？",
  ui_story_5036_50360301_33_dialog_content = "我贊成歌爾蒂在巨像上開演唱會！",
  ui_story_5036_50360301_34_dialog_content = "歌爾蒂說得沒錯，歌頌者號存在的使命，也許就是為了傳遞歌聲。",
  ui_story_5036_50360301_35_dialog_content = "身為空裔，我想見證歌頌者號完成它的使命。",
  ui_story_5036_50360301_36_dialog_content = "更想看到不同地區的人們放下偏見，歡聚一堂的模樣！",
  ui_story_5036_50360301_37_dialog_content = "歌頌者號的出現，也許就是為了讓我們停下來想想……",
  ui_story_5036_50360301_38_dialog_content = "無論地區和身分，我們可以聚在一起完成一件事！",
  ui_story_5036_50360301_39_dialog_content = "請你們給歌爾蒂一點時間，給歌頌者號一點時間。",
  ui_story_5036_50360301_40_dialog_content = "也請你們給我一點時間，也許……",
  ui_story_5036_50360301_41_dialog_content = "也許我還能找到挽救歌頌者號的方法！",
  ui_story_5036_50360301_42_dialog_content = "現在回想起來，當時PlayerName的發言真的好帥氣呢！",
  ui_story_5036_50360301_43_dialog_content = "我聽完差點都要感動地哭出來了～",
  ui_story_5036_50360301_44_dialog_content = "難怪涉老闆總是感嘆「空心粉的數量遠超蒂蒂人」呢。",
  ui_story_5036_50360301_45_dialog_content = "也沒有啦，嘿嘿，我可能是有點容易激動，激動的時候就會說一堆有的沒的。",
  ui_story_5036_50360301_46_dialog_content = "我倒是覺得涉女士才是全場最帥氣的人呢。",
  ui_story_5036_50360301_47_dialog_content = "她微笑著說自己會承包所有工作人員的全部費用，那一刻簡直是在發光！",
  ui_story_5036_50360301_48_dialog_content = "商人不會做虧本生意的。",
  ui_story_5036_50360301_49_dialog_content = "她肯投入這麼多，一定是因為早已算好演唱會所能帶來的收益。",
  ui_story_5036_50360301_50_dialog_content = "可是大家只要站在金河旁邊就可以免費看到演出，她要怎麼賺錢呢？",
  ui_story_5036_50360301_51_dialog_content = "唉，可惜她已經回影鎮去做演唱會的宣傳了。",
  ui_story_5036_50360301_52_dialog_content = "下次我一定要問問她是怎麼回本的！",
  ui_story_5036_50360301_53_dialog_content = "薇絲，有時候我覺得也許妳更適合生在影鎮。",
  ui_story_5036_50360301_54_dialog_content = "一討論到白夜幣，妳就比當年在白夜城留學的課堂上還要認真。",
  ui_story_5036_50360301_55_dialog_content = "唔？那還不是托某人的福。",
  ui_story_5036_50360301_56_dialog_content = "呃，妳們看我幹嘛？",
  ui_story_5036_50360301_57_dialog_content = "哈哈，涉老闆的商業手腕可不是我們能看透的哦。",
  ui_story_5036_50360301_58_dialog_content = "我們只要盡力做好自己該做的事情就可以啦～",
  ui_story_5036_50360301_59_dialog_content = "現在歌爾蒂的任務就是，好好籌備演唱會！",
  ui_story_5036_50360301_60_dialog_content = "……",
  ui_story_5036_50360301_61_dialog_content = "PlayerName，你是在擔心什麼嗎？",
  ui_story_5036_50360301_62_dialog_content = "啊，我只是在想：歌頌者號上的螢幕和音響設備雖然沒有問題，但是僅僅依靠這些……",
  ui_story_5036_50360301_63_dialog_content = "真的可以像妳設想的那樣，讓這裡的歌聲傳遞到遙遠的地面嗎？",
  ui_story_5036_50360301_64_dialog_content = "PlayerName，你就這麼不信任你們空裔的科技嗎？",
  ui_story_5036_50360301_65_dialog_content = "相信，我當然相信！只是……",
  ui_story_5036_50360301_66_dialog_content = "好啦，我知道大家在擔心什麼。相信我，我比任何人都希望演唱會能順利舉行。",
  ui_story_5036_50360301_67_dialog_content = "我向希諾普長官請教了設備的各種問題，已經學會了如何控制設備音量。",
  ui_story_5036_50360301_68_dialog_content = "透過那些設備，我們的歌聲可以百分之百傳遞到地面的觀眾耳朵裡去哦～",
  ui_story_5036_50360301_69_dialog_content = "原來妳早就做好準備了，不愧是專業的偶像！",
  ui_story_5036_50360301_70_dialog_content = "欸，話說回來，你們不是在尋找拯救歌頌者號的方法嗎？",
  ui_story_5036_50360301_71_dialog_content = "有什麼進展嗎？",
  ui_story_5036_50360301_72_dialog_content = "完全沒有頭緒。",
  ui_story_5036_50360301_73_dialog_content = "唉，現在想想當時的自己真是無知者的自信。",
  ui_story_5036_50360301_74_dialog_content = "連啟光的科研長官都沒有辦法的事情，我是哪來的信心認為自己會有辦法的呢？",
  ui_story_5036_50360301_75_dialog_content = "PlayerName，不要說這種喪氣話嘛～",
  ui_story_5036_50360301_76_dialog_content = "要不我幫你問問我的<color=#FFB400>幸運子彈</color>吧？",
  ui_story_5036_50360301_77_dialog_content = "幸運子彈？",
  ui_story_5036_50360301_78_dialog_content = "子彈子彈，PlayerName能找到拯救歌頌者號的辦法嗎？",
  ui_story_5036_50360301_79_dialog_content = "如果可以，就請你彈頭落地吧！",
  ui_story_5036_50360301_80_dialog_content = "PlayerName，來，把子彈扔到空中試試看吧～",
  ui_story_5036_50360301_81_dialog_content = "扔到空中？像這樣嗎？",
  ui_story_5036_50360301_82_dialog_content = "<color=#e8d9bb>咻——</color>",
  ui_story_5036_50360301_83_dialog_content = "飛起來了……",
  ui_story_5036_50360301_84_dialog_content = "<color=#e8d9bb>叮！</color>",
  ui_story_5036_50360301_85_dialog_content = "太棒了，PlayerName！看，子彈是彈頭落地的哦～",
  ui_story_5036_50360301_86_dialog_content = "幸運子彈說你可以找到辦法，就一定沒問題的！",
  ui_story_5036_50360301_87_dialog_content = "真的嗎？",
  ui_story_5036_50360301_88_dialog_content = "以前每當我遇到困難，幸運子彈都能幫我找到答案。",
  ui_story_5036_50360301_89_dialog_content = "我相信，幸運子彈也會把好運帶給你的～",
  ui_story_5036_50360301_90_dialog_content = "嗯……好！總之我不會放棄的！",
  ui_story_5036_50360301_91_dialog_content = "每次聽歌爾蒂說話都會覺得幹勁滿滿。",
  ui_story_5036_50360301_92_dialog_content = "感覺我也快成為「蒂蒂人」了～",
  ui_story_5036_50360301_93_dialog_content = "哈哈，那你可要快點囉～",
  ui_story_5036_50360301_94_dialog_content = "因為我早就是資深的「空心粉」了呢。",
  ui_story_5036_50360301_95_dialog_content = "啊？",
  ui_story_5036_50360301_96_dialog_content = "<color=#e8d9bb>喀嚓！</color>",
  ui_story_5036_50360301_97_dialog_content = "欸？",
  ui_story_5036_50360301_98_dialog_content = "不......不好意思！",
  ui_story_5036_50360301_99_dialog_content = "我是覺得現在各位的氛圍很融洽，所以情不自禁地想為大家拍一張紀念照……",
  ui_story_5036_50360301_100_dialog_content = "哇，謝謝你哦～珀蘭蒂！",
  ui_story_5036_50360301_101_dialog_content = "（歌爾蒂……喊出了我的名字？）",
  ui_story_5036_50360301_102_dialog_content = "不愧是影鎮的報社，這麼快就派人來採訪演唱會的事情了嗎？",
  ui_story_5036_50360301_103_dialog_content = "其實我這次是跟著PlayerName來的……",
  ui_story_5036_50360301_104_dialog_content = "嗯，珀蘭蒂說想要採訪我。",
  ui_story_5036_50360301_105_dialog_content = "原來是這樣，這次採訪的對像是PlayerName嗎？",
  ui_story_5036_50360301_106_dialog_content = "哎呀哎呀，有點吃醋了呢。",
  ui_story_5036_50360301_107_dialog_content = "啊......那個那個……",
  ui_story_5036_50360301_108_dialog_content = "放心，珀蘭蒂，我是開玩笑的啦～",
  ui_story_5036_50360301_109_dialog_content = "……沒想到歌爾蒂還記得我。",
  ui_story_5036_50360301_110_dialog_content = "當然了，上次珀蘭蒂採訪我的報導，我有好好剪下來收藏哦～",
  ui_story_5036_50360301_111_dialog_content = "可是那篇文章寫得很爛，還被編輯老師臭罵了一頓。",
  ui_story_5036_50360301_112_dialog_content = "珀蘭蒂，我可不准妳這樣說自己哦。",
  ui_story_5036_50360301_113_dialog_content = "妳為了採訪做的準備工作，比誰都認真！",
  ui_story_5036_50360301_114_dialog_content = "不管別人怎麼說，我們都要相信自己和自己的判斷哦～",
  ui_story_5036_50360301_115_dialog_content = "……相信自己呢。",
  ui_story_5036_50360301_116_dialog_content = "果然每次都能從歌爾蒂身上獲得繼續工作下去的能量呢。",
  ui_story_5036_50360301_117_dialog_content = "不過我聽報社的前輩說，妳為了大明星劇場的演唱會，已經準備了很久。",
  ui_story_5036_50360301_118_dialog_content = "在漂流巨像上開演唱會的話，那邊的演唱會是不是就不開了？",
  ui_story_5036_50360301_119_dialog_content = "那個啊……",
  ui_story_5036_50360301_120_dialog_content = "既然有「歌頌者號」這麼大的舞台等著我，我當然不能錯過啦。",
  ui_story_5036_50360301_121_dialog_content = "畢竟以後還有很多機會在影鎮的劇場開演唱會嘛。",
  ui_story_5036_50360301_122_dialog_content = "是這樣嗎？",
  ui_story_5036_50360301_123_dialog_content = "哈哈，不過真是太好了！",
  ui_story_5036_50360301_124_dialog_content = "幸運子彈果然沒說錯，我一定會請到一位厲害的記者！",
  ui_story_5036_50360301_125_dialog_content = "欸？",
  ui_story_5036_50360301_126_dialog_content = "涉老闆剛剛還要我去請一位記者過來報導演唱會的消息，我還煩惱要去哪裡找呢。",
  ui_story_5036_50360301_127_dialog_content = "如果可以的話，希望可以請珀蘭蒂追蹤報導這次演唱會的盛況呢～",
  ui_story_5036_50360301_128_dialog_content = "不過我的要求會不會太突然了呢？",
  ui_story_5036_50360301_129_dialog_content = "妳可以考慮一下再給我答覆哦～",
  ui_story_5036_50360301_130_dialog_content = "（歌爾蒂，果然還是那個溫柔、善良的歌爾蒂！）",
  ui_story_5036_50360301_131_dialog_content = "（那個說歌爾蒂有暴力傾向的小道消息，或許是假的吧？）",
  ui_story_5036_50360301_132_dialog_content = "大家別愣在這裡了。",
  ui_story_5036_50360301_133_dialog_content = "前面好像還有一個地方需要貼海報呢，我們快過去吧！",
  ui_story_5036_50360301_134_dialog_content = "他們動作也太快了吧。",
  ui_story_5036_50360301_135_dialog_content = "這裡的走廊也都貼滿了花花綠綠的海報。",
  ui_story_5036_50360301_136_dialog_content = "唉，真是搞不懂這種所謂的偶像。",
  ui_story_5036_50360301_137_dialog_content = "只要站在台上提起嘴角笑一笑、賣個萌，就能獲得大家的喜愛和掌聲。",
  ui_story_5036_50360301_138_dialog_content = "我們這些人在這裡勤勤懇懇地工作，卻得不到任何誇獎。",
  ui_story_5036_50360301_139_dialog_content = "就是說，從來沒聽說過這種奇裝異服的偶像。",
  ui_story_5036_50360301_140_dialog_content = "唱唱歌、跳跳舞的人只會魅惑人心，哪能拯救人心呢？",
  ui_story_5036_50360301_141_dialog_content = "沒想到有一天，我竟然會同意白夜城人的觀點。",
  ui_story_5036_50360301_142_dialog_content = "唉，誰讓我們倒楣呢。",
  ui_story_5036_50360301_143_dialog_content = "他們就動動嘴皮子說要開演唱會，可防守封鎖區、清理暗鬼的是我們！",
  ui_story_5036_50360301_144_dialog_content = "也不知道怎麼回事，這兩天我覺得越來越沒精神了。",
  ui_story_5036_50360301_145_dialog_content = "可不是嗎。",
  ui_story_5036_50360301_146_dialog_content = "咳咳……",
  ui_story_5036_50360301_147_dialog_content = "！！！",
  ui_story_5036_50360301_148_dialog_content = "薇絲中尉好！",
  ui_story_5036_50360301_149_dialog_content = "卡蓮殿下貴安！",
  ui_story_5036_50360301_150_dialog_content = "免禮，辛苦你們在此處執勤了。",
  ui_story_5036_50360301_151_dialog_content = "……我們剛才不知好歹，說了很多糊塗話，還請殿下責罰！",
  ui_story_5036_50360301_152_dialog_content = "請薇絲中尉責罰！",
  ui_story_5036_50360301_153_dialog_content = "羞辱平民不是騎士該有的作為。",
  ui_story_5036_50360301_154_dialog_content = "你應怎麼做，無需我多言。",
  ui_story_5036_50360301_155_dialog_content = "歌爾蒂小姐，對不起！",
  ui_story_5036_50360301_156_dialog_content = "還有你，快去道歉呀。",
  ui_story_5036_50360301_157_dialog_content = "對......對不起，歌爾蒂小姐！",
  ui_story_5036_50360301_158_dialog_content = "出言不遜有辱騎士精神，請您用這把劍裁決我吧！",
  ui_story_5036_50360301_159_dialog_content = "好。我就懲罰你們兩個……",
  ui_story_5036_50360301_160_dialog_content = "今天早點休息，再做個甜美的夢哦！",
  ui_story_5036_50360301_161_dialog_content = "啊！？",
  ui_story_5036_50360301_162_dialog_content = "好了啦，誰工作的時候不會抱怨兩句呢。",
  ui_story_5036_50360301_163_dialog_content = "而且的確是因為我的到來，才增加了大家的工作量。",
  ui_story_5036_50360301_164_dialog_content = "該道歉的人是我啦～",
  ui_story_5036_50360301_165_dialog_content = "我已經拜託涉老闆聯繫了影鎮的傭兵團，幫大家分擔工作哦。",
  ui_story_5036_50360301_166_dialog_content = "以後大家就可以多休息一下了！",
  ui_story_5036_50360301_167_dialog_content = "這……",
  ui_story_5036_50360301_168_dialog_content = "走廊盡頭的房間裡有補充糖分的飲料，你們兩位一直在執勤，應該還沒有拿吧？",
  ui_story_5036_50360301_169_dialog_content = "快去嚐嚐吧～",
  ui_story_5036_50360301_170_dialog_content = "我保證喝完之後可以恢復精神哦！",
  ui_story_5036_50360301_171_dialog_content = "……",
  ui_story_5036_50360301_172_dialog_content = "哎呀，歌爾蒂小姐都這麼說了，還愣著幹什麼呀？",
  ui_story_5036_50360301_173_dialog_content = "卡蓮殿下……？",
  ui_story_5036_50360301_174_dialog_content = "既然歌爾蒂小姐已經懲罰過你了，那就快去吧。",
  ui_story_5036_50360301_175_dialog_content = "謝謝卡蓮殿下！謝謝歌爾蒂小姐！",
  ui_story_5036_50360301_176_dialog_content = "謝謝薇絲中尉！謝謝歌爾蒂小姐！",
  ui_story_5036_50360301_177_dialog_content = "要舉辦一場演唱會要考慮的事情果然好多。",
  ui_story_5036_50360301_178_dialog_content = "沒想到我還是忘記了考慮這些士兵的需求……",
  ui_story_5036_50360301_179_dialog_content = "歌爾蒂小姐，如果妳需要，我可以再從白夜城的騎士團抽調一些人手過來。",
  ui_story_5036_50360301_180_dialog_content = "不用不用，這怎麼好意思呢！",
  ui_story_5036_50360301_181_dialog_content = "沒關係的！正好我委託白火傭兵團來幫我運輸材料、搭建舞台。",
  ui_story_5036_50360301_182_dialog_content = "等他們來了，我再追加一些委託就好！",
  ui_story_5036_50360301_183_dialog_content = "委託白火傭兵團做這些事情，算下來可不是筆小數目。",
  ui_story_5036_50360301_184_dialog_content = "涉女士也會承擔這些費用嗎？",
  ui_story_5036_50360301_185_dialog_content = "……",
  ui_story_5036_50360301_186_dialog_content = "歌爾蒂？",
  ui_story_5036_50360301_187_dialog_content = "嗯？",
  ui_story_5036_50360301_188_dialog_content = "啊……嗯，涉老闆神通廣大，沒問題的。",
  ui_story_5036_50360301_189_dialog_content = "歌爾蒂剛才是在擔心什麼嗎？",
  ui_story_5036_50360301_190_dialog_content = "沒有啦。",
  ui_story_5036_50360301_191_dialog_content = "我只是在想白火傭兵團本來應該早就到了，可是現在還沒來……",
  ui_story_5036_50360301_192_dialog_content = "<color=#e8d9bb>噠噠噠噠……</color>",
  ui_story_5036_50360301_193_dialog_content = "腳步聲？前面是不是來了一群人？",
  ui_story_5036_50360301_194_dialog_content = "正說著呢，白火傭兵團的人就到了嗎？",
  ui_story_5036_50360301_195_dialog_content = "真是太巧了吧！哈哈哈。",
  ui_story_5036_50360301_196_dialog_content = "吼——！",
  ui_story_5036_50360301_197_dialog_content = "欸？糟糕……",
  ui_story_5036_50360301_198_dialog_content = "我認錯人了！",
  ui_story_5036_50360301_199_dialog_content = "我請來幫忙的傭兵可不是暗鬼呀？",
  ui_story_5036_50360302_1_dialog_content = "歌爾蒂，小心身後！",
  ui_story_5036_50360302_2_dialog_content = "欸？",
  ui_story_5036_50360302_3_dialog_content = "吼！",
  ui_story_5036_50360302_4_dialog_content = "消失吧！",
  ui_story_5036_50360302_5_dialog_content = "白火傭兵團，你們來了！",
  ui_story_5036_50360302_6_dialog_content = "歌爾蒂小姐！妳沒事吧？",
  ui_story_5036_50360302_7_dialog_content = "我沒事哦，幸虧你們及時趕來幫忙呢。",
  ui_story_5036_50360302_8_dialog_content = "也算不上及時。",
  ui_story_5036_50360302_9_dialog_content = "準備搭建舞台的材料比預想中多花了點時間，所以很抱歉我們現在才趕到。",
  ui_story_5036_50360302_10_dialog_content = "但我沒想到漂流巨像上竟然也有暗鬼？",
  ui_story_5036_50360302_11_dialog_content = "其實……我也是上來之後才知道這件事。",
  ui_story_5036_50360302_12_dialog_content = "不過啟光和白夜城的士兵，已經把大部分的暗鬼趕到了漂流巨像尾部的封鎖區。",
  ui_story_5036_50360302_13_dialog_content = "雖然各個地方還有一些流竄的暗鬼，但是如你所見……",
  ui_story_5036_50360302_14_dialog_content = "它們的殺傷力並不大。",
  ui_story_5036_50360302_15_dialog_content = "啟光和白夜城的士兵，已經加強了對流竄暗鬼的清除力道。",
  ui_story_5036_50360302_16_dialog_content = "再加上你們白火傭兵團的幫忙……",
  ui_story_5036_50360302_17_dialog_content = "相信不只是這些流竄的暗鬼，封鎖區的暗鬼們也很快會被清除乾淨的。",
  ui_story_5036_50360302_18_dialog_content = "涉老闆的委託，我們一定竭盡全力。",
  ui_story_5036_50360302_19_dialog_content = "包在我們身上吧！",
  ui_story_5036_50360302_20_dialog_content = "那就拜託大家啦～",
  ui_story_5036_50360302_21_dialog_content = "歌爾蒂小姐不用客氣，我們在影鎮就聽說……",
  ui_story_5036_50360302_22_dialog_content = "好像已經有不少人報名參加演唱會了？",
  ui_story_5036_50360302_23_dialog_content = "消息傳得還真快呢～",
  ui_story_5036_50360302_24_dialog_content = "是真的哦！大家的熱情遠超我的想像。",
  ui_story_5036_50360302_25_dialog_content = "所以在正式演出之前，我們還要舉辦幾場<color=#FFB400>偶像海選</color>。",
  ui_story_5036_50360302_26_dialog_content = "來選出能夠真正登上舞台、表演節目的偶像們。",
  ui_story_5036_50360302_27_dialog_content = "偶像海選？感覺會很熱鬧啊。",
  ui_story_5036_50360302_28_dialog_content = "明天就會舉辦第一場海選，還要麻煩你們調幾個人維持現場秩序了。",
  ui_story_5036_50360302_29_dialog_content = "沒問題！",
  ui_story_5036_50360302_30_dialog_content = "弟兄們，要忙起來啦！",
  ui_story_5036_50360302_31_dialog_content = "哦——！",
  ui_story_5036_50360302_32_dialog_content = "歌爾蒂的行動力還真是強啊。",
  ui_story_5036_50360302_33_dialog_content = "偶像海選？聽上去要花費不少精力吧？",
  ui_story_5036_50360302_34_dialog_content = "這是我一直以來都想做的事，難得有這樣的機會可以實現我的夢想。",
  ui_story_5036_50360302_35_dialog_content = "我一點都不會覺得辛苦哦～",
  ui_story_5036_50360302_36_dialog_content = "歌爾蒂一直都想要舉辦偶像海選？",
  ui_story_5036_50360302_37_dialog_content = "沒錯哦。我熱愛著舞台，也熱愛著台下的觀眾。",
  ui_story_5036_50360302_38_dialog_content = "我希望能把我的這份熱愛傳遞下去！",
  ui_story_5036_50360302_39_dialog_content = "希望有更多的偶像能為觀眾帶來感動和希望。",
  ui_story_5036_50360302_40_dialog_content = "所以我要趁我還有能力的時候，見證更多像我一樣的男孩和女孩成為偶像！",
  ui_story_5036_50360302_41_dialog_content = "歌爾蒂是真的很熱愛自己的這份事業啊。",
  ui_story_5036_50360302_42_dialog_content = "說起這個……",
  ui_story_5036_50360302_43_dialog_content = "PlayerName，不知道你有沒有興趣成為偶像海選的<color=#FFB400>評審</color>呀？",
  ui_story_5036_50360302_44_dialog_content = "評審？我？",
  ui_story_5036_50360302_45_dialog_content = "對哦！評審的任務說起來也很簡單。",
  ui_story_5036_50360302_46_dialog_content = "就是觀看報名選手的節目，根據自己的喜好判斷選手能否站在最終舞台上。",
  ui_story_5036_50360302_47_dialog_content = "本來這個評審的位子要留給涉老闆，但是她好像因為宣傳的事變得很忙。",
  ui_story_5036_50360302_48_dialog_content = "想來想去，只有PlayerName最合適了呢。",
  ui_story_5036_50360302_49_dialog_content = "可是我，真的沒有信心。",
  ui_story_5036_50360302_50_dialog_content = "對了！卡蓮、薇絲，妳們不是也挺喜歡唱歌的嘛。",
  ui_story_5036_50360302_51_dialog_content = "有沒有興趣成為評審？",
  ui_story_5036_50360302_52_dialog_content = "呃……",
  ui_story_5036_50360302_53_dialog_content = "唔……",
  ui_story_5036_50360302_54_dialog_content = "哈哈哈，PlayerName還不知道嗎？",
  ui_story_5036_50360302_55_dialog_content = "薇絲小姐和卡蓮殿下也已經報名參加偶像海選了哦～",
  ui_story_5036_50360302_56_dialog_content = "欸！？",
  ui_story_5036_50360302_57_dialog_content = "為什麼我完全不知道！",
  ui_story_5036_50360302_58_dialog_content = "這個可不能怪我們，我們真的有告訴過你。",
  ui_story_5036_50360302_59_dialog_content = "但是你當時一直在說好像聽到了什麼歌聲，完全不理我們。",
  ui_story_5036_50360302_60_dialog_content = "我和薇絲商量過了，如果演唱會能成功舉辦，也許就能證明歌頌者號是有價值的。",
  ui_story_5036_50360302_61_dialog_content = "從而說服啟光高層和我的父親，不去破壞它。",
  ui_story_5036_50360302_62_dialog_content = "就算最後我們還是找不到控制巨像的辦法……",
  ui_story_5036_50360302_63_dialog_content = "起碼歌頌者號還可以繼續像現在一樣漫無目的地航行下去。",
  ui_story_5036_50360302_64_dialog_content = "說不定再過一百年，歌頌者號又能回到艾斯特拉大陸的上空呢！",
  ui_story_5036_50360302_65_dialog_content = "原來妳們兩位已經想到這一步了？",
  ui_story_5036_50360302_66_dialog_content = "其實我們差一點也要幫你報名了，可是後來想了想……",
  ui_story_5036_50360302_67_dialog_content = "嗯，果然還是算了。",
  ui_story_5036_50360302_68_dialog_content = "雖然我對表演不是很有信心，但是也用不著說出來吧？",
  ui_story_5036_50360302_69_dialog_content = "當評審也不一定要會表演嘛。",
  ui_story_5036_50360302_70_dialog_content = "只要有一雙善於發現的眼睛，就可以成為合格的評審哦～",
  ui_story_5036_50360302_71_dialog_content = "嗯……",
  ui_story_5036_50360302_72_dialog_content = "唉，只有這個辦法了。",
  ui_story_5036_50360302_73_dialog_content = "真是沒想到啊。",
  ui_story_5036_50360302_74_dialog_content = "我都這把年紀了，還要來幹這種事。",
  ui_story_5036_50360302_75_dialog_content = "嗷！",
  ui_story_5036_50360302_76_dialog_content = "噓！",
  ui_story_5036_50360302_77_dialog_content = "<size=35>嗚？</size>",
  ui_story_5036_50360302_78_dialog_content = "好龍龍，已經很晚啦。",
  ui_story_5036_50360302_79_dialog_content = "發出那麼大的聲音可是會嚇到別人的。",
  ui_story_5036_50360302_80_dialog_content = "我可不想一出場就這麼扎眼啊。",
  ui_story_5036_50360302_81_dialog_content = "嗚……",
  ui_story_5036_50360302_82_dialog_content = "好了，快點回去找菲雅吧。",
  ui_story_5036_50360302_83_dialog_content = "但是記得……",
  ui_story_5036_50360302_84_dialog_content = "千萬別透露我的行蹤。",
  ui_story_5036_50360401_1_dialog_content = "編輯老師，是我！",
  ui_story_5036_50360401_2_dialog_content = "不說名字我怎麼知道妳是誰？",
  ui_story_5036_50360401_3_dialog_content = "……是珀蘭蒂。",
  ui_story_5036_50360401_4_dialog_content = "哦，我想起來了。",
  ui_story_5036_50360401_5_dialog_content = "就是那個只會寫無聊報導的實習記者吧？",
  ui_story_5036_50360401_6_dialog_content = "我還以為妳已經收拾行李不幹了。",
  ui_story_5036_50360401_7_dialog_content = "上次您說再給我最後一次機會。",
  ui_story_5036_50360401_8_dialog_content = "哦，好像是有這麼回事。怎麼，有什麼好消息？",
  ui_story_5036_50360401_9_dialog_content = "嗯！編輯老師，您知道嗎？",
  ui_story_5036_50360401_10_dialog_content = "我現在在歌頌者號……就是大家說的那艘漂流巨像上！",
  ui_story_5036_50360401_11_dialog_content = "所以呢？",
  ui_story_5036_50360401_12_dialog_content = "等到這艘巨像漂流到影鎮上空時，會舉辦一場大型的演唱會！",
  ui_story_5036_50360401_13_dialog_content = "我時間很緊，能不能說點我不知道的？",
  ui_story_5036_50360401_14_dialog_content = "哦，那個。",
  ui_story_5036_50360401_15_dialog_content = "我被委派擔任這次演唱會的指定記者，還會幫大家主持偶像海選！",
  ui_story_5036_50360401_16_dialog_content = "哼，報導這種官方消息就這麼讓妳覺得驕傲嗎？",
  ui_story_5036_50360401_17_dialog_content = "看來妳還是沒搞懂。",
  ui_story_5036_50360401_18_dialog_content = "我要的是足夠勁爆、足夠吸睛的東西！",
  ui_story_5036_50360401_19_dialog_content = "欸，老師！老師？",
  ui_story_5036_50360401_20_dialog_content = "……勁爆的消息嗎。",
  ui_story_5036_50360401_21_dialog_content = "<color=#e8d9bb>距離演唱會開始還有五天</color>",
  ui_story_5036_50360401_22_dialog_content = "親愛的選手們，大家久等啦！",
  ui_story_5036_50360401_23_dialog_content = "歡迎大家來到<color=#FFB400>群星閃耀之刻·天空演唱會</color>的海選現場。",
  ui_story_5036_50360401_24_dialog_content = "能夠通過報名審核、乘坐專用飛空艇登上這艘巨像，有什麼感想呢？",
  ui_story_5036_50360401_25_dialog_content = "激動？興奮？緊張？刺激？",
  ui_story_5036_50360401_26_dialog_content = "不過更緊張、更刺激的還在後頭。",
  ui_story_5036_50360401_27_dialog_content = "我宣布，第一場海選馬上就要開始啦！",
  ui_story_5036_50360401_28_dialog_content = "哦——！終於要開始了！！",
  ui_story_5036_50360401_29_dialog_content = "大家稍安勿躁，我先來為大家介紹一下海選的規則。",
  ui_story_5036_50360401_30_dialog_content = "各位可以看到，海選的現場共有六位評審老師。",
  ui_story_5036_50360401_31_dialog_content = "歡迎找我來交流養成遊戲的快樂哦，呼呼呼。",
  ui_story_5036_50360401_32_dialog_content = "唱歌、跳舞、顏值、身材、情商、智商，這六項就是我的評分標準。",
  ui_story_5036_50360401_33_dialog_content = "只要有一項出眾，就會得到我的關注。",
  ui_story_5036_50360401_34_dialog_content = "我想看到純潔的、唯美的、高尚的、一塵不染的、洗滌心靈的節目……",
  ui_story_5036_50360401_35_dialog_content = "你，能否做到？",
  ui_story_5036_50360401_36_dialog_content = "大家加油。",
  ui_story_5036_50360401_37_dialog_content = "希望可以和閃耀的你一起登上天空的舞台，綻放光芒～",
  ui_story_5036_50360401_38_dialog_content = "大家好，我會認真觀看大家的表演的！",
  ui_story_5036_50360401_39_dialog_content = "我們的規則很簡單，只要獲得四位評審投票……",
  ui_story_5036_50360401_40_dialog_content = "就可以進入複賽，角逐最終的登台機會。",
  ui_story_5036_50360401_41_dialog_content = "而獲得六位評審一致通過的選手，將直接獲得天空演唱會的演出機會！",
  ui_story_5036_50360401_42_dialog_content = "沒有晉級的選手也不用灰心，每個人都有三次參加海選的機會。",
  ui_story_5036_50360401_43_dialog_content = "大家可以盡情使用歌頌者號上的排練室進行訓練。",
  ui_story_5036_50360401_44_dialog_content = "那麼事不宜遲，讓我們趕快開始今天的海選吧～",
  ui_story_5036_50360401_45_dialog_content = "接下來，請念到報名編號的選手上前開始表演！",
  ui_story_5036_50360401_46_dialog_content = "1號選手，啟光合唱團！",
  ui_story_5036_50360401_47_dialog_content = "海選已經開始了，不去看看嗎？",
  ui_story_5036_50360401_48_dialog_content = "嗯，還是先不看了吧。",
  ui_story_5036_50360401_49_dialog_content = "我還沒有想好到底要表演什麼。",
  ui_story_5036_50360401_50_dialog_content = "現在去看其他人的表演，可能會讓我更加緊張。",
  ui_story_5036_50360401_51_dialog_content = "其實我也還沒想好。",
  ui_story_5036_50360401_52_dialog_content = "我們報名的時候，只是擔心報名的選手不夠，演唱會無法順利舉辦。",
  ui_story_5036_50360401_53_dialog_content = "現在有這麼多人聚集在這裡，我反而覺得……",
  ui_story_5036_50360401_54_dialog_content = "或許不用我出場也可以。",
  ui_story_5036_50360401_55_dialog_content = "欸？聽說啟光和白夜城都有一個內定名額。",
  ui_story_5036_50360401_56_dialog_content = "啟光推選了啟光合唱團，我還以為白夜城的名額會是妳？",
  ui_story_5036_50360401_57_dialog_content = "謝謝，我們的表演到此結束！",
  ui_story_5036_50360401_58_dialog_content = "你們的動作整齊、精神昂揚，歌曲內容振奮人心，展現了我們啟光士兵的風範！",
  ui_story_5036_50360401_59_dialog_content = "我知道這個合唱團經常在啟光各地巡迴表演，所以台風非常成熟穩健。",
  ui_story_5036_50360401_60_dialog_content = "我很喜歡你們的合唱，加油！",
  ui_story_5036_50360401_61_dialog_content = "謝謝評審的點評。",
  ui_story_5036_50360401_62_dialog_content = "1號選手啟光合唱團最終得票數是——",
  ui_story_5036_50360401_63_dialog_content = "6票全票！",
  ui_story_5036_50360401_64_dialog_content = "他們頂住了第一個出場的壓力，順利得到了演唱會的演出機會！恭喜他們！",
  ui_story_5036_50360401_65_dialog_content = "謝謝各位評審，我們一定不會辜負大家的期望！",
  ui_story_5036_50360401_66_dialog_content = "好的，接下來讓我們有請2號選手——白夜城唱詩班，基汀！",
  ui_story_5036_50360401_67_dialog_content = "原來如此。",
  ui_story_5036_50360401_68_dialog_content = "可是這麼難得的機會，如果放棄的話不會覺得很可惜嗎？",
  ui_story_5036_50360401_69_dialog_content = "正是因為機會難得，所以才更應該讓給想要的人去爭取。",
  ui_story_5036_50360401_70_dialog_content = "什麼嘛。",
  ui_story_5036_50360401_71_dialog_content = "嗯？",
  ui_story_5036_50360401_72_dialog_content = "到頭來只有我一個人參加海選嗎？",
  ui_story_5036_50360401_73_dialog_content = "哦～我知道了！",
  ui_story_5036_50360401_74_dialog_content = "到時候在白夜城也可以看到歌頌者號的舞台……",
  ui_story_5036_50360401_75_dialog_content = "卡蓮妳不會是不好意思在家門口表演吧？",
  ui_story_5036_50360401_76_dialog_content = "我沒有那個意思……",
  ui_story_5036_50360401_77_dialog_content = "那就證明給大家看吧。",
  ui_story_5036_50360401_78_dialog_content = "妳真正的實力。",
  ui_story_5036_50360401_79_dialog_content = "這就是♪",
  ui_story_5036_50360401_80_dialog_content = "我們的表演♪",
  ui_story_5036_50360401_81_dialog_content = "請開始♪",
  ui_story_5036_50360401_82_dialog_content = "你們的表演♪",
  ui_story_5036_50360401_83_dialog_content = "難以置信的優雅！",
  ui_story_5036_50360401_84_dialog_content = "不愧是舒瓦茲殿下親自欽選的孩子們！",
  ui_story_5036_50360401_85_dialog_content = "他們的歌聲彷彿天籟，將我由內而外地洗滌乾淨。",
  ui_story_5036_50360401_86_dialog_content = "其他地方的庶民啊，你們暗自慶幸吧。",
  ui_story_5036_50360401_87_dialog_content = "能夠聽到這樣神聖的歌曲，可是光之神對你們的恩澤。",
  ui_story_5036_50360401_88_dialog_content = "大人的表演♪",
  ui_story_5036_50360401_89_dialog_content = "真可笑♪",
  ui_story_5036_50360401_90_dialog_content = "嘴裡的說辭♪",
  ui_story_5036_50360401_91_dialog_content = "一套套♪",
  ui_story_5036_50360401_92_dialog_content = "聽啊，這群孩子就連平時講話也會加上悅耳的曲調！",
  ui_story_5036_50360401_93_dialog_content = "完全聽不出，是諷刺？",
  ui_story_5036_50360401_94_dialog_content = "這是什麼情況？",
  ui_story_5036_50360401_95_dialog_content = "基汀也得到了6票全票，直接獲得演出機會！恭喜他們！",
  ui_story_5036_50360401_96_dialog_content = "前兩個都是6票？喂！該不會是有什麼內幕吧？",
  ui_story_5036_50360401_97_dialog_content = "請問妳是3號選手——芭芭拉嗎？",
  ui_story_5036_50360401_98_dialog_content = "芭芭拉在這裡哦！",
  ui_story_5036_50360401_99_dialog_content = "不要理會那個只會發出噪音的女人，芭芭拉才是真正為偶像舞台而生的人！",
  ui_story_5036_50360401_100_dialog_content = "呵，妳還是先練習一下音準再上台吧。",
  ui_story_5036_50360401_101_dialog_content = "有空擔心我，不如先學學怎麼唱歌吧？",
  ui_story_5036_50360401_102_dialog_content = "兩位選手，該上台了。",
  ui_story_5036_50360401_103_dialog_content = "真是不想承認啊。",
  ui_story_5036_50360401_104_dialog_content = "紅油扳手怎麼會有妳這種只會唱老土情歌的人？",
  ui_story_5036_50360401_105_dialog_content = "不會吧？不會吧？",
  ui_story_5036_50360401_106_dialog_content = "妳以為紅油扳手裡真有人欣賞妳的破嗓子嗎？",
  ui_story_5036_50360401_107_dialog_content = "哈？妳說什麼？",
  ui_story_5036_50360401_108_dialog_content = "妳敢再說一遍！？",
  ui_story_5036_50360401_109_dialog_content = "欸，怎麼已經有人上台表演了？",
  ui_story_5036_50360401_110_dialog_content = "明明芭芭拉才是3號選手！",
  ui_story_5036_50360401_111_dialog_content = "抱歉……3號選手芭芭拉、4號選手蕾吉娜。",
  ui_story_5036_50360401_112_dialog_content = "因為違反會場紀律，妳們兩位已被評審請出了本輪海選。",
  ui_story_5036_50360401_113_dialog_content = "請重新報名下一場海選吧。",
  ui_story_5036_50360401_114_dialog_content = "哈！？",
  ui_story_5036_50360401_115_dialog_content = "噢，我知道了。",
  ui_story_5036_50360401_116_dialog_content = "妳……妳知道什麼了？",
  ui_story_5036_50360401_117_dialog_content = "薇絲是因為要一個人參加海選，覺得孤單了嗎？",
  ui_story_5036_50360401_118_dialog_content = "唔，小聲一點啦……",
  ui_story_5036_50360401_119_dialog_content = "好吧，我承認。",
  ui_story_5036_50360401_120_dialog_content = "畢竟我們幾個以前總是一起行動的嘛。",
  ui_story_5036_50360401_121_dialog_content = "忽然變成我的單獨行動，我還是多少會有那麼一點點寂寞的啦。",
  ui_story_5036_50360401_122_dialog_content = "嗯，好吧。",
  ui_story_5036_50360401_123_dialog_content = "那我就勉為其難地陪陪某個寂寞小鬼吧。",
  ui_story_5036_50360401_124_dialog_content = "我才不是寂寞小鬼呢！",
  ui_story_5036_50360401_125_dialog_content = "哈哈哈……",
  ui_story_5036_50360401_126_dialog_content = "呼～不過，比起獨自站在舞台上……",
  ui_story_5036_50360401_127_dialog_content = "我更懷念和妳一起站在舞台上的感覺呢。",
  ui_story_5036_50360401_128_dialog_content = "欸？",
  ui_story_5036_50360401_129_dialog_content = "忽然開始懷念過去是為什麼呀，哈哈哈。",
  ui_story_5036_50360401_130_dialog_content = "嗯，總覺得那個時候的自己，會更有動力去完成表演。",
  ui_story_5036_50360401_131_dialog_content = "其實，我也……",
  ui_story_5036_50360401_132_dialog_content = "真是太遺憾了。",
  ui_story_5036_50360401_133_dialog_content = "除了1號和2號選手，今天其他的選手都沒能得到演唱會的入場券嗎？",
  ui_story_5036_50360401_134_dialog_content = "接下來，就讓我們歡迎今天最後一位選手。",
  ui_story_5036_50360401_135_dialog_content = "看看他會給我們帶來什麼樣的表現！",
  ui_story_5036_50360401_136_dialog_content = "各位評審老師們，大家好啊。",
  ui_story_5036_50360401_137_dialog_content = "我是維克，平時的職業是神奇動物訓練師。",
  ui_story_5036_50360401_138_dialog_content = "維克！？",
  ui_story_5036_50360401_139_dialog_content = "欸？是PlayerName？",
  ui_story_5036_50360401_140_dialog_content = "哈哈哈，評審裡竟然有我認識的熟人呢。",
  ui_story_5036_50360401_141_dialog_content = "事先聲明，我可是真的不清楚評審是PlayerName哦。",
  ui_story_5036_50360401_142_dialog_content = "真的是你？",
  ui_story_5036_50360401_143_dialog_content = "我還以為是自己眼花了！你怎麼也來參加海選了？",
  ui_story_5036_50360401_144_dialog_content = "我當然想成為一名偶像，在這難得的舞台上演出一回嘛。",
  ui_story_5036_50360401_145_dialog_content = "我從來不知道你還想成為偶像？",
  ui_story_5036_50360401_146_dialog_content = "據我所知，你在神奇動物訓練師這一行，應該已經頗有建樹了吧？",
  ui_story_5036_50360401_147_dialog_content = "哎呀，有誰規定神奇動物訓練師不可以成為偶像嗎？",
  ui_story_5036_50360401_148_dialog_content = "要我說呀！",
  ui_story_5036_50360401_149_dialog_content = "在我們這個時代，誰都有機會成為偶像……",
  ui_story_5036_50360401_150_dialog_content = "在屬於自己的舞台上，發光發熱那麼一下下。",
  ui_story_5036_50360401_151_dialog_content = "「在我們這個時代，誰都有機會成為偶像」嗎？",
  ui_story_5036_50360401_152_dialog_content = "人人都有機會成為偶像，說得太好了。",
  ui_story_5036_50360401_153_dialog_content = "我非常欣賞你對「偶像」的態度和見解，也很期待你接下來的表演！",
  ui_story_5036_50360401_154_dialog_content = "哇！到目前為止，這還是第一位吸引到歌爾蒂小姐的選手呢！",
  ui_story_5036_50360401_155_dialog_content = "他究竟會帶來什麼樣的精彩演出呢？",
  ui_story_5036_50360401_156_dialog_content = "維克選手，請開始你的表演吧。",
  ui_story_5036_50360401_157_dialog_content = "我想為大家帶來一段美文朗誦。咳咳……",
  ui_story_5036_50360401_158_dialog_content = "啊！春天到了，萬物復甦～",
  ui_story_5036_50360401_159_dialog_content = "又到了，神奇動物展現生命力的季節。",
  ui_story_5036_50360401_160_dialog_content = "（這......這種節目也可以嗎？）",
  ui_story_5036_50360401_161_dialog_content = "（不過維克朗誦的內容聽上去似乎是自己寫的《神奇動物大全》？）",
  ui_story_5036_50360401_162_dialog_content = "看哪！無論是森林之中還是荒原之上，到處都洋溢著生機勃勃的歡樂氣息。",
  ui_story_5036_50360401_163_dialog_content = "但在這種時候，有一種神奇動物卻格外冷靜。",
  ui_story_5036_50360401_164_dialog_content = "<color=#FFB400>銜尾龍</color>，艾斯特拉大陸上最為<color=#FFB400>長壽</color>的神奇動物之一。",
  ui_story_5036_50360401_165_dialog_content = "它們在成長到成熟狀態後……",
  ui_story_5036_50360401_166_dialog_content = "不好意思，打斷一下！",
  ui_story_5036_50360401_167_dialog_content = "評審們想問一下你還有其他想要展示的節目嗎？",
  ui_story_5036_50360401_168_dialog_content = "真是不好意思呢，今天我只準備了這段美文朗誦。",
  ui_story_5036_50360401_169_dialog_content = "是這樣嗎？太遺憾了。",
  ui_story_5036_50360401_170_dialog_content = "你的這段美文朗誦很有表現力，只是節目形式和內容都和我們的演唱會不太符合。",
  ui_story_5036_50360401_171_dialog_content = "不過你千萬不要灰心哦！",
  ui_story_5036_50360401_172_dialog_content = "以我的經驗來看，你的聲音條件非常好，外形條件也十分出眾。",
  ui_story_5036_50360401_173_dialog_content = "如果你能換一個唱跳類的節目，一定可以取得不凡的成績。",
  ui_story_5036_50360401_174_dialog_content = "甚至匹敵活躍在演藝界的前輩們，也是很有可能的哦！",
  ui_story_5036_50360401_175_dialog_content = "希望可以在之後的海選，看到你帶來不一樣的節目。",
  ui_story_5036_50360401_176_dialog_content = "我非常看好你的發展，加油唷！",
  ui_story_5036_50360401_177_dialog_content = "哦，那我只好再加油一下試試了。",
  ui_story_5036_50360401_178_dialog_content = "（歌爾蒂看維克的眼神，就好像是發現了什麼寶藏般？）",
  ui_story_5036_50360401_179_dialog_content = "（難道維克真的在當偶像這件事上很有天分！？）",
  ui_story_5036_50360401_180_dialog_content = "辛苦各位選手和評審老師了，今天的海選到此為止～",
  ui_story_5036_50360401_181_dialog_content = "請大家繼續支持我們接下來的幾場海選吧。",
  ui_story_5036_50360401_182_dialog_content = "我們明天再見！",
  ui_story_5036_50360401_183_dialog_content = "PlayerName、歌爾蒂小姐，海選結束了？",
  ui_story_5036_50360401_184_dialog_content = "嗯，本來以為可以用輕鬆的心態看大家表演，沒想到這麼看一天也還是挺累的。",
  ui_story_5036_50360401_185_dialog_content = "話說，怎麼沒看到妳們出場？",
  ui_story_5036_50360401_186_dialog_content = "我們還想要再一起排練一下，等準備好了再去參加海選。",
  ui_story_5036_50360401_187_dialog_content = "一起排練？",
  ui_story_5036_50360401_188_dialog_content = "沒錯哦，想來想去還是覺得兩個人一起表演比較有趣呢。",
  ui_story_5036_50360401_189_dialog_content = "不用瞪大眼睛了，PlayerName，你沒有聽錯。",
  ui_story_5036_50360401_190_dialog_content = "我和薇絲要組一個雙人組合一起表演。",
  ui_story_5036_50360401_191_dialog_content = "雙人組合，這個想法很好耶！",
  ui_story_5036_50360401_192_dialog_content = "有想好要表演什麼節目嗎？",
  ui_story_5036_50360401_193_dialog_content = "我們打算唱歌，已經想好幾首備選曲目了。",
  ui_story_5036_50360401_194_dialog_content = "不過還是要實際練習一下，才能決定究竟該選哪一首。",
  ui_story_5036_50360401_195_dialog_content = "真不知道我們還來不來得及……",
  ui_story_5036_50360401_196_dialog_content = "不用擔心，告訴妳們一個祕密哦～",
  ui_story_5036_50360401_197_dialog_content = "其實我也還沒有選好歌曲呢，嘿嘿。",
  ui_story_5036_50360401_198_dialog_content = "歌爾蒂應該有很多自己的歌曲可以選擇吧？",
  ui_story_5036_50360401_199_dialog_content = "雖然是這樣沒錯，但是我覺得好像沒有一首適合歌頌者號的舞台。",
  ui_story_5036_50360401_200_dialog_content = "嗯，不過沒關係的。也許這兩天我就能找到靈感！",
  ui_story_5036_50360401_201_dialog_content = "妳的意思是，要為歌頌者號的舞台創作一首全新的歌曲？",
  ui_story_5036_50360401_202_dialog_content = "噓～這只是我的想法啦，哈哈哈。",
  ui_story_5036_50360401_203_dialog_content = "能不能創作出來還不一定呢，所以請大家為我保密啦。",
  ui_story_5036_50360401_204_dialog_content = "原來歌爾蒂的歌曲都是自己創作的嗎？",
  ui_story_5036_50360401_205_dialog_content = "太厲害了吧！",
  ui_story_5036_50360401_206_dialog_content = "也不是所有的歌都是自己寫的啦。",
  ui_story_5036_50360401_207_dialog_content = "只是偶爾，腦海中會突然出現一段旋律。",
  ui_story_5036_50360401_208_dialog_content = "我會想辦法把旋律記錄下來，再譜成一首完整的歌曲。",
  ui_story_5036_50360401_209_dialog_content = "但不是所有時候，我想要的旋律都能在腦海中湧現的。",
  ui_story_5036_50360401_210_dialog_content = "在腦海中湧現的……旋律？",
  ui_story_5036_50360401_211_dialog_content = "♪嗚嗚嗚嗚……♪",
  ui_story_5036_50360401_212_dialog_content = "♪哦啦啦啦……♪",
  ui_story_5036_50360401_213_dialog_content = "那個，其實自從靠近歌頌者號之後，我的腦海裡倒是經常湧現一些旋律。",
  ui_story_5036_50360401_214_dialog_content = "不過與其說是旋律，不如說是有人在輕聲哼唱。",
  ui_story_5036_50360401_215_dialog_content = "欸！？真的嗎？",
  ui_story_5036_50360401_216_dialog_content = "我聽說空裔是熱愛音樂的族群！",
  ui_story_5036_50360401_217_dialog_content = "也許PlayerName天生就有音樂方面的創作才華呀！",
  ui_story_5036_50360401_218_dialog_content = "是……是嗎？",
  ui_story_5036_50360401_219_dialog_content = "難道這是歌頌者號給我的靈感？",
  ui_story_5036_50360401_220_dialog_content = "很有可能呀！",
  ui_story_5036_50360401_221_dialog_content = "欸，對啊。",
  ui_story_5036_50360401_222_dialog_content = "歌頌者號本來就是空裔一族的遺產。",
  ui_story_5036_50360401_223_dialog_content = "如果我能在歌頌者號的舞台上演唱空裔譜下的樂曲，這不是更有意義嗎！",
  ui_story_5036_50360401_224_dialog_content = "PlayerName！",
  ui_story_5036_50360401_225_dialog_content = "如果你不介意的話，可以讓我聽聽你腦海中的旋律嗎？",
  ui_story_5036_50360401_226_dialog_content = "當然不會介意了。",
  ui_story_5036_50360401_227_dialog_content = "站住——！",
  ui_story_5036_50360401_228_dialog_content = "嗯？發生什麼事了？",
  ui_story_5036_50360401_229_dialog_content = "吼！",
  ui_story_5036_50360401_230_dialog_content = "PlayerName，看來只能等一會兒再聽你哼唱旋律了！",
  ui_story_5036_50360402_1_dialog_content = "非常抱歉驚擾到了各位！",
  ui_story_5036_50360402_2_dialog_content = "剛才一位弟兄在封鎖區清理暗鬼的時候意外暈倒，才讓這些暗鬼趁機逃了出來。",
  ui_story_5036_50360402_3_dialog_content = "還要多謝啟光和白夜城的士兵們出手相助了。",
  ui_story_5036_50360402_4_dialog_content = "那位傭兵情況如何？有沒有受傷？",
  ui_story_5036_50360402_5_dialog_content = "請歌爾蒂小姐放心，他已經醒過來了，沒有什麼大礙。",
  ui_story_5036_50360402_6_dialog_content = "是因為讓大家清理封鎖區暗鬼的任務太繁重了嗎？",
  ui_story_5036_50360402_7_dialog_content = "我們聽從歌爾蒂小姐的建議，每個人都會有充足的休息時間，所以並沒有太辛苦。",
  ui_story_5036_50360402_8_dialog_content = "他說自己暈倒是因為沒有吃飯。",
  ui_story_5036_50360402_9_dialog_content = "我們應該有發放了伙食呢？",
  ui_story_5036_50360402_10_dialog_content = "這個嘛，好像是他的伙食被偷了，還沒來得及再領一份。",
  ui_story_5036_50360402_11_dialog_content = "被偷了？",
  ui_story_5036_50360402_12_dialog_content = "不會吧！難道我的也是？",
  ui_story_5036_50360402_13_dialog_content = "士兵，你受傷了嗎？",
  ui_story_5036_50360402_14_dialog_content = "報告薇絲中尉，我沒有受傷。",
  ui_story_5036_50360402_15_dialog_content = "只是我隨身攜帶的配給糧食也不見了。",
  ui_story_5036_50360402_16_dialog_content = "「也」不見了？",
  ui_story_5036_50360402_17_dialog_content = "是的，最近身邊的戰友們都遭遇了這種情況。",
  ui_story_5036_50360402_18_dialog_content = "大家的配給糧食莫名其妙地少了很多。",
  ui_story_5036_50360402_19_dialog_content = "我以為帶在身上就會安全一點，結果……",
  ui_story_5036_50360402_20_dialog_content = "會不會是大家在和暗鬼戰鬥的時候不小心弄丟了？",
  ui_story_5036_50360402_21_dialog_content = "我們也是這麼想的，所以沒有向上級匯報這個情況。",
  ui_story_5036_50360402_22_dialog_content = "<color=#FFB400>「幽靈小偷」</color>……一定是「幽靈小偷」幹的！",
  ui_story_5036_50360402_23_dialog_content = "「幽靈小偷」？",
  ui_story_5036_50360402_24_dialog_content = "卡蓮殿下，您有所不知，這艘巨像上有一個「幽靈小偷」！",
  ui_story_5036_50360402_25_dialog_content = "「幽靈小偷」會神不知鬼不覺地令大家暈過去。",
  ui_story_5036_50360402_26_dialog_content = "然後神不知鬼不覺地偷走大家身上值錢的珠寶！",
  ui_story_5036_50360402_27_dialog_content = "我身上的寶石懷錶就是這麼丟失的。",
  ui_story_5036_50360402_28_dialog_content = "偷竊食物和珠寶？",
  ui_story_5036_50360402_29_dialog_content = "這些行為聽上去的確不像是暗鬼所為。",
  ui_story_5036_50360402_30_dialog_content = "小偷嗎……",
  ui_story_5036_50360402_31_dialog_content = "為什麼這小偷的作案風格聽起來有點耳熟呢？",
  ui_story_5036_50360402_32_dialog_content = "我是在哪遇見過這種情況來著……",
  ui_story_5036_50360402_33_dialog_content = "難道是漂流巨像上混進了一個偷盜慣犯？",
  ui_story_5036_50360402_34_dialog_content = "歌爾蒂小姐，其實我們傭兵團的弟兄們也遇到了同樣的怪事。",
  ui_story_5036_50360402_35_dialog_content = "不只是我們，就連報名參賽的選手們也抱怨遺失了很多糖果和酒水。",
  ui_story_5036_50360402_36_dialog_content = "可惡，為什麼連在天上也有跑來為非作歹的壞蛋！？",
  ui_story_5036_50360402_37_dialog_content = "歌爾蒂，我很擔心這個小偷會影響參賽選手的情緒。",
  ui_story_5036_50360402_38_dialog_content = "卡蓮說得對，當務之急，是不能讓選手們因為這個小偷，失去對演唱會主辦方的信任。",
  ui_story_5036_50360402_39_dialog_content = "傭兵，麻煩你再安排一個人去影鎮採購一批食物和飲料。",
  ui_story_5036_50360402_40_dialog_content = "確保歌頌者號上的參賽選手和士兵們都能吃上東西。",
  ui_story_5036_50360402_41_dialog_content = "這麼大的量，恐怕要多派幾個人了。",
  ui_story_5036_50360402_42_dialog_content = "辛苦你了，可以把這筆錢也記在帳上。",
  ui_story_5036_50360402_43_dialog_content = "好的！",
  ui_story_5036_50360402_44_dialog_content = "……",
  ui_story_5036_50360402_45_dialog_content = "歌爾蒂，妳還好嗎？",
  ui_story_5036_50360402_46_dialog_content = "……",
  ui_story_5036_50360402_47_dialog_content = "歌爾蒂？",
  ui_story_5036_50360402_48_dialog_content = "啊？……嗯！不用擔心我哦。",
  ui_story_5036_50360402_49_dialog_content = "卡蓮小姐和薇絲小姐也安心排練節目吧，不用操心這件事哦～",
  ui_story_5036_50360402_50_dialog_content = "我一定……",
  ui_story_5036_50360402_51_dialog_content = "我一定不會允許任何人影響演唱會的舉行！",
  ui_story_5036_50360501_1_dialog_content = "傭兵……",
  ui_story_5036_50360501_2_dialog_content = "你們是怎麼搞的！",
  ui_story_5036_50360501_3_dialog_content = "這裡的舞台也搭建得太夢幻了吧！",
  ui_story_5036_50360501_4_dialog_content = "不僅把歌頌者號的螢幕洗刷如新，還架設了這些可以變換色彩的燈光！",
  ui_story_5036_50360501_5_dialog_content = "不瞞你們說哦。",
  ui_story_5036_50360501_6_dialog_content = "這座舞台比我在影鎮見過的任何舞台都要讓人情緒澎湃！",
  ui_story_5036_50360501_7_dialog_content = "感謝歌爾蒂小姐的肯定。",
  ui_story_5036_50360501_8_dialog_content = "我們只是按照涉老闆的吩咐幹活而已。",
  ui_story_5036_50360501_9_dialog_content = "那可不一樣。",
  ui_story_5036_50360501_10_dialog_content = "涉老闆說過喔，隨便應付、得過且過的傭兵團才是大多數。",
  ui_story_5036_50360501_11_dialog_content = "只有你們白火傭兵團每次都非常細心認真，非常值得信賴呢。",
  ui_story_5036_50360501_12_dialog_content = "可惜……",
  ui_story_5036_50360501_13_dialog_content = "可惜這麼漂亮的舞台，只能用這麼一次。",
  ui_story_5036_50360501_14_dialog_content = "如果歌爾蒂小姐需要的話……",
  ui_story_5036_50360501_15_dialog_content = "以後我們可以為您在影鎮搭建一座一模一樣的舞台。",
  ui_story_5036_50360501_16_dialog_content = "以後嗎？",
  ui_story_5036_50360501_17_dialog_content = "如果到那個時候我還能繼續做偶像的話……",
  ui_story_5036_50360501_18_dialog_content = "嗯？",
  ui_story_5036_50360501_19_dialog_content = "不說這些了。關於小偷，有什麼最新的線索嗎？",
  ui_story_5036_50360501_20_dialog_content = "暫時還沒有。",
  ui_story_5036_50360501_21_dialog_content = "對方非常狡猾，目前我們還未找到任何有意義的線索。",
  ui_story_5036_50360501_22_dialog_content = "只知道大部分東西都是在夜晚丟失的。",
  ui_story_5036_50360501_23_dialog_content = "這就夠了。",
  ui_story_5036_50360501_24_dialog_content = "我會和你們一起加強夜間巡邏。",
  ui_story_5036_50360501_25_dialog_content = "歌爾蒂小姐也要一起巡邏嗎？",
  ui_story_5036_50360501_26_dialog_content = "哈哈，不歡迎我這個當紅偶像的人，你好像還是第一個呢？",
  ui_story_5036_50360501_27_dialog_content = "不敢！我只是擔心佔用歌爾蒂小姐寫歌的時間。",
  ui_story_5036_50360501_28_dialog_content = "傭兵，不要小看當紅偶像的實力哦！",
  ui_story_5036_50360501_29_dialog_content = "我有很多可以在舞台上表演的歌曲呢。",
  ui_story_5036_50360501_30_dialog_content = "雖然想用空裔的旋律寫一首新曲……",
  ui_story_5036_50360501_31_dialog_content = "可PlayerName哼唱出的旋律只有那麼一句，讓我有點無從下手。",
  ui_story_5036_50360501_32_dialog_content = "一句旋律？",
  ui_story_5036_50360501_33_dialog_content = "很好奇嗎？",
  ui_story_5036_50360501_34_dialog_content = "我……我絕對沒有想私下聽歌爾蒂小姐唱歌的意思！",
  ui_story_5036_50360501_35_dialog_content = "是嗎？不過我倒是很想在這座剛建好的舞台上偷偷唱一句呢。",
  ui_story_5036_50360501_36_dialog_content = "♪啦……♪",
  ui_story_5036_50360501_37_dialog_content = "♪啦……啦啦啦……♪",
  ui_story_5036_50360501_38_dialog_content = "吼——！",
  ui_story_5036_50360501_39_dialog_content = "是之前溜出來的暗鬼嗎，它們竟敢躲在舞台下面！？",
  ui_story_5036_50360501_40_dialog_content = "歌爾蒂小姐剛開口唱了一句，暗鬼就出來了？",
  ui_story_5036_50360501_41_dialog_content = "難道暗鬼也是「蒂蒂人」？",
  ui_story_5036_50360502_1_dialog_content = "聽說舞台在今晚就能正式搭建完成了。",
  ui_story_5036_50360502_2_dialog_content = "一定要趕在其他人之前第一個拍到全方位、多角度的舞台照片！",
  ui_story_5036_50360502_3_dialog_content = "我要的是足夠勁爆，足夠吸睛的內容！",
  ui_story_5036_50360502_4_dialog_content = "真是的，編輯老師總是提出這種強人所難的要求。",
  ui_story_5036_50360502_5_dialog_content = "去哪裡找那麼多勁爆的新聞啊？",
  ui_story_5036_50360502_6_dialog_content = "只能爭取儘早發出關於歌頌者號的第一手消息了。",
  ui_story_5036_50360502_7_dialog_content = "欸，舞台上好像有人？",
  ui_story_5036_50360502_8_dialog_content = "要是暗鬼真的可以成為「蒂蒂人」就好了。",
  ui_story_5036_50360502_9_dialog_content = "歌爾蒂小姐，妳還有這種愛好？",
  ui_story_5036_50360502_10_dialog_content = "你在想什麼啦！？",
  ui_story_5036_50360502_11_dialog_content = "抱……抱歉！",
  ui_story_5036_50360502_12_dialog_content = "哈哈哈～要怪我沒說清楚。",
  ui_story_5036_50360502_13_dialog_content = "我只是在想，如果暗鬼真的能夠聽懂我的歌曲就好了。",
  ui_story_5036_50360502_14_dialog_content = "當它們聽到歌曲中對愛與和平的渴求，或許也能受到感動……",
  ui_story_5036_50360502_15_dialog_content = "然後停止現在這種野蠻的殺戮行為吧。",
  ui_story_5036_50360502_16_dialog_content = "哈哈哈，這樣說會不會顯得我有點太自負了？",
  ui_story_5036_50360502_17_dialog_content = "「感動」、「野蠻」、「殺戮」？",
  ui_story_5036_50360502_18_dialog_content = "歌爾蒂小姐到底在說什麼？離這麼遠，還是聽不太清楚啊。",
  ui_story_5036_50360502_19_dialog_content = "只能冒險再往前走兩步了！",
  ui_story_5036_50360502_20_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5036_50360502_21_dialog_content = "拜託！運氣要不要這麼差啊。",
  ui_story_5036_50360502_22_dialog_content = "怎麼偏偏就踢到旁邊的木箱子了啊。",
  ui_story_5036_50360502_23_dialog_content = "這個聲音，舞台上的人會聽見嗎？",
  ui_story_5036_50360502_24_dialog_content = "呼……看樣子我應該沒有被發現。",
  ui_story_5036_50360502_25_dialog_content = "什麼人！",
  ui_story_5036_50360502_26_dialog_content = "欸！？",
  ui_story_5036_50360502_27_dialog_content = "還……還是被發現了嗎？",
  ui_story_5036_50360502_28_dialog_content = "沒關係，我只要解釋一下是偶然路過，歌爾蒂小姐一定會……",
  ui_story_5036_50360502_29_dialog_content = "應該會相信我的吧？",
  ui_story_5036_50360502_30_dialog_content = "<color=#e8d9bb>啪啦！</color>",
  ui_story_5036_50360502_31_dialog_content = "別跑！",
  ui_story_5036_50360502_32_dialog_content = "欸？欸？欸？",
  ui_story_5036_50360502_33_dialog_content = "歌爾蒂小姐在對著另外一個方向喊？",
  ui_story_5036_50360502_34_dialog_content = "在附近躲藏的除了我，還有別人？",
  ui_story_5036_50360502_35_dialog_content = "歌爾蒂小姐，妳的察覺力簡直比我們偵察兵還敏銳！",
  ui_story_5036_50360502_36_dialog_content = "沒想到這塊木板下面真藏著一個人。",
  ui_story_5036_50360502_37_dialog_content = "可惜在我掀開這塊木板之前，那個人就已經逃走了。",
  ui_story_5036_50360502_38_dialog_content = "妳看，這裡有一塊吃了一半的乾糧。",
  ui_story_5036_50360502_39_dialog_content = "這包裝一看就是啟光的配給糧。",
  ui_story_5036_50360502_40_dialog_content = "啟光的配給糧？",
  ui_story_5036_50360502_41_dialog_content = "但是應該沒有安排啟光的士兵在舞台附近工作。",
  ui_story_5036_50360502_42_dialog_content = "是的，最近身邊的戰友們都遇到了這種情況。",
  ui_story_5036_50360502_43_dialog_content = "大家的配給糧食莫名其妙地少了很多。",
  ui_story_5036_50360502_44_dialog_content = "難道是……",
  ui_story_5036_50360502_45_dialog_content = "<color=#e8d9bb>嗖——</color>",
  ui_story_5036_50360502_46_dialog_content = "嗯？剛才那是老鼠？",
  ui_story_5036_50360502_47_dialog_content = "不對！不是老鼠。",
  ui_story_5036_50360502_48_dialog_content = "棉花糖，看見那隻竄出去的小東西了嗎？",
  ui_story_5036_50360502_49_dialog_content = "快追上去！",
  ui_story_5036_50360502_50_dialog_content = "汪！汪汪汪！",
  ui_story_5036_50360502_51_dialog_content = "嗨？",
  ui_story_5036_50360502_52_dialog_content = "嗨嗨！！！",
  ui_story_5036_50360502_53_dialog_content = "先別抓它，棉花糖，跟緊它就好。讓我們把釣魚線放長一點。",
  ui_story_5036_50360502_54_dialog_content = "看看這個小東西能不能幫我們釣到一條<color=#FFB400>「大魚」</color>。",
  ui_story_5036_50360502_55_dialog_content = "嗨——！",
  ui_story_5036_50360502_56_dialog_content = "欸……啊？",
  ui_story_5036_50360502_57_dialog_content = "比卡啊比卡，剛才找你你不理我。",
  ui_story_5036_50360502_58_dialog_content = "怎麼這會兒又主動黏過來了？",
  ui_story_5036_50360502_59_dialog_content = "汪！",
  ui_story_5036_50360502_60_dialog_content = "咳咳，我說妳要不要管管妳家的小胖狗呀？",
  ui_story_5036_50360502_61_dialog_content = "我的比卡很敏感的，這一敏感啊就容易緊張，一緊張呢就容易腸胃不舒服……",
  ui_story_5036_50360502_62_dialog_content = "你就是幽靈小偷？",
  ui_story_5036_50360502_63_dialog_content = "幽靈？可不要胡說呀。",
  ui_story_5036_50360502_64_dialog_content = "不信？不信的話我咬自己一口。啊嗚！",
  ui_story_5036_50360502_65_dialog_content = "哎唷……痛痛痛痛！",
  ui_story_5036_50360502_66_dialog_content = "妳看，我可是個大活人，會痛的。幽靈可不會覺得痛。",
  ui_story_5036_50360502_67_dialog_content = "（和這個人說話好費力。）",
  ui_story_5036_50360502_68_dialog_content = "（可他的聲音為什麼有點耳熟？）",
  ui_story_5036_50360502_69_dialog_content = "是不是幽靈我不管，但是我絕對不允許任何壞蛋妨礙我的演唱會！",
  ui_story_5036_50360502_70_dialog_content = "你最好老實交代！",
  ui_story_5036_50360502_71_dialog_content = "<color=#e8d9bb>叮鈴！</color>",
  ui_story_5036_50360502_72_dialog_content = "我手裡的東西可不只是裝飾而已！",
  ui_story_5036_50360502_73_dialog_content = "欸......欸……",
  ui_story_5036_50360502_74_dialog_content = "有話好好說嘛，讓妳這麼一嚇，我都差點絆倒自己了。",
  ui_story_5036_50360502_75_dialog_content = "你的衣服看起來鼓鼓的，裡面是不是裝著你偷的東西！？",
  ui_story_5036_50360502_76_dialog_content = "我懷裡裝著剛剛馴服的寶貝，它正在休息呢。",
  ui_story_5036_50360502_77_dialog_content = "我怎麼一點都不相信呢？",
  ui_story_5036_50360502_78_dialog_content = "唉，那只能說明妳還需要更加善解人意。",
  ui_story_5036_50360502_79_dialog_content = "平時啊多讀書、多看報，找機會多做點義工……我能提供的建議就這麼多了。",
  ui_story_5036_50360502_80_dialog_content = "哈哈，那沒事的話，我先走了。",
  ui_story_5036_50360502_81_dialog_content = "把你的衣服解開！",
  ui_story_5036_50360502_82_dialog_content = "欸！？現在雖然夜黑風高，什麼都看不清……",
  ui_story_5036_50360502_83_dialog_content = "但我作為一個清清白白的男孩子，也還是要自愛的啊。",
  ui_story_5036_50360502_84_dialog_content = "棉花糖，去！",
  ui_story_5036_50360502_85_dialog_content = "汪汪！",
  ui_story_5036_50360502_86_dialog_content = "小心，小心啊——",
  ui_story_5036_50360502_87_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5036_50360502_88_dialog_content = "還......還是跌倒了。",
  ui_story_5036_50360502_89_dialog_content = "嗯？這人好像是今天參賽的選手？",
  ui_story_5036_50360502_90_dialog_content = "果然是假借參賽之名偷溜進來的嗎。",
  ui_story_5036_50360502_91_dialog_content = "嘶，痛痛痛痛痛……",
  ui_story_5036_50360502_92_dialog_content = "原來是……他？",
  ui_story_5036_50360502_93_dialog_content = "咕咕咕咕！",
  ui_story_5036_50360502_94_dialog_content = "啊？那人懷裡滾出一隻貓頭鷹？",
  ui_story_5036_50360502_95_dialog_content = "不是贓物？果然是我太多疑了嗎？",
  ui_story_5036_50360502_96_dialog_content = "我就說我是冤枉的嘛。",
  ui_story_5036_50360502_97_dialog_content = "<color=#e8d9bb>嘩啦——叮鈴鈴鈴……</color>",
  ui_story_5036_50360502_98_dialog_content = "呃，貓頭鷹的羽毛裡掉出來好多珠寶首飾。",
  ui_story_5036_50360502_99_dialog_content = "嘿嘿嘿，妳看，我就說我不是小偷吧。",
  ui_story_5036_50360502_100_dialog_content = "泥尊鷹啊泥尊鷹，你說你做什麼不好， 為什麼要做小偷？",
  ui_story_5036_50360502_101_dialog_content = "咕咕……",
  ui_story_5036_50360502_102_dialog_content = "為什麼？為什麼證據確鑿，你還要狡辯！？",
  ui_story_5036_50360502_103_dialog_content = "有話好好說啊！",
  ui_story_5036_50360502_104_dialog_content = "不可饒恕！",
  ui_story_5036_50360502_105_dialog_content = "啊……",
  ui_story_5036_50360502_106_dialog_content = "歌爾蒂小姐！？",
  ui_story_5036_50360502_107_dialog_content = "放心，我只是讓他暫時暈倒而已。",
  ui_story_5036_50360502_108_dialog_content = "這個人說話拐彎抹角的，現在我們兩人都沒有力氣和他耗費時間。",
  ui_story_5036_50360502_109_dialog_content = "麻煩你把他帶走，等忙完手上的工作再好好審問一下吧。",
  ui_story_5036_50360502_110_dialog_content = "<color=#e8d9bb>喀嚓！</color>",
  ui_story_5036_50360502_111_dialog_content = "原來……",
  ui_story_5036_50360502_112_dialog_content = "歌爾蒂小姐有暴力傾向的消息不是假的？",
  ui_story_5036_50360502_113_dialog_content = "有了這張照片，我就可以……",
  ui_story_5036_50360601_1_dialog_content = "又怎麼了？",
  ui_story_5036_50360601_2_dialog_content = "我找到了！足夠勁爆和吸睛的新聞！",
  ui_story_5036_50360601_3_dialog_content = "妳最好不是在浪費我的時間。",
  ui_story_5036_50360601_4_dialog_content = "我保證，您一定會喜歡！",
  ui_story_5036_50360601_5_dialog_content = "老師是不是收到過一則關於歌爾蒂有暴力傾向的消息？",
  ui_story_5036_50360601_6_dialog_content = "（我……我這是在哪兒？）",
  ui_story_5036_50360601_7_dialog_content = "（嗯？我什麼時候回到空谷了，我記得我還在……）",
  ui_story_5036_50360601_8_dialog_content = "（我之前是在哪裡？）",
  ui_story_5036_50360601_9_dialog_content = "♪啦……啦啦啦……♪",
  ui_story_5036_50360601_10_dialog_content = "（這段旋律，我記得這段旋律！）",
  ui_story_5036_50360601_11_dialog_content = "♪嗚嗚嗚嗚……♪",
  ui_story_5036_50360601_12_dialog_content = "（是誰在哼唱？）",
  ui_story_5036_50360601_13_dialog_content = "<color=#e8d9bb>嗖！</color>",
  ui_story_5036_50360601_14_dialog_content = "（什麼東西飛過去了？是巨像嗎？）",
  ui_story_5036_50360601_15_dialog_content = "（我得跟過去看看。）",
  ui_story_5036_50360601_16_dialog_content = "♪哦啦啦啦……♪",
  ui_story_5036_50360601_17_dialog_content = "♪嗚嗚嗚嗚……♪",
  ui_story_5036_50360601_18_dialog_content = "♪啦……啦啦……♪",
  ui_story_5036_50360601_19_dialog_content = "（前面有一個女孩，就是她一直在唱歌。）",
  ui_story_5036_50360601_20_dialog_content = "你來了？",
  ui_story_5036_50360601_21_dialog_content = "（欸？在和我說話嗎？）",
  ui_story_5036_50360601_22_dialog_content = "啾啾！",
  ui_story_5036_50360601_23_dialog_content = "（原來她是在和那隻看上去很像巨像的動物說話。）",
  ui_story_5036_50360601_24_dialog_content = "又來聽我唱歌？你很捧我的場呢。",
  ui_story_5036_50360601_25_dialog_content = "嗯，不過我覺得，是時候給這段旋律加上一些歌詞了。",
  ui_story_5036_50360601_26_dialog_content = "（她的衣著和氣息……不會有錯，她是空裔！）",
  ui_story_5036_50360601_27_dialog_content = "（我就知道，我一定會找到其他空裔的！）",
  ui_story_5036_50360601_28_dialog_content = "唔，有點口渴了呢。",
  ui_story_5036_50360601_29_dialog_content = "我們去摘點野果子吃吧？",
  ui_story_5036_50360601_30_dialog_content = "啾啾！",
  ui_story_5036_50360601_31_dialog_content = "喂，小妹妹！",
  ui_story_5036_50360601_32_dialog_content = "等等我呀！",
  ui_story_5036_50360601_33_dialog_content = "嗯？",
  ui_story_5036_50360601_34_dialog_content = "<color=#e8d9bb>咚咚咚！</color>",
  ui_story_5036_50360601_35_dialog_content = "小妹妹！",
  ui_story_5036_50360601_36_dialog_content = "嗯？",
  ui_story_5036_50360601_37_dialog_content = "呼，只是一個夢嗎。",
  ui_story_5036_50360601_38_dialog_content = "<color=#e8d9bb>距離演唱會開始還有四天</color>",
  ui_story_5036_50360601_39_dialog_content = "<color=#e8d9bb>咚咚咚！咚咚咚！</color>",
  ui_story_5036_50360601_40_dialog_content = "PlayerName，你還好嗎！？",
  ui_story_5036_50360601_41_dialog_content = "啊，來了來了！",
  ui_story_5036_50360601_42_dialog_content = "PlayerName，你會不會睡得太熟了？",
  ui_story_5036_50360601_43_dialog_content = "我們大聲敲門敲了好久，你都沒有聽見嗎？",
  ui_story_5036_50360601_44_dialog_content = "還以為是暗鬼溜進你的房間把你給……",
  ui_story_5036_50360601_45_dialog_content = "我和薇絲差點就要破門而入了。",
  ui_story_5036_50360601_46_dialog_content = "抱歉、抱歉，我剛才做了一個夢，一時沒有回神過來。",
  ui_story_5036_50360601_47_dialog_content = "唉，又是做夢啊。",
  ui_story_5036_50360601_48_dialog_content = "夢？",
  ui_story_5036_50360601_49_dialog_content = "對呀，卡蓮，妳忘了？",
  ui_story_5036_50360601_50_dialog_content = "PlayerName經常做一些稀奇古怪的夢。",
  ui_story_5036_50360601_51_dialog_content = "我忽然想起今早我也做了一個奇怪的夢。",
  ui_story_5036_50360601_52_dialog_content = "我好像夢到了空谷。",
  ui_story_5036_50360601_53_dialog_content = "可是空谷裡住著的人並不是PlayerName，而是一個我沒見過的小女孩。",
  ui_story_5036_50360601_54_dialog_content = "我也是！我也做了同樣的夢！",
  ui_story_5036_50360601_55_dialog_content = "沒想到我和卡蓮已經默契到了這種程度？",
  ui_story_5036_50360601_56_dialog_content = "一定是這幾天的集訓有了效果！",
  ui_story_5036_50360601_57_dialog_content = "可是我也做了類似的夢。",
  ui_story_5036_50360601_58_dialog_content = "什麼？",
  ui_story_5036_50360601_59_dialog_content = "我看見一個小女孩在空谷裡歌唱。",
  ui_story_5036_50360601_60_dialog_content = "她唱的歌，就是最近一直佔據我腦海的那段旋律！",
  ui_story_5036_50360601_61_dialog_content = "我夢裡的小女孩沒有唱歌，只是很普通地在家裡打掃衛生。",
  ui_story_5036_50360601_62_dialog_content = "我夢見的女孩一直在屋子裡看書。",
  ui_story_5036_50360601_63_dialog_content = "看來大家的夢有點不一樣呢。",
  ui_story_5036_50360601_64_dialog_content = "我聽說，如果幾個人共同經歷過一些事情，就有機會夢到類似的夢境。",
  ui_story_5036_50360601_65_dialog_content = "因為他們有相似的經歷，因此所思所想會逐漸相近，夢到的東西也會變得相似。",
  ui_story_5036_50360601_66_dialog_content = "這就是所謂的「日有所思，夜有所夢」。",
  ui_story_5036_50360601_67_dialog_content = "又因為每個人的性格不同，所以即使是再相似的夢境，細節也會有所不同。",
  ui_story_5036_50360601_68_dialog_content = "啊？只是這樣而已嗎？害我白白激動了一下。",
  ui_story_5036_50360601_69_dialog_content = "比起這個，PlayerName還要陪我們繼續聊下去嗎？",
  ui_story_5036_50360601_70_dialog_content = "今天的第二場海選，你還是要當評審的吧？",
  ui_story_5036_50360601_71_dialog_content = "啊！！！差點忘掉了！",
  ui_story_5036_50360601_72_dialog_content = "♪嗚嗚嗚嗚……♪",
  ui_story_5036_50360601_73_dialog_content = "♪啦……啦啦……♪",
  ui_story_5036_50360601_74_dialog_content = "這就是我腦海中完整的旋律，終於全部唱出來了！",
  ui_story_5036_50360601_75_dialog_content = "呵——欠！",
  ui_story_5036_50360601_76_dialog_content = "是……是我哼唱得太差勁了嗎？",
  ui_story_5036_50360601_77_dialog_content = "沒有那回事啦。可能是我昨晚沒有睡好，才在PlayerName面前失態了。",
  ui_story_5036_50360601_78_dialog_content = "不會是因為做太多夢沒睡好吧？",
  ui_story_5036_50360601_79_dialog_content = "哈哈哈，PlayerName真的好有想像力哦～",
  ui_story_5036_50360601_80_dialog_content = "我昨晚去檢查了舞台的情況。",
  ui_story_5036_50360601_81_dialog_content = "還去封鎖區幫忙清理了一批暗鬼，直到凌晨才收工。",
  ui_story_5036_50360601_82_dialog_content = "這些事不是交給白火傭兵團了嗎？",
  ui_story_5036_50360601_83_dialog_content = "哈哈～我在房間裡待不住。",
  ui_story_5036_50360601_84_dialog_content = "與其在房裡想些有的沒的，不如幫忙分擔一點任務。",
  ui_story_5036_50360601_85_dialog_content = "怪不得妳會成為影鎮最當紅的偶像，這樣做也太拼了吧？",
  ui_story_5036_50360601_86_dialog_content = "連這種細枝末節也要操心！",
  ui_story_5036_50360601_87_dialog_content = "任何一個細節都有可能影響演唱會的成敗。",
  ui_story_5036_50360601_88_dialog_content = "這場演唱會對我來說至關重要，當然不允許發生任何意外啦。",
  ui_story_5036_50360601_89_dialog_content = "總覺得，妳對待每次演唱會都像是對待最後一次演唱會一樣盡心盡力。",
  ui_story_5036_50360601_90_dialog_content = "有……有嗎？哈哈哈。",
  ui_story_5036_50360601_91_dialog_content = "言歸正傳！PlayerName哼唱的這段旋律該怎麼說呢……",
  ui_story_5036_50360601_92_dialog_content = "輕柔、舒緩、療愈，既有空裔的風格，又非常容易傳唱！",
  ui_story_5036_50360601_93_dialog_content = "無論從哪個角度來看，它都是我想要的音樂！",
  ui_story_5036_50360601_94_dialog_content = "你真的不介意我在舞台上演唱它嗎？",
  ui_story_5036_50360601_95_dialog_content = "從來沒想過我還能成為作曲家，妳儘管拿去用！",
  ui_story_5036_50360601_96_dialog_content = "能讓當紅偶像歌手演唱我的歌曲，是我的榮幸。",
  ui_story_5036_50360601_97_dialog_content = "如果PlayerName對歌詞有什麼好的想法，也記得告訴我哦～",
  ui_story_5036_50360601_98_dialog_content = "除此之外，我還有件事想問PlayerName。",
  ui_story_5036_50360601_99_dialog_content = "第一場海選的最後一位選手，你還記得嗎？",
  ui_story_5036_50360601_100_dialog_content = "妳是說維克？",
  ui_story_5036_50360601_101_dialog_content = "維克是PlayerName的朋友嗎？",
  ui_story_5036_50360601_102_dialog_content = "嗯，我和維克的徒弟比較熟，所以算是認識的朋友吧。",
  ui_story_5036_50360601_103_dialog_content = "不過他來參賽的事我事先毫不知情，當時我也沒有投票給他。",
  ui_story_5036_50360601_104_dialog_content = "你不用擔心我會偏袒他！",
  ui_story_5036_50360601_105_dialog_content = "他以前有偷東西的癖好嗎？",
  ui_story_5036_50360601_106_dialog_content = "欸？偷東西？為什麼這麼問？",
  ui_story_5036_50360601_107_dialog_content = "昨天深夜……",
  ui_story_5036_50360601_108_dialog_content = "救命！",
  ui_story_5036_50360601_109_dialog_content = "吼——！",
  ui_story_5036_50360601_110_dialog_content = "別跑啊！",
  ui_story_5036_50360601_111_dialog_content = "暗鬼追著維克，傭兵又追著暗鬼？這是什麼情況！？",
  ui_story_5036_50360602_1_dialog_content = "歌爾蒂小姐、PlayerName先生，其他評審已經入場了。",
  ui_story_5036_50360602_2_dialog_content = "如果兩位方便的話……",
  ui_story_5036_50360602_3_dialog_content = "救命啊——！",
  ui_story_5036_50360602_4_dialog_content = "也該去參加第二場海選了。",
  ui_story_5036_50360602_5_dialog_content = "吼！",
  ui_story_5036_50360602_6_dialog_content = "接招吧！",
  ui_story_5036_50360602_7_dialog_content = "看樣子，大家現在還不太方便呀？",
  ui_story_5036_50360602_8_dialog_content = "救命！",
  ui_story_5036_50360602_9_dialog_content = "暗鬼已經被打倒了，你不用再喊了。",
  ui_story_5036_50360602_10_dialog_content = "呼……呼……呼……",
  ui_story_5036_50360602_11_dialog_content = "我是害怕妳再把我和暗鬼關到一起才喊的！",
  ui_story_5036_50360602_12_dialog_content = "剛才多虧小毛球的爪子夠長，把門鎖撬開了。",
  ui_story_5036_50360602_13_dialog_content = "不然我連喊救命的機會都沒有了。",
  ui_story_5036_50360602_14_dialog_content = "對不起！我絕對沒有危害你性命的意思。",
  ui_story_5036_50360602_15_dialog_content = "可把你關進去之前，房間裡並沒有暗鬼。",
  ui_story_5036_50360602_16_dialog_content = "……",
  ui_story_5036_50360602_17_dialog_content = "歌爾蒂小姐，暗鬼是從房內的通風管道口爬出來的。",
  ui_story_5036_50360602_18_dialog_content = "那個房間的通風管道似乎和封鎖區相通。",
  ui_story_5036_50360602_19_dialog_content = "通風管道？可通風管道口被柵欄鎖得很死。",
  ui_story_5036_50360602_20_dialog_content = "嗯？我明白啦。",
  ui_story_5036_50360602_21_dialog_content = "是你想要從通風管道逃跑，所以才引來了暗鬼！",
  ui_story_5036_50360602_22_dialog_content = "呃……哈哈哈。",
  ui_story_5036_50360602_23_dialog_content = "房間裡那麼熱，我實在是需要放放風嘛。",
  ui_story_5036_50360602_24_dialog_content = "怎麼回事？你們為什麼要把維克關起來？",
  ui_story_5036_50360602_25_dialog_content = "PlayerName，對不起。",
  ui_story_5036_50360602_26_dialog_content = "但你的朋友維克就是這幾天四處行竊的「幽靈小偷」。",
  ui_story_5036_50360602_27_dialog_content = "維克？小偷？",
  ui_story_5036_50360602_28_option_content = "也不是沒有可能",
  ui_story_5036_50360602_29_dialog_content = "雖然是出過書的神奇動物專家，但那已經是好多年前的事了。",
  ui_story_5036_50360602_30_dialog_content = "沒有新作、沒有收入的維克，到頭來只能靠偷竊謀生了嗎？",
  ui_story_5036_50360602_31_dialog_content = "就算再落魄，也要以自己的雙手創造財富。",
  ui_story_5036_50360602_32_dialog_content = "而不是把雙手伸進別人的口袋，偷走東西放進自己的口袋！",
  ui_story_5036_50360602_33_option_content = "怎麼可能！？",
  ui_story_5036_50360602_34_dialog_content = "他可是出過書的神奇動物專家，還收了好幾個徒弟。",
  ui_story_5036_50360602_35_dialog_content = "就算再怎麼落魄，也不會做這種小偷小盜的事情吧？",
  ui_story_5036_50360602_36_dialog_content = "PlayerName，我知道你很難接受這件事。",
  ui_story_5036_50360602_37_dialog_content = "其實我也不敢相信，在這之前我都非常看好維克的潛力。",
  ui_story_5036_50360602_38_dialog_content = "但是昨天我們從他的口袋裡發現了失竊的食物和珠寶，證據確鑿。",
  ui_story_5036_50360602_39_dialog_content = "大家聽我解釋啊……",
  ui_story_5036_50360602_40_dialog_content = "昨天我已經聽夠了你故弄玄虛的狡辯。",
  ui_story_5036_50360602_41_dialog_content = "現在有這麼多證據，你還想要抵賴嗎？",
  ui_story_5036_50360602_42_dialog_content = "好吧好吧，我承認最近的失竊事件全怪我。",
  ui_story_5036_50360602_43_dialog_content = "維克，你還真的是「幽靈小偷」啊！？",
  ui_story_5036_50360602_44_dialog_content = "雖然這件事要怪我，但我必須聲明！",
  ui_story_5036_50360602_45_dialog_content = "我，維克，著名神奇動物專家，從來沒當過小偷哦。",
  ui_story_5036_50360602_46_dialog_content = "最近大家口中的「幽靈小偷」……其實是我帶來的神奇動物。",
  ui_story_5036_50360602_47_dialog_content = "嗨……",
  ui_story_5036_50360602_48_dialog_content = "咕……",
  ui_story_5036_50360602_49_dialog_content = "嗚啾嗚啾啾，嗚啾嗚！",
  ui_story_5036_50360602_50_dialog_content = "你肩膀上那團毛茸茸的小傢伙好像很激動？",
  ui_story_5036_50360602_51_dialog_content = "小毛球在說：「是它們兩個，不是我！」",
  ui_story_5036_50360602_52_dialog_content = "嗚啾！",
  ui_story_5036_50360602_53_dialog_content = "平時，我每天都會變著花樣給它們餵食。",
  ui_story_5036_50360602_54_dialog_content = "但這次我準備得很匆忙，只帶了一種食物過來。",
  ui_story_5036_50360602_55_dialog_content = "它們兩個大概是吃膩了，突然丟下我擅自離開。",
  ui_story_5036_50360602_56_dialog_content = "我聽到巨像上有小偷的傳聞之後，就猜到也許是它們做的好事。",
  ui_story_5036_50360602_57_dialog_content = "花了好大一番功夫，才在昨晚把它們全都抓回來。",
  ui_story_5036_50360602_58_dialog_content = "然後又正好被我們抓到？",
  ui_story_5036_50360602_59_dialog_content = "對啊，妳說這事情怎麼就這麼巧呢，哈哈哈。",
  ui_story_5036_50360602_60_dialog_content = "一群小動物，偷吃也就算了，為什麼會偷大家的珠寶呢？",
  ui_story_5036_50360602_61_dialog_content = "泥尊鷹？是泥尊鷹？",
  ui_story_5036_50360602_62_dialog_content = "沒錯，泥尊鷹能夠施放讓人沉睡的氣體，我原本是為了防身才帶在身邊的。",
  ui_story_5036_50360602_63_dialog_content = "但泥尊鷹最喜歡收集閃亮亮的財寶，如果不看好它們的話……",
  ui_story_5036_50360602_64_dialog_content = "它們就會變成人們口中「把人迷暈再行竊的小偷」。",
  ui_story_5036_50360602_65_dialog_content = "不過這只是神奇動物的習性而已，它們對我們沒有惡意。",
  ui_story_5036_50360602_66_dialog_content = "要怪只能怪我沒有看好它們。",
  ui_story_5036_50360602_67_dialog_content = "我保證會把那些珠寶啊、錢幣啊都還給失主！",
  ui_story_5036_50360602_68_dialog_content = "不夠的話，我還可以付大家精神賠償費。",
  ui_story_5036_50360602_69_dialog_content = "請你們千萬不要懲罰這些神奇動物！它們真的不是故意的。",
  ui_story_5036_50360602_70_dialog_content = "嗨嗨嗨。",
  ui_story_5036_50360602_71_dialog_content = "……",
  ui_story_5036_50360602_72_dialog_content = "好吧，但是你必須要說到做到。",
  ui_story_5036_50360602_73_dialog_content = "歸還失物、賠禮道歉、賠償費用，一項都不能少。",
  ui_story_5036_50360602_74_dialog_content = "所以，可以別把我們關在小黑屋裡了嗎？",
  ui_story_5036_50360602_75_dialog_content = "怪悶的呢……",
  ui_story_5036_50360602_76_dialog_content = "也不是不可以。",
  ui_story_5036_50360602_77_dialog_content = "但是你必須答應我，做好善後工作後，立刻離開歌頌者號。",
  ui_story_5036_50360602_78_dialog_content = "啊？我不能離開這裡呀，我的偶像夢還沒有實現呢！",
  ui_story_5036_50360602_79_dialog_content = "歌爾蒂小姐，妳之前不是也很期待我繼續參加海選嗎？",
  ui_story_5036_50360602_80_dialog_content = "雖然你的條件很出眾，嘴上也說得很好聽……",
  ui_story_5036_50360602_81_dialog_content = "可我的直覺說，你來歌頌者號上並不是為了參加海選，對不對？",
  ui_story_5036_50360602_82_dialog_content = "！！！",
  ui_story_5036_50360602_83_dialog_content = "……既然歌爾蒂小姐這麼問，我也就不再掩飾了。",
  ui_story_5036_50360602_84_dialog_content = "其實我來這裡，是為了尋找一種叫做銜尾龍的神奇動物。",
  ui_story_5036_50360602_85_dialog_content = "這種動物在成長到一定階段之後，會變成龍蛋。",
  ui_story_5036_50360602_86_dialog_content = "而經過一段時間後，它會再次破殼而出，如此循環往復，以這種方式達成永生。",
  ui_story_5036_50360602_87_dialog_content = "這世上竟然有可以永生的動物！",
  ui_story_5036_50360602_88_dialog_content = "我從小就知道自己不是父母的親生兒子……",
  ui_story_5036_50360602_89_dialog_content = "但我最近發現，我的血脈與銜尾龍似乎有某種奇妙的關聯！所以我必須找到銜尾龍。",
  ui_story_5036_50360602_89X1_dialog_content = "找到銜尾龍，我就能調查清楚自己的身世，也許我還能找到自己的親生父母。",
  ui_story_5036_50360602_90_dialog_content = "而關於銜尾龍的記載少之又少，唯一可以肯定的是，銜尾龍非常喜歡在巨像附近活動。",
  ui_story_5036_50360602_91_dialog_content = "師父，你怎麼又喝得不省人事啦？快醒醒！",
  ui_story_5036_50360602_92_dialog_content = "菲雅已經找遍了艾斯特拉大陸上所有的巨像遺跡，包括PlayerName的臨空者號。",
  ui_story_5036_50360602_93_dialog_content = "但是沒有發現半點銜尾龍的蹤跡。",
  ui_story_5036_50360602_94_dialog_content = "世界上真的存在銜尾龍這種神奇動物嗎？",
  ui_story_5036_50360602_96_dialog_content = "你該不會又在耍菲雅吧！？",
  ui_story_5036_50360602_97_dialog_content = "哼！以後不要再讓菲雅幫你找什麼銜尾龍了！",
  ui_story_5036_50360602_98_dialog_content = "但是我找遍了艾斯特拉大陸上的所有巨像遺跡，都沒有發現銜尾龍的蹤跡。",
  ui_story_5036_50360602_99_dialog_content = "所以只有到這艘在天空中航行的巨像上來尋找了。",
  ui_story_5036_50360602_100_dialog_content = "所以你在歌頌者號上發現銜尾龍的蹤跡了嗎？",
  ui_story_5036_50360602_101_dialog_content = "沒有。但是我有一種預感， 一種非常強烈的預感。",
  ui_story_5036_50360602_102_dialog_content = "銜尾龍就在這艘歌頌者號上！",
  ui_story_5036_50360602_103_dialog_content = "請讓我繼續留在這裡尋找吧！",
  ui_story_5036_50360602_104_dialog_content = "給我這個從來沒有體會過家庭溫暖的人一個機會，一個找到家人的機會！",
  ui_story_5036_50360602_105_dialog_content = "講完了嗎？",
  ui_story_5036_50360602_106_dialog_content = "嗯，講完了。",
  ui_story_5036_50360602_107_dialog_content = "哈哈，你講的這個故事比影鎮的三流電影還要離譜。",
  ui_story_5036_50360602_108_dialog_content = "謝謝你讓我大開眼界啦。",
  ui_story_5036_50360602_109_dialog_content = "欸嘿嘿，不客氣，沒想到歌爾蒂小姐這麼通情達理。",
  ui_story_5036_50360602_110_dialog_content = "早知道這樣，我應該一開始就找大家說清楚的。",
  ui_story_5036_50360602_111_dialog_content = "好了，故事講完了。",
  ui_story_5036_50360602_112_dialog_content = "現在你可以離開歌頌者號了嗎？",
  ui_story_5036_50360602_113_dialog_content = "啊？",
  ui_story_5036_50360602_114_dialog_content = "請這邊走，我來送你。",
  ui_story_5036_50360602_115_dialog_content = "等等！哎呀，我還沒說完、沒說完呢。",
  ui_story_5036_50360602_116_dialog_content = "剛才我說的那些都是開玩笑的，哈哈哈哈。",
  ui_story_5036_50360602_116X1_dialog_content = "隨機應變、帶動氣氛、緩和粉絲情緒等等，這些也是偶像實力的一部分。",
  ui_story_5036_50360602_116X2_dialog_content = "我是想向歌爾蒂小姐展現我這方面的能力，以證明我真的是想來參加海選的嘛~",
  ui_story_5036_50360602_117_dialog_content = "隨機應變、帶動氣氛的能力？",
  ui_story_5036_50360602_118_dialog_content = "歌爾蒂小姐聽了我的故事，不也開心得笑出來了嗎？",
  ui_story_5036_50360602_119_dialog_content = "這……",
  ui_story_5036_50360602_120_dialog_content = "（的確，從剛才開始，我的注意力就一直被維克帶著跑。）",
  ui_story_5036_50360602_121_dialog_content = "（涉老闆總說我還欠缺什麼，難道就是維克這種令人心情放鬆的幽默感？）",
  ui_story_5036_50360602_124_dialog_content = "我是真心想成為一名偶像，就讓我留下繼續參賽吧。",
  ui_story_5036_50360602_125_dialog_content = "妳不相信我，難道也不相信妳身旁的PlayerName嗎？",
  ui_story_5036_50360602_126_dialog_content = "PlayerName是這場演唱會的貴賓，我當然無條件相信他。",
  ui_story_5036_50360602_127_dialog_content = "那不就好辦了嗎。",
  ui_story_5036_50360602_128_dialog_content = "PlayerName，我的愛徒菲雅幫過你不少次，對不對？",
  ui_story_5036_50360602_129_dialog_content = "呃，嗯……算是吧。",
  ui_story_5036_50360602_130_dialog_content = "四捨五入，我也算是PlayerName的恩人囉？",
  ui_story_5036_50360602_131_dialog_content = "恩......恩人？",
  ui_story_5036_50360602_132_dialog_content = "所以你身為評審，一定也願意幫我擔保吧？",
  ui_story_5036_50360602_133_dialog_content = "……",
  ui_story_5036_50360602_134_dialog_content = "歌爾蒂小姐，PlayerName願意替我擔保。",
  ui_story_5036_50360602_135_dialog_content = "看在他的面子上，就不要趕我走了，好不好呢？",
  ui_story_5036_50360602_136_dialog_content = "PlayerName，你真的願意替維克擔保嗎？",
  ui_story_5036_50360602_137_dialog_content = "我……我……",
  ui_story_5036_50360602_138_dialog_content = "PlayerName，把耳朵湊過來，聽我說……",
  ui_story_5036_50360602_139_dialog_content = "難道你真的沒有發現，歌頌者號的封鎖區裡，有一股非常強大的光能嗎？",
  ui_story_5036_50360602_140_dialog_content = "欸！？",
  ui_story_5036_50360602_141_dialog_content = "原來昨晚歌爾蒂只是為了抓小偷才……",
  ui_story_5036_50360602_142_dialog_content = "那我拍的那張照片豈不是會誤導讀者嗎？",
  ui_story_5036_50360602_143_dialog_content = "<color=#e8d9bb>嗡嗡嗡！</color>",
  ui_story_5036_50360602_144_dialog_content = "珀蘭蒂，到底要等到什麼時候，妳才會把所說的照片給我？",
  ui_story_5036_50360602_145_dialog_content = "編輯老師，這件事我還需要再調查清楚才行！",
  ui_story_5036_50360602_146_dialog_content = "還調查什麼啊調查？",
  ui_story_5036_50360602_147_dialog_content = "不管真相是什麼，能吸引讀者目光的新聞才是好新聞！",
  ui_story_5036_50360602_148_dialog_content = "可是……",
  ui_story_5036_50360602_149_dialog_content = "要是再不把照片給我，妳就再也不用回來上班了！",
  ui_story_5036_50360602_150_dialog_content = "編輯老師！編輯老師？",
  ui_story_5036_50360701_1_dialog_content = "PlayerName，今天你對選手節目的點評越來越專業了！",
  ui_story_5036_50360701_2_dialog_content = "說不定以後你可以成為真正的偶像製作人呢～",
  ui_story_5036_50360701_3_dialog_content = "不過……",
  ui_story_5036_50360701_4_dialog_content = "妳還在擔心維克？",
  ui_story_5036_50360701_5_dialog_content = "嗯，對不起！",
  ui_story_5036_50360701_6_dialog_content = "雖然PlayerName願意幫他擔保，但我還是有點放心不下。",
  ui_story_5036_50360701_7_dialog_content = "我把他安排在附近的那間排練室，也不知道他有沒有在認真排練節目。",
  ui_story_5036_50360701_8_dialog_content = "會不會干擾別人的訓練？",
  ui_story_5036_50360701_9_dialog_content = "不行，我還是要去看看才行。",
  ui_story_5036_50360701_10_dialog_content = "那個……讓我去吧。",
  ui_story_5036_50360701_11_dialog_content = "他是有我擔保才留下來的，我有責任去監督他。",
  ui_story_5036_50360701_12_dialog_content = "歌爾蒂從昨天開始一直沒有停過，還是先去休息下吧。",
  ui_story_5036_50360701_13_dialog_content = "嗯，也是。我還有歌詞要寫，不能辜負了PlayerName交給我的旋律呢～",
  ui_story_5036_50360701_14_dialog_content = "維克的事就拜託PlayerName啦！",
  ui_story_5036_50360701_15_dialog_content = "呵——欠，你說什麼？",
  ui_story_5036_50360701_16_dialog_content = "今天怎麼樣？",
  ui_story_5036_50360701_17_dialog_content = "很不錯哦。",
  ui_story_5036_50360701_18_dialog_content = "睡得很飽！",
  ui_story_5036_50360701_19_dialog_content = "我是問你排練得怎麼樣了？",
  ui_story_5036_50360701_20_dialog_content = "難道你今天睡了一天，都沒有想過排練節目的事？",
  ui_story_5036_50360701_21_dialog_content = "是我沒說清楚嗎？好吧，我再說一遍。",
  ui_story_5036_50360701_22_dialog_content = "銜尾龍的故事不是假的，參加海選只是我的藉口。",
  ui_story_5036_50360701_23_dialog_content = "我只是想藉這個機會進入歌頌者號，找到銜尾龍。",
  ui_story_5036_50360701_24_dialog_content = "我知道，可是我根本沒有感應到歌頌者號的封鎖區裡，有什麼強大的光能。",
  ui_story_5036_50360701_25_dialog_content = "那裡只有一堆正在昏睡的暗鬼而已。",
  ui_story_5036_50360701_26_dialog_content = "銜尾龍在蛋裡面的時候，的確無法釋放太多光能。",
  ui_story_5036_50360701_27_dialog_content = "這麼說，銜尾龍現在真的還在龍蛋裡面！",
  ui_story_5036_50360701_28_dialog_content = "為什麼要把「銜尾龍在歌頌者號上」當作前提來思考啊？",
  ui_story_5036_50360701_29_dialog_content = "因為直覺——神奇動物專家的直覺。",
  ui_story_5036_50360701_30_dialog_content = "呼，也就是沒有任何證據。",
  ui_story_5036_50360701_31_dialog_content = "我現在總算明白菲雅平時的心情了。",
  ui_story_5036_50360701_32_dialog_content = "你還是沒辦法說服他們，讓我進入封鎖區嗎？",
  ui_story_5036_50360701_33_dialog_content = "我……我怎麼開得了這個口。",
  ui_story_5036_50360701_34_dialog_content = "歌爾蒂交代傭兵團嚴加看守封鎖區，她一定不會讓任何人闖進去惹事。",
  ui_story_5036_50360701_35_dialog_content = "就算你想找的銜尾龍真的在歌頌者號上，你也可以等演唱會結束了再去找嘛。",
  ui_story_5036_50360701_36_dialog_content = "你的意思是我可以留在歌頌者號上，直到演唱會結束？",
  ui_story_5036_50360701_37_dialog_content = "前提是你能通過海選。",
  ui_story_5036_50360701_38_dialog_content = "無法通過海選的選手需要立刻離開，海選的參賽守則上應該有寫的。",
  ui_story_5036_50360701_39_dialog_content = "通過海選？這事很簡單嘛。",
  ui_story_5036_50360701_40_dialog_content = "哦？你想到要表演什麼了？",
  ui_story_5036_50360701_41_dialog_content = "指揮小毛球表演後空翻，這個節目怎麼樣？",
  ui_story_5036_50360701_42_dialog_content = "動物表演？這種節目去馬戲團還差不多。",
  ui_story_5036_50360701_43_dialog_content = "這裡不是選拔偶像歌手的比賽嗎？",
  ui_story_5036_50360701_44_dialog_content = "你是不是來錯地方了？",
  ui_story_5036_50360701_45_dialog_content = "大家，發生什麼事了嗎？",
  ui_story_5036_50360701_46_dialog_content = "有衝突的地方就有新聞，我可要好好記錄下來！",
  ui_story_5036_50360701_47_dialog_content = "你，不要看別人了，就是你！",
  ui_story_5036_50360701_48_dialog_content = "這位大哥認識我嗎？",
  ui_story_5036_50360701_49_dialog_content = "我知道你。",
  ui_story_5036_50360701_50_dialog_content = "好難得，竟然能在這裡遇見我的讀者！",
  ui_story_5036_50360701_51_dialog_content = "你就是最近被逮到的那個「幽靈小偷」。",
  ui_story_5036_50360701_52_dialog_content = "啊？小偷不是該被關起來嗎？為什麼還能在這裡等著參加比賽？",
  ui_story_5036_50360701_53_dialog_content = "而且他根本就是在浪費名額。",
  ui_story_5036_50360701_54_dialog_content = "聽著，小偷，我不知道你走了什麼後門。",
  ui_story_5036_50360701_55_dialog_content = "但是在這裡的所有選手，都不允許你褻瀆我們的舞台和夢想！",
  ui_story_5036_50360701_56_dialog_content = "如果你不打算認真參賽，就趁早滾出去！",
  ui_story_5036_50360701_57_dialog_content = "呃，大家消消氣、消消氣……",
  ui_story_5036_50360701_58_dialog_content = "之前的事是一場誤會，我是真心打算認真參賽。",
  ui_story_5036_50360701_59_dialog_content = "不只如此，我還決心要通過海選，站在真正的舞台上演出～",
  ui_story_5036_50360701_60_dialog_content = "就憑你的馬戲表演？",
  ui_story_5036_50360701_61_dialog_content = "哎呀，剛才只是朋友之間的說笑。",
  ui_story_5036_50360701_62_dialog_content = "我怎麼可能沒有準備合適的節目就報名呢～",
  ui_story_5036_50360701_63_dialog_content = "那你倒是給大家看看，是準備了什麼節目？",
  ui_story_5036_50360701_64_dialog_content = "就是！",
  ui_story_5036_50360701_65_dialog_content = "給我們看看你準備了什麼節目！",
  ui_story_5036_50360701_66_dialog_content = "這個……",
  ui_story_5036_50360701_67_dialog_content = "嗯？還在猶豫什麼？",
  ui_story_5036_50360701_68_dialog_content = "快開始！快表演！",
  ui_story_5036_50360701_69_dialog_content = "別急呀大家，我表演就是了。",
  ui_story_5036_50360701_70_dialog_content = "咳咳，接下來請欣賞——蒼獅龍舞。",
  ui_story_5036_50360701_71_dialog_content = "這段舞蹈是模仿蒼獅龍求偶的飛行動作，大家看好了啊～",
  ui_story_5036_50360701_72_dialog_content = "嘿！",
  ui_story_5036_50360701_73_dialog_content = "哈！",
  ui_story_5036_50360701_74_dialog_content = "呃……這真的是舞蹈嗎？",
  ui_story_5036_50360701_75_dialog_content = "看上去更像剛剛骨折痊癒的人在重新學走路。",
  ui_story_5036_50360701_76_dialog_content = "看好了，我要來個後空翻囉！",
  ui_story_5036_50360701_77_dialog_content = "嘿哈！",
  ui_story_5036_50360701_78_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_5036_50360701_79_dialog_content = "哎唷……痛痛痛痛痛痛痛痛痛！",
  ui_story_5036_50360701_80_dialog_content = "哈哈哈哈哈哈哈哈哈！",
  ui_story_5036_50360701_81_dialog_content = "後空翻沒翻起來，倒是摔到腰了麼？",
  ui_story_5036_50360701_82_dialog_content = "能跳成這個樣子，也是某種程度的天才了吧！",
  ui_story_5036_50360701_83_dialog_content = "神奇動物專家轉行偶像，歌頌者號上遭圍剿……",
  ui_story_5036_50360701_84_dialog_content = "這樣的報導能讓編輯老師滿意嗎？",
  ui_story_5036_50360701_85_dialog_content = "維克，你還好嗎？",
  ui_story_5036_50360701_86_dialog_content = "唉，到頭來還是PlayerName知道關心老人家啊。",
  ui_story_5036_50360701_87_dialog_content = "我的屁股後面好像撞到了什麼東西，能拉我起來嗎？",
  ui_story_5036_50360701_88_dialog_content = "……好吧。",
  ui_story_5036_50360701_89_dialog_content = "欸，你屁股後面是……通風管道口嗎！？",
  ui_story_5036_50360701_90_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5036_50360701_91_dialog_content = "嗯？這是什麼聲音？",
  ui_story_5036_50360701_92_dialog_content = "哈哈哈，我竟然又把通風管道口給撞開了呢。",
  ui_story_5036_50360701_93_dialog_content = "吼！！！",
  ui_story_5036_50360701_94_dialog_content = "啊，這裡的通風管道中，怎麼也藏著暗鬼啊？",
  ui_story_5036_50360701_95_dialog_content = "快跑啊——！",
  ui_story_5036_50360702_1_dialog_content = "吼！！！",
  ui_story_5036_50360702_2_dialog_content = "綻放吧！",
  ui_story_5036_50360702_3_dialog_content = "歌爾蒂小姐和暗鬼戰鬥的樣子……必須快點想辦法調查清楚關於她的那個傳聞才行。",
  ui_story_5036_50360702_4_dialog_content = "啊，糟糕！忘記拍照記錄了……",
  ui_story_5036_50360702_5_dialog_content = "各位選手，大家有沒有受傷？",
  ui_story_5036_50360702_6_dialog_content = "大家都還好，就是有幾個受到驚嚇了。",
  ui_story_5036_50360702_7_dialog_content = "謝謝歌爾蒂小姐前來相救。",
  ui_story_5036_50360702_8_dialog_content = "歌爾蒂小姐真人和海報上一樣漂亮……不對，比海報上更漂亮！",
  ui_story_5036_50360702_9_dialog_content = "是歌爾蒂小姐！？",
  ui_story_5036_50360702_10_dialog_content = "我從妳剛出道開始就是「蒂蒂人」了！",
  ui_story_5036_50360702_11_dialog_content = "歌爾蒂小姐，可以幫我在這裡簽個名嗎？",
  ui_story_5036_50360702_12_dialog_content = "歌爾蒂！歌爾蒂！歌爾蒂！歌爾蒂！",
  ui_story_5036_50360702_13_dialog_content = "抱歉，稍後我會安排人過來把這裡的通風口堵死，再給大家發放一些食物。",
  ui_story_5036_50360702_14_dialog_content = "都怪那個小偷，要不是他撞開了通風口，就不會有這麼多事！",
  ui_story_5036_50360702_15_dialog_content = "而且他跳的舞真的超級難看！",
  ui_story_5036_50360702_16_dialog_content = "趕下去！趕下去！趕下去！趕下去！",
  ui_story_5036_50360702_17_dialog_content = "可是……",
  ui_story_5036_50360702_18_dialog_content = "可是我真的很想通過海選。",
  ui_story_5036_50360702_19_dialog_content = "是嗎？",
  ui_story_5036_50360702_20_dialog_content = "你真的有決心走到最後嗎？",
  ui_story_5036_50360702_21_dialog_content = "為了銜尾龍……",
  ui_story_5036_50360702_22_dialog_content = "我必須！",
  ui_story_5036_50360702_23_dialog_content = "我必須走到最後！",
  ui_story_5036_50360702_24_dialog_content = "（這種毫無理由的信念和決心，真是讓人懷念呢。）",
  ui_story_5036_50360702_25_dialog_content = "（當年沒有受過任何訓練的我，也曾經信心滿滿地發誓，自己一定會站上更大的舞台。）",
  ui_story_5036_50360702_26_dialog_content = "（是錯覺嗎？）",
  ui_story_5036_50360702_27_dialog_content = "（為什麼我會在維克身上看到過去自己的影子？）",
  ui_story_5036_50360702_28_dialog_content = "（是因為我們都曾經執著地相信著「相信」的力量嗎？）",
  ui_story_5036_50360702_29_dialog_content = "我一定要走到最後！",
  ui_story_5036_50360702_30_dialog_content = "……",
  ui_story_5036_50360702_31_dialog_content = "好，我就再相信你最後一次。",
  ui_story_5036_50360702_32_dialog_content = "趕下去！趕下去！趕下去！趕下去！",
  ui_story_5036_50360702_33_dialog_content = "大家聽我說哦～",
  ui_story_5036_50360702_34_dialog_content = "因為種種誤會，之前我們把維克當成了幽靈小偷。",
  ui_story_5036_50360702_35_dialog_content = "現在已解開誤會了，維克也已經物歸原主，並答應付出相應的賠償。",
  ui_story_5036_50360702_36_dialog_content = "所以我們同意讓維克繼續參加接下來的比賽。",
  ui_story_5036_50360702_37_dialog_content = "但是維克的所作所為，還是在一定程度上干擾了比賽的籌備工作。",
  ui_story_5036_50360702_38_dialog_content = "因此我們只會再給維克最後一次參加比賽的機會。",
  ui_story_5036_50360702_39_dialog_content = "如果到時候維克仍然沒有通過，我們會立刻把他趕下去。",
  ui_story_5036_50360702_40_dialog_content = "只剩下這麼一兩天，就算再怎麼訓練，他也不可能有什麼進步。",
  ui_story_5036_50360702_41_dialog_content = "既然歌爾蒂小姐都這麼說了……",
  ui_story_5036_50360702_42_dialog_content = "我相信歌爾蒂小姐的判斷！",
  ui_story_5036_50360702_43_dialog_content = "哼，如果到時候這傢伙用這種舞蹈也能通過比賽……",
  ui_story_5036_50360702_44_dialog_content = "我可要質疑歌爾蒂小姐舉辦這場海選的用意了。",
  ui_story_5036_50360702_45_dialog_content = "請大家放心吧，我絕對不會辜負大家對我的信任～",
  ui_story_5036_50360702_46_dialog_content = "歌爾蒂！歌爾蒂！歌爾蒂！歌爾蒂！",
  ui_story_5036_50360702_47_dialog_content = "咳咳，謝謝妳，歌爾蒂小姐。",
  ui_story_5036_50360702_48_dialog_content = "還待在這裡做什麼？",
  ui_story_5036_50360702_49_dialog_content = "嗯？",
  ui_story_5036_50360702_50_dialog_content = "找個房間開始排練節目吧。",
  ui_story_5036_50360702_51_dialog_content = "可是現在已經很晚……",
  ui_story_5036_50360702_52_dialog_content = "我說過，你的聲音條件非常好，外形條件也十分出眾。",
  ui_story_5036_50360702_53_dialog_content = "在這一點上，你已經領先了許多人一大步。",
  ui_story_5036_50360702_54_dialog_content = "但如果你真的想要走到最後……",
  ui_story_5036_50360702_55_dialog_content = "就要照我所說的去做。",
  ui_story_5036_50360801_1_dialog_content = "<color=#e8d9bb>距離演唱會開始還有三天</color>",
  ui_story_5036_50360801_2_dialog_content = "♪啊～嗷～～～",
  ui_story_5036_50360801_3_dialog_content = "停一下！",
  ui_story_5036_50360801_4_dialog_content = "這就是你想要演唱的歌曲嗎？",
  ui_story_5036_50360801_5_dialog_content = "嘿嘿，我早就說過我準備了合適的節目嘛，你們還不相信。",
  ui_story_5036_50360801_6_dialog_content = "這首歌真的合適嗎？",
  ui_story_5036_50360801_7_dialog_content = "這首旋律是我專程跑到北境的深山密林裡，向難得一遇的極光夜鶯請教來的。",
  ui_story_5036_50360801_8_dialog_content = "再加上神奇動物專家的我所傾力寫下，充滿狂野氣息的歌詞……",
  ui_story_5036_50360801_9_dialog_content = "這首歌想不搭都不行呢。",
  ui_story_5036_50360801_10_dialog_content = "咳咳……",
  ui_story_5036_50360801_11_dialog_content = "你的歌曲沒有什麼問題，但是你的唱功還有很大的進步空間。",
  ui_story_5036_50360801_12_dialog_content = "歌爾蒂的評價太委婉了吧！",
  ui_story_5036_50360801_13_dialog_content = "的確是非常委婉了。",
  ui_story_5036_50360801_14_dialog_content = "PlayerName也就算了，為什麼連記者小姐也要一起嘲笑我？",
  ui_story_5036_50360801_15_dialog_content = "我……只是實話實說。",
  ui_story_5036_50360801_16_dialog_content = "珀蘭蒂是一位觀點中立、心地善良的專業記者。",
  ui_story_5036_50360801_17_dialog_content = "如果你的歌聲無法打動她，就需要想想問題到底出在哪裡。",
  ui_story_5036_50360801_18_dialog_content = "難道是？記者小姐，妳的耳朵受過傷嗎？所以才聽不出我歌喉的美妙？",
  ui_story_5036_50360801_19_dialog_content = "不是那個啦！",
  ui_story_5036_50360801_20_dialog_content = "呃唔，總而言之……",
  ui_story_5036_50360801_21_dialog_content = "想要唱好一首歌，首先要學會正確的呼吸方法。",
  ui_story_5036_50360801_22_dialog_content = "呼吸方法還需要學習嗎？",
  ui_story_5036_50360801_23_dialog_content = "如果你還想通過海選，就照我說的做。",
  ui_story_5036_50360801_24_dialog_content = "好的，歌爾蒂老師！",
  ui_story_5036_50360801_25_dialog_content = "吸氣的時候把肚子鼓起來，呼氣的時候把肚子縮回去。",
  ui_story_5036_50360801_26_dialog_content = "這就是所謂的腹式呼吸法。",
  ui_story_5036_50360801_27_dialog_content = "先練習十分鐘左右吧。",
  ui_story_5036_50360801_28_dialog_content = "聽起來很像小毛球平常睡覺的樣子啊。",
  ui_story_5036_50360801_29_dialog_content = "呼～吸～",
  ui_story_5036_50360801_30_dialog_content = "不錯，氣息再長一些。",
  ui_story_5036_50360801_31_dialog_content = "呼——吸——",
  ui_story_5036_50360801_32_dialog_content = "很好，繼續保持。",
  ui_story_5036_50360801_33_dialog_content = "呼……吸……",
  ui_story_5036_50360801_34_dialog_content = "呼……呼……",
  ui_story_5036_50360801_35_dialog_content = "維克是不是，睡著了？",
  ui_story_5036_50360801_36_dialog_content = "呼……呼……呼……",
  ui_story_5036_50360801_37_dialog_content = "維克！",
  ui_story_5036_50360801_38_dialog_content = "菲雅別生氣！欸？",
  ui_story_5036_50360801_39_dialog_content = "哦！是歌爾蒂小姐……哦不，是歌爾蒂老師啊。",
  ui_story_5036_50360801_40_dialog_content = "讓你練習呼吸，沒讓你練習睡覺啦。",
  ui_story_5036_50360801_41_dialog_content = "<color=#e8d9bb>一段時間後</color>",
  ui_story_5036_50360801_42_dialog_content = "學會如何呼吸後，就可以開始練習發聲了。",
  ui_story_5036_50360801_43_dialog_content = "維克，你的音色很好，但是切記！",
  ui_story_5036_50360801_44_dialog_content = "如果沒有良好的發音技巧，一味扯著嗓子唱歌，會對聲帶造成永久性的傷害。",
  ui_story_5036_50360801_45_dialog_content = "可是歌爾蒂老師，如何才能擁有良好的發音技巧呢？",
  ui_story_5036_50360801_46_dialog_content = "問得好。",
  ui_story_5036_50360801_47_dialog_content = "為師這就傳授你獨家祕笈——打嘟嚕！",
  ui_story_5036_50360801_48_dialog_content = "仔細看清楚哦～把嘴巴噘起來，然後！",
  ui_story_5036_50360801_49_dialog_content = "嘟嚕嚕嚕嚕嚕……",
  ui_story_5036_50360801_50_dialog_content = "嘟嚕嚕嚕嚕嚕……",
  ui_story_5036_50360801_51_dialog_content = "欸？做得很好，你學得好快呀！",
  ui_story_5036_50360801_52_dialog_content = "哈哈，這個一點都難不倒我！",
  ui_story_5036_50360801_53_dialog_content = "我在野外有時會發出這種聲音，來吸引發情的泥地犀牛。",
  ui_story_5036_50360801_54_dialog_content = "嘟嚕嚕嚕嚕嚕……",
  ui_story_5036_50360801_55_dialog_content = "狀況好的時候，一次能吸引過來十幾頭呢。",
  ui_story_5036_50360801_56_dialog_content = "是……是嗎？",
  ui_story_5036_50360801_57_dialog_content = "還好我們現在是在空中。",
  ui_story_5036_50360801_58_dialog_content = "總之，這個練習不僅可以訓練聲音的穿透力，還可以解決氣息不足的問題。",
  ui_story_5036_50360801_59_dialog_content = "雖然距離最後一次海選只剩下不到兩天的時間。",
  ui_story_5036_50360801_60_dialog_content = "但是如果你勤加練習，一天時間也足夠讓你形成肌肉記憶，改善你在歌唱方面的問題。",
  ui_story_5036_50360801_61_dialog_content = "學習泥地犀牛的叫聲，就可以改善歌唱問題嗎？",
  ui_story_5036_50360801_62_dialog_content = "身為好學生的我可以舉一反三，試著多模仿一些神奇動物的叫聲！",
  ui_story_5036_50360801_63_dialog_content = "嗨，嗨嗨！",
  ui_story_5036_50360801_64_dialog_content = "嗨？",
  ui_story_5036_50360801_65_dialog_content = "咕，咕咕咕咕。",
  ui_story_5036_50360801_66_dialog_content = "咕？",
  ui_story_5036_50360801_67_dialog_content = "嗚啾～嗚啾嗚啾～",
  ui_story_5036_50360801_68_dialog_content = "嗚？",
  ui_story_5036_50360801_69_dialog_content = "好……好了啦。",
  ui_story_5036_50360801_70_dialog_content = "只練習泥地犀牛的叫聲就可以了。",
  ui_story_5036_50360801_71_dialog_content = "哦？看來是我多此一舉了呢。",
  ui_story_5036_50360801_72_dialog_content = "真正需要下功夫的還有一個地方——舞蹈。",
  ui_story_5036_50360801_73_dialog_content = "演唱只是表演的一部分，而舞蹈動作會為表演增添不少魅力。",
  ui_story_5036_50360801_74_dialog_content = "我們還需要為你的這首歌編排一支舞蹈。",
  ui_story_5036_50360801_75_dialog_content = "在此之前，我想先看看你的身體協調性如何。",
  ui_story_5036_50360801_76_dialog_content = "我會做幾種簡單的舞蹈動作，你在旁邊盡量跟上就好。",
  ui_story_5036_50360801_77_dialog_content = "PlayerName，伴奏就拜託你囉～",
  ui_story_5036_50360801_78_dialog_content = "好，我來彈琴！",
  ui_story_5036_50360801_79_dialog_content = "音樂已經開始了，維克，跟上節奏哦！",
  ui_story_5036_50360801_80_dialog_content = "一噠、二噠！腳步、移動！",
  ui_story_5036_50360801_81_dialog_content = "左點、一下！右點、一下！",
  ui_story_5036_50360801_82_dialog_content = "呃，左……右……忽然發現我好像分不清左右了！？",
  ui_story_5036_50360801_83_dialog_content = "接著，舉手！空中、畫圈！",
  ui_story_5036_50360801_84_dialog_content = "左手、推出去、收回來！",
  ui_story_5036_50360801_85_dialog_content = "右手、推出去、收回來！",
  ui_story_5036_50360801_86_dialog_content = "左腳……呃，已經換右手了嗎！？",
  ui_story_5036_50360801_87_dialog_content = "不要停下腳部的動作哦～",
  ui_story_5036_50360801_88_dialog_content = "啊？我……沒有看錯吧？",
  ui_story_5036_50360801_89_dialog_content = "歌爾蒂小姐……",
  ui_story_5036_50360801_90_dialog_content = "歌爾蒂小姐……紅遍整個影鎮的歌爾蒂小姐，正在我的面前跳舞？",
  ui_story_5036_50360801_91_dialog_content = "就算是最資深的「蒂蒂人」也從沒有過這種待遇！",
  ui_story_5036_50360801_X91_dialog_content = "冷靜，我要保持冷靜，那件事情我還沒有查清楚……",
  ui_story_5036_50360801_92_dialog_content = "可她的舞姿在維克的襯托下顯得更加曼妙、輕盈了。",
  ui_story_5036_50360801_93_dialog_content = "我要趕緊記錄下來！",
  ui_story_5036_50360801_94_dialog_content = "手臂指向遠方，像是抓住了夢想一樣，收回到胸口～",
  ui_story_5036_50360801_95_dialog_content = "一噠、二噠！腳步、跳動！",
  ui_story_5036_50360801_96_dialog_content = "左邊揮揮手！右邊揮揮手！",
  ui_story_5036_50360801_97_dialog_content = "呼......呼……還沒有結束嗎？",
  ui_story_5036_50360801_98_dialog_content = "最後，讓我們舉起雙手～",
  ui_story_5036_50360801_99_dialog_content = "轉一個圈圈！",
  ui_story_5036_50360801_100_dialog_content = "轉……圈圈！",
  ui_story_5036_50360801_101_dialog_content = "<color=#e8d9bb>咚！！！</color>",
  ui_story_5036_50360801_102_dialog_content = "哎唷，痛痛痛……",
  ui_story_5036_50360801_103_dialog_content = "這已經是維克今天第幾次摔倒了？",
  ui_story_5036_50360801_104_dialog_content = "沒事，我已經習慣了，哈哈哈。",
  ui_story_5036_50360801_105_dialog_content = "難以置信，你的身體協調性還不如剛學會走路的小朋友。",
  ui_story_5036_50360801_106_dialog_content = "而且只是做了這幾項動作，你的氣息就已經紊亂了，平常你一點都不鍛鍊身體的嗎？",
  ui_story_5036_50360801_107_dialog_content = "如果睡覺也算是鍛鍊身體的話？",
  ui_story_5036_50360801_108_dialog_content = "這下難辦了，協調性可不是一朝一夕就能練好的。",
  ui_story_5036_50360801_109_dialog_content = "<color=#e8d9bb>又過了一段時間</color>",
  ui_story_5036_50360801_110_dialog_content = "這套舞步怎麼樣，記得住嗎？",
  ui_story_5036_50360801_111_dialog_content = "不就是走來走去並同時揮揮手嗎？哈哈，記住了！",
  ui_story_5036_50360801_112_dialog_content = "這雖然是最簡單的舞步……",
  ui_story_5036_50360801_113_dialog_content = "但是我要你全身心地投入到歌曲的情境中，用自己的情感來跳舞。",
  ui_story_5036_50360801_114_dialog_content = "用情感跳舞？我不太能理解。",
  ui_story_5036_50360801_115_dialog_content = "維克，你覺得偶像最需要的能力是什麼呢？",
  ui_story_5036_50360801_116_dialog_content = "會唱歌？會跳舞？",
  ui_story_5036_50360801_117_dialog_content = "對，也不對。",
  ui_story_5036_50360801_118_dialog_content = "身為偶像，唱歌跳舞的能力是必要的，這點毫無疑問。",
  ui_story_5036_50360801_119_dialog_content = "但唱歌跳舞只是媒介，一種傳遞訊息的媒介。",
  ui_story_5036_50360801_120_dialog_content = "對偶像而言最重要的，是擁有絕不屈服、絕不退讓的信念與熱情。",
  ui_story_5036_50360801_121_dialog_content = "然後透過唱歌跳舞，把信念與熱情傳遞給大家。",
  ui_story_5036_50360801_122_dialog_content = "嗯……",
  ui_story_5036_50360801_123_dialog_content = "<size=35>這一點，也許他已經做到了吧。</size>",
  ui_story_5036_50360801_124_dialog_content = "欸？老師說什麼？",
  ui_story_5036_50360801_125_dialog_content = "咳咳，還是要先打動自己，才能打動別人。",
  ui_story_5036_50360801_126_dialog_content = "該說的我都說了，接下來只能靠你自己努力了。",
  ui_story_5036_50360801_127_dialog_content = "在正式的海選現場，我是不會放水的哦～",
  ui_story_5036_50360801_128_dialog_content = "算起來還有一天半的時間。",
  ui_story_5036_50360801_129_dialog_content = "只要再努力一天半，我就可以留下來繼續找銜尾龍了！",
  ui_story_5036_50360801_130_dialog_content = "呃，歌爾蒂！",
  ui_story_5036_50360801_131_dialog_content = "非常謝謝妳，結果到頭來，還是麻煩了妳。",
  ui_story_5036_50360801_132_dialog_content = "不客氣啦，為選手提供對策本來就是我應該做的，別放在心上哦～",
  ui_story_5036_50360801_133_dialog_content = "說真的，我以為維克惹了這麼多麻煩，妳不會再幫他了。",
  ui_story_5036_50360801_134_dialog_content = "說實話，維克真的很棘手呢～",
  ui_story_5036_50360801_135_dialog_content = "可是維克身上的潛力實在是不可限量。",
  ui_story_5036_50360801_136_dialog_content = "如果他真的能夠走上偶像的道路，對我來說也是一種激勵～",
  ui_story_5036_50360801_137_dialog_content = "嗯？你們兩個在說我的好話？",
  ui_story_5036_50360801_138_dialog_content = "讓我也聽聽吧？",
  ui_story_5036_50360801_139_dialog_content = "對了，差點忘記最重要的事了。",
  ui_story_5036_50360801_140_dialog_content = "對偶像而言，充沛的體力是一切活動的基本。",
  ui_story_5036_50360801_141_dialog_content = "我剛好有一種增強體力的祕訣，想知道嗎？",
  ui_story_5036_50360801_142_dialog_content = "欸？這是從哪裡拉過來一籠子的暗鬼啊？",
  ui_story_5036_50360801_143_dialog_content = "哼哼，當然是抓來的啦。",
  ui_story_5036_50360801_144_dialog_content = "吼！",
  ui_story_5036_50360801_145_dialog_content = "妳說的祕訣，該不會是和暗鬼戰鬥吧？",
  ui_story_5036_50360801_146_dialog_content = "把你的神奇動物們放一邊。",
  ui_story_5036_50360801_147_dialog_content = "這次要靠你自己囉～",
  ui_story_5036_50360801_148_dialog_content = "啊？",
  ui_story_5036_50360801_149_dialog_content = "吼！！！",
  ui_story_5036_50360801_150_dialog_content = "別過來啊！",
  ui_story_5036_50360801_151_dialog_content = "我就知道，你自己也可以和暗鬼戰鬥的！",
  ui_story_5036_50360801_152_dialog_content = "可是我不想這麼累啊！",
  ui_story_5036_50360801_153_dialog_content = "別停下！",
  ui_story_5036_50360801_154_dialog_content = "一邊戰鬥，一邊唱歌，一邊跳舞！",
  ui_story_5036_50360801_155_dialog_content = "啊？ ？ ？",
  ui_story_5036_50360801_156_dialog_content = "真正的魔鬼……原來是妳啊？",
  ui_story_5036_50360801_157_dialog_content = "吼——！",
  ui_story_5036_50360802_1_dialog_content = "<color=#e8d9bb>距離演唱會開始還有兩天</color>",
  ui_story_5036_50360802_2_dialog_content = "現場的朋友們舉起手來！我們一起……",
  ui_story_5036_50360802_3_dialog_content = "再來一遍！",
  ui_story_5036_50360802_4_dialog_content = "那......那真的是前幾天我們遇到的那個小偷？",
  ui_story_5036_50360802_5_dialog_content = "好像是，但又好像不是？",
  ui_story_5036_50360802_6_dialog_content = "♪又到了萬物復甦的春天♪",
  ui_story_5036_50360802_7_dialog_content = "♪動物們忙碌地走出家園♪",
  ui_story_5036_50360802_8_dialog_content = "♪無論在森林還是在那荒原♪",
  ui_story_5036_50360802_9_dialog_content = "♪到處都洋溢著蜜語甜言♪",
  ui_story_5036_50360802_10_dialog_content = "雖然完全聽不懂他在唱什麼……",
  ui_story_5036_50360802_11_dialog_content = "但是身體忍不住隨著他的歌曲在搖擺？",
  ui_story_5036_50360802_12_dialog_content = "♪來啊，看啊，那是什麼♪",
  ui_story_5036_50360802_13_dialog_content = "♪滿身茸毛的比卡？它最愛說「嗨」♪",
  ui_story_5036_50360802_14_dialog_content = "嗨嗨嗨～",
  ui_story_5036_50360802_15_dialog_content = "嗨嗨嗨！",
  ui_story_5036_50360802_16_dialog_content = "♪來啊，看啊，那是什麼♪",
  ui_story_5036_50360802_17_dialog_content = "♪轉角遇到了泥尊鷹？要小心口袋♪",
  ui_story_5036_50360802_18_dialog_content = "咕咕咕～",
  ui_story_5036_50360802_19_dialog_content = "咕咕咕！",
  ui_story_5036_50360802_20_dialog_content = "歌爾蒂，這個維克是找人假扮的嗎？",
  ui_story_5036_50360802_21_dialog_content = "欸？",
  ui_story_5036_50360802_22_dialog_content = "我是說……短短一天半的時間，他就能有這麼大的進步！？",
  ui_story_5036_50360802_23_dialog_content = "我已經完全認不出眼前的人是維克了。",
  ui_story_5036_50360802_24_dialog_content = "簡直像是換了一個人！",
  ui_story_5036_50360802_25_dialog_content = "我早就說過啦，維克非常有成為偶像的潛力。",
  ui_story_5036_50360802_26_dialog_content = "他就像是一塊寶玉的原石，只要稍加打磨就能發出耀眼奪目的光芒。",
  ui_story_5036_50360802_27_dialog_content = "養成的快樂！",
  ui_story_5036_50360802_28_dialog_content = "這就是養成的快樂啊，懂了嗎？",
  ui_story_5036_50360802_29_dialog_content = "唱歌、跳舞、顏值、身材、情商、智商，六項分數幾近全滿。",
  ui_story_5036_50360802_30_dialog_content = "海選到現在終於出現了唯一一位全能選手！",
  ui_story_5036_50360802_31_dialog_content = "我竟然看這種表演看入了迷！？",
  ui_story_5036_50360802_32_dialog_content = "……我的光之神啊，請原諒我吧。",
  ui_story_5036_50360802_33_dialog_content = "嗯，進步很大。",
  ui_story_5036_50360802_34_dialog_content = "♪嘟嚕嚕嚕嚕嚕……♪",
  ui_story_5036_50360802_35_dialog_content = "♪有沒有見過銜尾龍的蛋殼♪",
  ui_story_5036_50360802_36_dialog_content = "♪嘟嚕嚕嚕嚕嚕……♪",
  ui_story_5036_50360802_37_dialog_content = "♪用盡全力也要尋找到你♪",
  ui_story_5036_50360802_38_dialog_content = "嘿，我的表演到此為止，謝謝大家～",
  ui_story_5036_50360802_39_dialog_content = "維克！維克！維克！維克！",
  ui_story_5036_50360802_40_dialog_content = "我們可以看到，整個賽場都被這首舞曲點燃了！",
  ui_story_5036_50360802_41_dialog_content = "謝謝維克選手帶來的精彩表演！",
  ui_story_5036_50360802_42_dialog_content = "但不知道我們嚴格的評審們會如何點評呢？",
  ui_story_5036_50360802_43_dialog_content = "有請歌爾蒂小姐發言！",
  ui_story_5036_50360802_44_dialog_content = "我沒什麼好說的。",
  ui_story_5036_50360802_45_dialog_content = "啊？我從前天晚上練到現在一直沒睡覺欸，這樣都沒辦法過關嗎？",
  ui_story_5036_50360802_46_dialog_content = "早知道還不如躺著睡覺呢。",
  ui_story_5036_50360802_47_dialog_content = "我的意思是，維克選手的表演很出色，我已經沒有什麼可建議的了。",
  ui_story_5036_50360802_48_dialog_content = "我相信投票結果可以說明一切。",
  ui_story_5036_50360802_49_dialog_content = "好的，最終投票結果已經出來了。",
  ui_story_5036_50360802_50_dialog_content = "讓我們看看，維克選手究竟能不能獲得登上舞台的機會吧！",
  ui_story_5036_50360802_51_dialog_content = "結果就是……",
  ui_story_5036_50360802_52_dialog_content = "就是？",
  ui_story_5036_50360802_53_dialog_content = "<size=45>全票通過！</size>",
  ui_story_5036_50360802_54_dialog_content = "嗯哼？連那個菜鳥都通過海選了耶。現在某人的壓力一定很大吧？",
  ui_story_5036_50360802_55_dialog_content = "芭芭拉要不要唱一首元氣滿滿的加油歌送給她呢？",
  ui_story_5036_50360802_56_dialog_content = "別在我面前賣弄了，我可用不著聽妳唱的無腦歌曲。",
  ui_story_5036_50360802_57_dialog_content = "如果妳沒有通過，芭芭拉可是會很寂寞的哦。",
  ui_story_5036_50360802_58_dialog_content = "妳能早一步通過海選，不過是因為出場順序比我前面。",
  ui_story_5036_50360802_59_dialog_content = "等著吧，評審們看完我的表演後，就會後悔讓你們這些菜鳥通過！",
  ui_story_5036_50360802_60_dialog_content = "維克選手，現在你的心情如何？",
  ui_story_5036_50360802_61_dialog_content = "終於可以……睡個好覺了……",
  ui_story_5036_50360802_62_dialog_content = "等睡醒了……我……",
  ui_story_5036_50360802_63_dialog_content = "就可以去找……銜尾……",
  ui_story_5036_50360802_64_dialog_content = "維克選手？",
  ui_story_5036_50360802_65_dialog_content = "維克選手！你怎麼了？",
  ui_story_5036_50360802_66_dialog_content = "呼……呼……呼……",
  ui_story_5036_50360802_67_dialog_content = "呃，維克選手。",
  ui_story_5036_50360802_68_dialog_content = "請不要在海選現場睡覺呀！",
  ui_story_5036_50360802_69_dialog_content = "維克睡得也太沉了吧。",
  ui_story_5036_50360802_70_dialog_content = "居然可以在吵鬧的海選現場睡上一整天！",
  ui_story_5036_50360802_71_dialog_content = "是啊，剛才被傭兵們抬回房間的時候，他也沒有醒過來。",
  ui_story_5036_50360802_72_dialog_content = "他的進步有目共睹。",
  ui_story_5036_50360802_73_dialog_content = "應該是這兩天訓練得太拼命，所以他才會這麼累吧？",
  ui_story_5036_50360802_74_dialog_content = "依我看，妳們兩位也很拼命訓練吧？",
  ui_story_5036_50360802_75_dialog_content = "不然也不會全票通過海選。",
  ui_story_5036_50360802_76_dialog_content = "呼～這是意料之中的結果哦。",
  ui_story_5036_50360802_77_dialog_content = "不過還真是有點累了呢。",
  ui_story_5036_50360802_78_dialog_content = "今天我們也早點休息吧。",
  ui_story_5036_50360802_79_dialog_content = "明天的節目彩排還要忙一整天呢。",
  ui_story_5036_50360802_80_dialog_content = "希望今天不會再做夢了。",
  ui_story_5036_50360802_81_dialog_content = "嗯，晚安。",
  ui_story_5036_50360802_82_dialog_content = "欸，薇絲？卡蓮？",
  ui_story_5036_50360802_83_dialog_content = "怎麼走得這麼快？",
  ui_story_5036_50360802_84_dialog_content = "那……",
  ui_story_5036_50360802_85_dialog_content = "我也早點休息吧。",
  ui_story_5036_50360901_1_dialog_content = "這是哪裡……？",
  ui_story_5036_50360901_2_dialog_content = "好像是巨像上，那是之前夢裡的那個空裔？",
  ui_story_5036_50360901_3_dialog_content = "我又在做夢嗎？",
  ui_story_5036_50360901_4_dialog_content = "你就是「歌頌者號」了吧？",
  ui_story_5036_50360901_5_dialog_content = "是的，我猜，妳是我的新導航員？",
  ui_story_5036_50360901_6_dialog_content = "沒錯！我叫夏米娜德，以後請多指教啦。",
  ui_story_5036_50360901_7_dialog_content = "（場景發生變化了，這次好像是巨像的艦橋？）",
  ui_story_5036_50360901_8_dialog_content = "歌頌者號，為什麼你有這麼多螢幕和奇怪的音響設備？",
  ui_story_5036_50360901_9_dialog_content = "我問了其他夥伴，他們都說沒有在其他巨像上見過這樣的設備。",
  ui_story_5036_50360901_10_dialog_content = "關於這件事，就算是我也不知道原因。",
  ui_story_5036_50360901_11_dialog_content = "那些久遠的記憶就像乘風而去的歌聲，已經消散無蹤了。",
  ui_story_5036_50360901_12_dialog_content = "真可惜啊……",
  ui_story_5036_50360901_13_dialog_content = "不過，大家都很喜歡歌頌者號哦！",
  ui_story_5036_50360901_14_dialog_content = "畢竟只有歌頌者號能讓樂聲響徹整個空之山谷。",
  ui_story_5036_50360901_15_dialog_content = "謝謝，能聽到妳這麼說，我很高興。",
  ui_story_5036_50360901_16_dialog_content = "歌頌者號，我們去旅行吧！",
  ui_story_5036_50360901_17_dialog_content = "咦？怎麼突然這麼說？",
  ui_story_5036_50360901_18_dialog_content = "今天聽老師說，艾斯特拉大陸上還有很多人因為戰爭和暗鬼而感到困擾。",
  ui_story_5036_50360901_19_dialog_content = "他們過著困難的生活，看不到希望，所以我想去為他們唱歌！",
  ui_story_5036_50360901_20_dialog_content = "我知道我的歌聲並不能打敗暗鬼或為他們帶來什麼……",
  ui_story_5036_50360901_21_dialog_content = "但是至少，我想讓他們聽見槍砲聲以外的聲音。",
  ui_story_5036_50360901_22_dialog_content = "那樣的地方對妳來說太危險了。",
  ui_story_5036_50360901_23_dialog_content = "我知道，但如果我的歌聲能帶給他們一絲慰藉和希望的話，無論多麼危險我都不怕。",
  ui_story_5036_50360901_24_dialog_content = "明白了。",
  ui_story_5036_50360901_25_dialog_content = "那我們出發吧。",
  ui_story_5036_50360901_26_dialog_content = "又是夢嗎？這次好像和之前的夢不一樣，更像是……某種記憶？",
  ui_story_5036_50360901_27_dialog_content = "夏米娜德，這是那個空裔女孩的名字嗎？",
  ui_story_5036_50360901_28_dialog_content = "難道說，剛才的夢境是我無意中感應到了空裔殘留在過去的情感？",
  ui_story_5036_50360901_29_dialog_content = "乘坐巨像在艾斯特拉巡迴演唱的空裔，感覺她就像歌爾蒂一樣。",
  ui_story_5036_50360901_30_dialog_content = "呵欠——夢到一大堆畫面，實際上就只睡了一個小時。",
  ui_story_5036_50360901_31_dialog_content = "一時半會兒睡不著，要不要去找點東西吃呢……",
  ui_story_5036_50360901_32_dialog_content = "<color=#e8d9bb>咚咚咚——！</color>",
  ui_story_5036_50360901_33_dialog_content = "（這麼晚了，是誰在敲門？）",
  ui_story_5036_50360901_34_dialog_content = "來了來了！",
  ui_story_5036_50360901_35_dialog_content = "PlayerName，抱歉，打擾到你休息了嗎？",
  ui_story_5036_50360901_36_dialog_content = "歌爾蒂，妳怎麼來了？我剛剛睡醒。",
  ui_story_5036_50360901_37_dialog_content = "有件事希望你能幫忙，事關演唱會能否順利舉辦！",
  ui_story_5036_50360901_38_dialog_content = "啊？這麼嚴重！？難道歌頌者號要墜機了？",
  ui_story_5036_50360901_39_dialog_content = "倒沒有那麼嚴重啦……你最近有沒有做過一個怪夢？",
  ui_story_5036_50360901_40_dialog_content = "夢裡有一片空曠的山谷，裡面還有小女孩唱歌的聲音。",
  ui_story_5036_50360901_41_dialog_content = "有啊，不知道為什麼，我最近每天晚上都會做那個夢。",
  ui_story_5036_50360901_42_dialog_content = "在空之山谷裡，有一個陌生的空裔女孩在唱歌。",
  ui_story_5036_50360901_43_dialog_content = "原來她是空裔嗎！？",
  ui_story_5036_50360901_44_dialog_content = "空裔應該很好辨認？畢竟我們的服裝都很特殊。",
  ui_story_5036_50360901_45_dialog_content = "雖然很奇怪，但因為也不是什麼惡夢，所以我就沒有理它。",
  ui_story_5036_50360901_46_dialog_content = "等一下，之前不是討論過，認為是巧合嗎？",
  ui_story_5036_50360901_47_dialog_content = "我原本也是這麼想的，但現在，巨像上的大家都做了這個夢！",
  ui_story_5036_50360901_48_dialog_content = "所有人都做了同樣的夢！？",
  ui_story_5036_50360901_49_dialog_content = "是的。一兩個人還能說是巧合，但所有人都做同一個夢，未免太奇怪了！",
  ui_story_5036_50360901_50_dialog_content = "就是因為發生了這件怪事，所以大家都感到不安。",
  ui_story_5036_50360901_51_dialog_content = "最近兩天，越來越多參與者找我抱怨，說怪夢影響到他們休息了。",
  ui_story_5036_50360901_52_dialog_content = "如果不能好好休息，大家在演唱會上的發揮也會受到影響。",
  ui_story_5036_50360901_53_dialog_content = "所以，妳是想找出怪夢的源頭，讓大家能好好休息？",
  ui_story_5036_50360901_54_dialog_content = "嗯……我也嘗試自己調查過，但是因為沒有空裔的感應能力，始終一無所獲。",
  ui_story_5036_50360901_55_dialog_content = "PlayerName，能幫幫我嗎？",
  ui_story_5036_50360901_56_dialog_content = "當然了，為了能讓演唱會順利舉行，我一定會幫忙！",
  ui_story_5036_50360901_57_dialog_content = "謝謝！",
  ui_story_5036_50360901_58_dialog_content = "但是，歌頌者號這麼大，就算我有感應能力，也沒辦法一次覆蓋到整艘巨像。",
  ui_story_5036_50360901_59_dialog_content = "我們應該從哪裡查起呢？",
  ui_story_5036_50360901_60_dialog_content = "我也不知道……",
  ui_story_5036_50360901_61_dialog_content = "先從巨像尾部查起比較好哦～",
  ui_story_5036_50360901_62_dialog_content = "維克！？你從哪裡冒出來的？",
  ui_story_5036_50360901_63_dialog_content = "後天就要正式舉辦演唱會了，你不去多花點時間訓練嗎？",
  ui_story_5036_50360901_64_dialog_content = "哎呀，我這不是聽到你們正在為怪夢發愁嗎？",
  ui_story_5036_50360901_65_dialog_content = "要先確保睡眠品質，才能養足精神訓練呀。",
  ui_story_5036_50360901_66_dialog_content = "確實是這樣沒錯，但從維克你嘴裡說出來，就覺得不太可靠。",
  ui_story_5036_50360901_67_dialog_content = "哈哈哈，這一定是你的錯覺～",
  ui_story_5036_50360901_68_dialog_content = "難得看你這麼積極，真可疑。",
  ui_story_5036_50360901_69_dialog_content = "我想起來了，你之前就想去巨像尾部尋找銜尾龍，這次你也是為了自己的事吧！",
  ui_story_5036_50360901_70_dialog_content = "怎麼能這麼說呢～多一個人就多一份力，帶上我一起，肯定不吃虧。",
  ui_story_5036_50360901_71_dialog_content = "好吧，不過明天訓練時我會好好看著你的，別想偷懶哦。",
  ui_story_5036_50360901_72_dialog_content = "神奇動物專家是不會說謊的。",
  ui_story_5036_50360901_73_dialog_content = "不過現在，還是讓我們把精力集中在解決怪夢上吧。",
  ui_story_5036_50360901_74_dialog_content = "（維克竟然對這件事這麼用心，還真是可疑。）",
  ui_story_5036_50360901_75_dialog_content = "（他究竟在盤算什麼呢？）",
  ui_story_5036_50360901_76_dialog_content = "巨像的尾部……應該是被暗鬼佔據的封鎖區吧？",
  ui_story_5036_50360901_77_dialog_content = "從那種危險的地方開始調查，有什麼根據嗎？",
  ui_story_5036_50360901_78_dialog_content = "沒有～",
  ui_story_5036_50360901_79_option_content = "我們還是不要理他了",
  ui_story_5036_50360901_80_dialog_content = "PlayerName，我們好歹也是曾經合作過的夥伴，不要說這麼無情的話啊！",
  ui_story_5036_50360901_81_option_content = "……",
  ui_story_5036_50360901_82_dialog_content = "……",
  ui_story_5036_50360901_83_dialog_content = "年輕人就是年輕人，這麼容易感到震驚呢。",
  ui_story_5036_50360901_84_dialog_content = "雖然沒有確實根據，但我會這麼說，也是有原因的。",
  ui_story_5036_50360901_85_dialog_content = "巨像頭部的暗鬼已經全部清理了，大家可以自由活動。",
  ui_story_5036_50360901_86_dialog_content = "也就代表，這些地方已經被探索過了吧？",
  ui_story_5036_50360901_87_dialog_content = "也對，如果有什麼異常的話，啟光和白夜城的大家應該早就發現了。",
  ui_story_5036_50360901_88_dialog_content = "所以說啊，還是尾部更可疑一點吧？",
  ui_story_5036_50360901_89_dialog_content = "可巨像尾部還聚集著那麼多暗鬼，只有我們三個的話，未免太危險了。",
  ui_story_5036_50360901_90_dialog_content = "這種情況我也考慮到了哦，只要讓泥尊鷹幫忙就可以了。",
  ui_story_5036_50360901_91_dialog_content = "讓暗鬼們先陷入沉睡，我們再偷偷溜過去，就能避免大部分戰鬥。",
  ui_story_5036_50360901_92_dialog_content = "你之前偷東西的時候，也是用這種方法？",
  ui_story_5036_50360901_93_dialog_content = "當然——不是！",
  ui_story_5036_50360901_94_dialog_content = "再怎麼說，上一次也只是因為泥尊鷹的習性所造成的誤會。",
  ui_story_5036_50360901_95_dialog_content = "這次讓它來幫忙，就當是將功補過了，這樣如何？",
  ui_story_5036_50360901_96_dialog_content = "算了，這事就先放一邊，等演唱會結束之後再說。",
  ui_story_5036_50360901_97_dialog_content = "維克說的確實有道理，我們就先從巨像尾部開始調查吧。",
  ui_story_5036_50360901_98_dialog_content = "嗯，那我們走吧。",
  ui_story_5036_50360901_99_dialog_content = "本來想找歌爾蒂，問問她關於暴力傾向傳聞的事。",
  ui_story_5036_50360901_100_dialog_content = "沒想到竟然撞見他們三個一起行動！",
  ui_story_5036_50360901_101_dialog_content = "還好剛才離得遠，不然一定會被PlayerName的感應能力發現吧。",
  ui_story_5036_50360901_102_dialog_content = "但離得太遠了，聽不見他們到底說了些什麼。",
  ui_story_5036_50360901_103_dialog_content = "那個方向……難道他們要去巨像的尾部嗎？",
  ui_story_5036_50360901_104_dialog_content = "有點可疑呢，跟上去看看吧！",
  ui_story_5036_50360901_105_dialog_content = "這裡好黑……感覺暗鬼隨時會冒出來，讓人提心吊膽。",
  ui_story_5036_50360901_106_dialog_content = "放心好啦，一切交給泥尊鷹就好，你看。",
  ui_story_5036_50360901_107_dialog_content = "咕咕——！",
  ui_story_5036_50360901_108_dialog_content = "（日蝕語）吞......吞羅大人！？",
  ui_story_5036_50360901_109_dialog_content = "咕咕咕！",
  ui_story_5036_50360901_110_dialog_content = "（日蝕語）感謝誇獎，屬下一定會加倍努力！",
  ui_story_5036_50360901_111_dialog_content = "（日蝕語）竟然能被誇獎，真奇怪……但是，好睏……",
  ui_story_5036_50360901_112_dialog_content = "（日蝕語）呵欠……",
  ui_story_5036_50360901_113_dialog_content = "你看，很順利吧？",
  ui_story_5036_50360901_114_dialog_content = "這麼做真的不是在濫用神奇動物的能力嗎？",
  ui_story_5036_50360901_115_dialog_content = "泥尊鷹是我的朋友，它是自願幫我的，一定是這樣的。",
  ui_story_5036_50360901_116_dialog_content = "這個地方可真黑……",
  ui_story_5036_50360901_117_dialog_content = "嗚，不行，得撐住！",
  ui_story_5036_50360901_118_dialog_content = "歌爾蒂，妳還好嗎？",
  ui_story_5036_50360901_119_dialog_content = "咦！？我......我沒事！",
  ui_story_5036_50360901_120_dialog_content = "偶像怎麼會有事呢，我只是有點累了，想要稍微休息一下。",
  ui_story_5036_50360901_121_dialog_content = "棉花糖，讓我抱抱你。",
  ui_story_5036_50360901_122_dialog_content = "汪嗚！",
  ui_story_5036_50360901_123_dialog_content = "軟綿綿，毛茸茸……嗯，我恢復了！",
  ui_story_5036_50360901_124_dialog_content = "繼續前進吧！",
  ui_story_5036_50360901_125_dialog_content = "（歌爾蒂的樣子很奇怪，難道她怕黑嗎……？）",
  ui_story_5036_50360901_126_dialog_content = "走了這麽久，我們應該已經接近巨像的尾部了。",
  ui_story_5036_50360901_X126_dialog_content = "PlayerName，這附近能感應到什麽嗎？",
  ui_story_5036_50360901_127_dialog_content = "我試試看。",
  ui_story_5036_50360901_128_option_content = "感應！",
  ui_story_5036_50360901_129_dialog_content = "（附近似乎只有睡著的暗鬼。）",
  ui_story_5036_50360901_130_dialog_content = "（不知道為什麼，總有種陰森森的感覺，是我想太多嗎？）",
  ui_story_5036_50360901_131_dialog_content = "（等等，這個感覺是……）",
  ui_story_5036_50360901_132_dialog_content = "（和第一次回空之山谷時的情況很像，好像是過去的空裔留下來的情感！）",
  ui_story_5036_50360901_133_dialog_content = "（試著感應看看吧。）",
  ui_story_5036_50360901_134_dialog_content = "嗚哇！？歌......歌頌者號，這是什麼！？",
  ui_story_5036_50360901_135_dialog_content = "不要驚慌，夏米娜德，這不是暗鬼。",
  ui_story_5036_50360901_136_dialog_content = "根據資料顯示，這應該是一種名為銜尾龍的動物，對光靈和空裔非常友善。",
  ui_story_5036_50360901_137_dialog_content = "太好了，原來不是暗鬼。",
  ui_story_5036_50360901_138_dialog_content = "啾啾！",
  ui_story_5036_50360901_139_dialog_content = "哈哈哈，不要舔我的臉啦。",
  ui_story_5036_50360901_140_dialog_content = "怎麼樣，PlayerName，你感應到什麼了嗎？",
  ui_story_5036_50360901_141_dialog_content = "她果然叫夏米娜德啊……",
  ui_story_5036_50360901_142_dialog_content = "夏米娜德？你是說那個空裔少女的名字嗎？",
  ui_story_5036_50360901_143_dialog_content = "嗯，我感應到了她遺留的一些情感，還有……",
  ui_story_5036_50360901_144_dialog_content = "我感應到了銜尾龍！",
  ui_story_5036_50360901_145_dialog_content = "什麼！？",
  ui_story_5036_50360901_146_dialog_content = "你說你感應到了銜尾龍？快詳細說說！",
  ui_story_5036_50360901_147_dialog_content = "停停停，你先放開我，我要被你搖吐了！",
  ui_story_5036_50360901_148_dialog_content = "你先說，說出來了我才會放手哦～",
  ui_story_5036_50360901_149_dialog_content = "我感應到的不是現在的銜尾龍，是過去的，過去！",
  ui_story_5036_50360901_150_dialog_content = "過去？",
  ui_story_5036_50360901_151_dialog_content = "這艘巨像過去的主人，也就是大家夢見的那個空裔少女，她叫夏米娜德。",
  ui_story_5036_50360901_152_dialog_content = "她曾經遇到過銜尾龍，並且把它留在了巨像上。",
  ui_story_5036_50360901_153_dialog_content = "不過根據調查結果判斷，這件事最遲發生在一百年前。",
  ui_story_5036_50360901_154_dialog_content = "你要找的銜尾龍，大概早就跑得無影無蹤了。",
  ui_story_5036_50360901_155_dialog_content = "唔……",
  ui_story_5036_50360901_156_dialog_content = "你能不能先把我放開？",
  ui_story_5036_50360901_157_dialog_content = "嗯～雖然不是銜尾龍的位置，但這也是不可忽視的情報呢。",
  ui_story_5036_50360901_158_dialog_content = "再幫幫忙，多感應一些呀，小空裔！",
  ui_story_5036_50360901_159_dialog_content = "看在我的愛徒菲雅曾經和你一起冒險的份上，這次就當是你還我的人情！",
  ui_story_5036_50360901_160_dialog_content = "我什麼時候欠你人情了！？",
  ui_story_5036_50360901_161_dialog_content = "等一等！現在不是應該先解決怪夢的問題嗎？",
  ui_story_5036_50360901_162_dialog_content = "怎麼忽然就變成找銜尾龍了？",
  ui_story_5036_50360901_163_dialog_content = "啊，對哦！差一點就被帶偏了！",
  ui_story_5036_50360901_164_dialog_content = "這麼想就錯了哦，年輕人。",
  ui_story_5036_50360901_165_dialog_content = "你剛才說，遇到銜尾龍的空裔，正是出現在大家夢中的那名少女吧？",
  ui_story_5036_50360901_166_dialog_content = "確實呢……就算繼續調查，也會以她為線索。",
  ui_story_5036_50360901_167_dialog_content = "那麼，在調查中如果發現了其他關於銜尾龍的情報，就麻煩你留意啦。",
  ui_story_5036_50360901_168_dialog_content = "怎麼感覺我在給你白打工……",
  ui_story_5036_50360901_169_dialog_content = "這可不是白打工，這是敬老護幼，是值得表揚的行為哦。",
  ui_story_5036_50360901_170_dialog_content = "你這傢伙還真會找理由……",
  ui_story_5036_50360901_171_dialog_content = "過獎，過獎。",
  ui_story_5036_50360901_172_dialog_content = "調查怪夢這件事，果然還是要靠PlayerName才行。",
  ui_story_5036_50360901_173_dialog_content = "PlayerName，能麻煩你再到別的地方感應一下，看看有沒有類似的遺留情感嗎？",
  ui_story_5036_50360901_174_dialog_content = "或許我們能透過這些情感中蘊藏的訊息，找到怪夢的源頭。",
  ui_story_5036_50360901_175_dialog_content = "好，我試試看！",
  ui_story_5036_50360901_176_dialog_content = "這個地方之前沒來過呢。",
  ui_story_5036_50360901_177_dialog_content = "這裡比剛才的走廊更接近巨像尾部，應該能發現一些新線索吧。",
  ui_story_5036_50360901_178_dialog_content = "歌爾蒂、維克，你們有沒有感覺這裡的氣氛有點駭人？",
  ui_story_5036_50360901_179_dialog_content = "好像確實有些冷，難道是暗能造成的嗎？",
  ui_story_5036_50360901_180_dialog_content = "不，我沒有感應到太多暗能，只是覺得莫名有些緊張。",
  ui_story_5036_50360901_181_dialog_content = "哎呀，難道你怕黑嗎？",
  ui_story_5036_50360901_182_dialog_content = "才……才沒有！",
  ui_story_5036_50360901_183_dialog_content = "沒事沒事，不用害羞。",
  ui_story_5036_50360901_184_dialog_content = "詩燁小時候也怕黑哦，晚上經常被風聲嚇得哇哇大哭呢～",
  ui_story_5036_50360901_185_dialog_content = "蒼獅龍除了捕獵鳥類以外，還會——阿嚏！",
  ui_story_5036_50360901_186_dialog_content = "還會打噴嚏？",
  ui_story_5036_50360901_187_dialog_content = "不，不是……阿嚏！",
  ui_story_5036_50360901_188_dialog_content = "只是我突然想打噴嚏而已。",
  ui_story_5036_50360901_189_dialog_content = "詩燁師姐感冒了嗎？",
  ui_story_5036_50360901_190_dialog_content = "沒有。我猜，是維克那傢伙正在某個地方偷說我壞話。",
  ui_story_5036_50360901_191_dialog_content = "等他回來以後，「好好詢問一番」就是了。",
  ui_story_5036_50360901_192_dialog_content = "你又在騙人吧？",
  ui_story_5036_50360901_193_dialog_content = "沒有哦，不信你可以去問詩燁～",
  ui_story_5036_50360901_194_dialog_content = "還是算了，先幹正事。",
  ui_story_5036_50360901_X194_dialog_content = "這附近似乎也有殘留的情感，我試著感應一下。",
  ui_story_5036_50360901_195_option_content = "感應！",
  ui_story_5036_50360901_196_dialog_content = "♪露珠，映著晨曦♪",
  ui_story_5036_50360901_197_dialog_content = "♪閃耀微弱的光芒♪",
  ui_story_5036_50360901_198_dialog_content = "（這首旋律是啟動巨像時用的旋律！）",
  ui_story_5036_50360901_199_dialog_content = "啾啾——啾！",
  ui_story_5036_50360901_200_dialog_content = "唔哇！？銜尾龍，你不是在睡覺嗎？怎麼跑過來了！？",
  ui_story_5036_50360901_201_dialog_content = "啾——♪啾——♪",
  ui_story_5036_50360901_202_dialog_content = "你是在唱歌嗎！？而且是我剛剛在唱的歌？",
  ui_story_5036_50360901_203_dialog_content = "銜尾龍，莫非你能聽懂我的歌聲！？",
  ui_story_5036_50360901_204_dialog_content = "啾——♪啾啾啾♪",
  ui_story_5036_50360901_205_dialog_content = "這種旋律是表示肯定的意思！？",
  ui_story_5036_50360901_206_dialog_content = "真是令人驚訝，這種生物竟然能夠透過空裔操縱巨像的旋律和人交流。",
  ui_story_5036_50360901_207_dialog_content = "我又感應到一段畫面……",
  ui_story_5036_50360901_208_dialog_content = "只不過這些片段都太零散和短暫了。",
  ui_story_5036_50360901_209_dialog_content = "是什麼？說說看吧？",
  ui_story_5036_50360901_210_dialog_content = "他們提到與怪夢有關的事了嗎？",
  ui_story_5036_50360901_211_dialog_content = "不是關於怪夢的。",
  ui_story_5036_50360901_212_dialog_content = "我感應到的是一段驚喜的情感，夏米娜德偶然發現了銜尾龍的祕密。",
  ui_story_5036_50360901_213_dialog_content = "這種生物似乎可以透過空裔，操縱巨像的旋律來表達情感，與人進行交流。",
  ui_story_5036_50360901_214_dialog_content = "哦？這可是關於銜尾龍的新發現！",
  ui_story_5036_50360901_215_dialog_content = "立大功了啊，PlayerName，雖然沒有獎金可給就是啦。",
  ui_story_5036_50360901_216_dialog_content = "……",
  ui_story_5036_50360901_217_dialog_content = "不過說起來，古書上確實提過，銜尾龍與巨像有著難以言喻的關係呢。",
  ui_story_5036_50360901_218_dialog_content = "很難不讓人聯想，銜尾龍是不是也具備某種精神方面的能力。",
  ui_story_5036_50360901_219_dialog_content = "比如說……使人做夢？",
  ui_story_5036_50360901_220_dialog_content = "真的！？",
  ui_story_5036_50360901_221_dialog_content = "你要是再說謊，我可是會對你進行正義制裁的！",
  ui_story_5036_50360901_222_dialog_content = "不不不，我可不敢！",
  ui_story_5036_50360901_223_dialog_content = "不過也只是推論，不能保證百分之百正確～",
  ui_story_5036_50360901_224_dialog_content = "真可疑……",
  ui_story_5036_50360901_225_dialog_content = "PlayerName，你怎麼想？",
  ui_story_5036_50360901_226_option_content = "相信維克",
  ui_story_5036_50360901_227_dialog_content = "雖然維克經常騙人，做事情也不怎麼可靠……",
  ui_story_5036_50360901_228_dialog_content = "但是他對神奇動物的了解是不用懷疑的。",
  ui_story_5036_50360901_229_dialog_content = "相信一下，應該沒什麼問題。",
  ui_story_5036_50360901_230_dialog_content = "沒錯沒錯，不聽老人言，吃虧在眼前～",
  ui_story_5036_50360901_231_dialog_content = "好吧，我相信PlayerName的判斷。",
  ui_story_5036_50360901_232_option_content = "不相信維克",
  ui_story_5036_50360901_233_dialog_content = "我的建議是不要相信他的話，因為他沒說過幾句真話。",
  ui_story_5036_50360901_234_dialog_content = "聽你這麼說，老人家我真的很傷心，嗚嗚……",
  ui_story_5036_50360901_235_dialog_content = "就像現在，他一會兒說自己是老人，一會兒又說自己是永遠的十八歲。",
  ui_story_5036_50360901_236_dialog_content = "年輕人不懂，這叫人老心不老。",
  ui_story_5036_50360901_237_dialog_content = "確實不可信任呢！",
  ui_story_5036_50360901_238_dialog_content = "嗚！",
  ui_story_5036_50360901_239_dialog_content = "只是，目前除了順著這條線索查下去以外，我們也沒有其他辦法了。",
  ui_story_5036_50360901_240_dialog_content = "只能繼續查下去了嗎？唉……不，不可以輕言放棄。",
  ui_story_5036_50360901_241_dialog_content = "我們繼續走吧，去別的地方看看。",
  ui_story_5036_50360901_242_dialog_content = "他們幾個人走走停停的，究竟在幹什麼？",
  ui_story_5036_50360901_243_dialog_content = "竟然在不知不覺間走到封鎖區來了，這裡陰森森的，怪可怕……",
  ui_story_5036_50360901_244_dialog_content = "<color=#e8d9bb>呼——</color>",
  ui_story_5036_50360901_245_dialog_content = "噫！？是......是風聲嗎？要不，還是回去算了吧？改天再找歌爾蒂詢問……",
  ui_story_5036_50360901_246_dialog_content = "不，不行！珀蘭蒂，妳可是追求真相的記者，怎麼能在這裡放棄！",
  ui_story_5036_50360901_247_dialog_content = "我得跟上他們！",
  ui_story_5036_50360901_248_dialog_content = "我們走了多久？二十分鐘？",
  ui_story_5036_50360901_249_dialog_content = "這裡的走廊相當複雜，我們好像在繞圈子呢。",
  ui_story_5036_50360901_250_dialog_content = "PlayerName，你在巨像上生活了這麼久，不如你來帶路？",
  ui_story_5036_50360901_251_dialog_content = "我只熟悉臨空者號，又不清楚這的構造……",
  ui_story_5036_50360901_252_dialog_content = "說的也是呢，要不要試試感應能力？",
  ui_story_5036_50360901_253_dialog_content = "如果附近還殘留著那名空裔的情感，說不定能幫我們指路。",
  ui_story_5036_50360901_254_dialog_content = "有道理，我再試試！",
  ui_story_5036_50360901_255_option_content = "感應！",
  ui_story_5036_50360901_256_dialog_content = "歌頌者號，不好了！",
  ui_story_5036_50360901_257_dialog_content = "銜尾龍變成這個樣子了！",
  ui_story_5036_50360901_258_dialog_content = "嗚嗚……它究竟怎麼了？難道是永遠離開我們了嗎？",
  ui_story_5036_50360901_259_dialog_content = "明明這一路都是靠它幫忙才能躲避暗鬼的襲擊……",
  ui_story_5036_50360901_260_dialog_content = "別擔心，夏米娜德。",
  ui_story_5036_50360901_261_dialog_content = "銜尾龍是一種長壽的生物，它們會在老邁時化為蛋，重新孵化，最終獲得新生。",
  ui_story_5036_50360901_262_dialog_content = "它信任妳，相信妳會在它最脆弱的時候保護它，所以才選擇在這裡變成蛋。",
  ui_story_5036_50360901_263_dialog_content = "只要等待一段時間，就能再次和它一起旅行。",
  ui_story_5036_50360901_264_dialog_content = "原來是這樣嗎？",
  ui_story_5036_50360901_265_dialog_content = "太好了，原來銜尾龍沒有離去，我們還能一起旅行。",
  ui_story_5036_50360901_266_dialog_content = "我要好好保護它。這樣吧，我去把這顆蛋放在牆壁最堅固的那間房裡！",
  ui_story_5036_50360901_267_dialog_content = "只要放在裡面，暗鬼再多都沒有辦法靠近它！",
  ui_story_5036_50360901_268_dialog_content = "我看到了！這次感應到的畫面很清晰！",
  ui_story_5036_50360901_269_dialog_content = "夏米娜德說，她把銜尾龍蛋放在了巨像上最堅固的房間裡。",
  ui_story_5036_50360901_X269_dialog_content = "她往那個方向跑了。",
  ui_story_5036_50360901_270_dialog_content = "我們快過去看看，說不定能找到新的線索。",
  ui_story_5036_50360901_271_dialog_content = "這麼多年過去了，還會有線索留下嗎？",
  ui_story_5036_50360901_272_dialog_content = "不管了，先走再說。",
  ui_story_5036_50361001_1_dialog_content = "我們已經走了十多分鐘了吧，怎麼還是沒有走到那個房間？",
  ui_story_5036_50361001_2_dialog_content = "就算歌頌者號是個大傢伙，也應該快到了才對。",
  ui_story_5036_50361001_3_dialog_content = "難道說，我們真的一直在繞圈子？",
  ui_story_5036_50361001_4_dialog_content = "不知道……但我覺得越來越難受。",
  ui_story_5036_50361001_5_dialog_content = "這裡陰森森的，讓我全身雞皮疙瘩。",
  ui_story_5036_50361001_6_dialog_content = "找不到方向，以至於一直繞圈子的情況，我在野外也經常遇到。",
  ui_story_5036_50361001_7_dialog_content = "這種時候就需要做標記啦～",
  ui_story_5036_50361001_8_dialog_content = "確實是個方法，有人帶筆了嗎？",
  ui_story_5036_50361001_9_dialog_content = "沒有～",
  ui_story_5036_50361001_10_dialog_content = "我也沒有，但是我帶了這個。",
  ui_story_5036_50361001_11_dialog_content = "這是演唱會的宣傳海報？妳出來調查還帶著這個？",
  ui_story_5036_50361001_12_dialog_content = "因為經常有粉絲找我要簽名，但是不一定都帶著簽名版。",
  ui_story_5036_50361001_13_dialog_content = "為了不辜負粉絲的熱愛，所以我就隨身攜帶海報當簽名版啦。",
  ui_story_5036_50361001_14_dialog_content = "好貼心！",
  ui_story_5036_50361001_15_dialog_content = "隨時隨地為粉絲著想，可是偶像的基本職責哦！",
  ui_story_5036_50361001_16_dialog_content = "海報嗎？嗯，確實是一個足夠顯眼的記號呢～",
  ui_story_5036_50361001_17_dialog_content = "總之，我先貼一張海報在這裡，我們繼續往前走吧！",
  ui_story_5036_50361001_18_dialog_content = "<color=#e8d9bb>一段時間後</color>",
  ui_story_5036_50361001_19_dialog_content = "已經繼續走了好幾分鐘了，兩側的景色還是沒有變化。",
  ui_story_5036_50361001_20_dialog_content = "哎呀？那不是歌爾蒂貼的海報嗎？",
  ui_story_5036_50361001_21_dialog_content = "真的是那張海報，我們果然在繞圈子！",
  ui_story_5036_50361001_22_dialog_content = "等等，這張海報有點不太對勁……",
  ui_story_5036_50361001_23_dialog_content = "這張海報上的歌爾蒂，頭髮怎麼是黑色的？表情也不太自然……",
  ui_story_5036_50361001_24_dialog_content = "這，怎麼會變成這樣？是誰在惡作劇嗎？",
  ui_story_5036_50361001_25_dialog_content = "這裡可是巨像尾部的未探索區域，除了我們三個，應該沒有人會往這邊跑了吧～",
  ui_story_5036_50361001_26_dialog_content = "難道說……",
  ui_story_5036_50361001_27_option_content = "有人跟蹤我們！？",
  ui_story_5036_50361001_28_dialog_content = "難道是狂熱過激粉絲嗎？不，難道是專門來破壞演唱會的壞蛋？",
  ui_story_5036_50361001_29_dialog_content = "不管怎麼說，都有點可怕……",
  ui_story_5036_50361001_30_dialog_content = "我們還是趕快離開這裡吧。",
  ui_story_5036_50361001_31_option_content = "是暗鬼！？",
  ui_story_5036_50361001_32_dialog_content = "可是，我們剛才不是已經讓泥尊鷹把沿路的暗鬼都催眠了嗎？",
  ui_story_5036_50361001_33_dialog_content = "它們現在應該還沒醒。",
  ui_story_5036_50361001_34_dialog_content = "這個地方確實讓人覺得不對勁，我們還是趕快離開吧！",
  ui_story_5036_50361001_35_dialog_content = "但是，要往哪裡走才對呢？",
  ui_story_5036_50361001_36_dialog_content = "既然剛才一直在繞圈子，那這次只要選中一個方向一直走就對了！",
  ui_story_5036_50361001_37_dialog_content = "就選這邊吧！",
  ui_story_5036_50361001_38_dialog_content = "慢點跑啊，等等老人家我！",
  ui_story_5036_50361001_39_dialog_content = "喂，別跑那麼快！",
  ui_story_5036_50361001_40_dialog_content = "這......這張海報真的不對勁。",
  ui_story_5036_50361001_41_dialog_content = "噫！等......等等我啊！",
  ui_story_5036_50361001_42_dialog_content = "呼——呼哈，這裡好像和剛才的走廊不太一樣，",
  ui_story_5036_50361001_43_dialog_content = "難道這裡就是夏米娜德所說的房間？",
  ui_story_5036_50361001_44_dialog_content = "看起來確實挺結實的，但是即便如此，牆壁還是因為年久失修而破破爛爛的。",
  ui_story_5036_50361001_45_dialog_content = "而且陰森的感覺也越來越重，真不想繼續留在這裡……",
  ui_story_5036_50361001_46_dialog_content = "這附近破損得好嚴重，感覺暗鬼隨時都會冒出來。",
  ui_story_5036_50361001_47_dialog_content = "窸窸窣窣——",
  ui_story_5036_50361001_48_dialog_content = "有動靜！是誰？誰在那裡？",
  ui_story_5036_50361001_49_dialog_content = "立刻出來！",
  ui_story_5036_50361001_50_dialog_content = "嗚啊！？別......別動手，是我！",
  ui_story_5036_50361001_51_dialog_content = "不是說妳！",
  ui_story_5036_50361001_52_dialog_content = "欸？",
  ui_story_5036_50361001_53_dialog_content = "珀蘭蒂？妳怎麼在這裡？不對，小心後面！",
  ui_story_5036_50361001_54_dialog_content = "嘎吼——！",
  ui_story_5036_50361001_55_dialog_content = "快閃開！",
  ui_story_5036_50361001_56_dialog_content = "啊！歌爾蒂！？",
  ui_story_5036_50361001_57_dialog_content = "（歌爾蒂剛才救了我！）",
  ui_story_5036_50361001_58_dialog_content = "想當著我的面傷害別人，我可不允許！",
  ui_story_5036_50361001_59_dialog_content = "準備接受正義的制裁吧！",
  ui_story_5036_50361001_60_dialog_content = "汪嗚——汪！",
  ui_story_5036_50361002_1_dialog_content = "嗚啊！好危險！",
  ui_story_5036_50361002_2_dialog_content = "已經沒關係了，最後一隻暗鬼已經被消滅了！",
  ui_story_5036_50361002_3_dialog_content = "妳沒事吧？有沒有受傷？",
  ui_story_5036_50361002_4_dialog_content = "我還好，除了有點腿軟……",
  ui_story_5036_50361002_5_dialog_content = "難怪剛剛總有種被什麼人盯著的微妙感，原來是這位小姑娘一直在跟蹤我們。",
  ui_story_5036_50361002_6_dialog_content = "妳怎麼會出現在這裡，是跟著我們來的嗎？",
  ui_story_5036_50361002_7_dialog_content = "這可不行啊珀蘭蒂，跟蹤是犯法的，需要接受制裁！",
  ui_story_5036_50361002_8_dialog_content = "我……嗚，我沒有！",
  ui_story_5036_50361002_9_dialog_content = "我是為了查清真相才來的！",
  ui_story_5036_50361002_10_dialog_content = "查清真相？難道妳也是來調查怪夢的？",
  ui_story_5036_50361002_11_dialog_content = "不，不是怪夢，而是另一件事。本來想偷偷調查的，既然被你們發現了，那我就直接問了。",
  ui_story_5036_50361002_12_dialog_content = "歌爾蒂，妳還記不記得大明星劇場的老闆？",
  ui_story_5036_50361002_13_dialog_content = "欸？我想想。聽妳這麼一說，好像有點印象。",
  ui_story_5036_50361002_14_dialog_content = "難道他也挨過歌爾蒂的揍嗎？",
  ui_story_5036_50361002_15_dialog_content = "維克你別打岔。",
  ui_story_5036_50361002_16_dialog_content = "我們確實有過短暫的合作，不過最後不歡而散了。",
  ui_story_5036_50361002_17_dialog_content = "不歡而散嗎？那為什麽妳不換個劇場，反而冒著重重困難跑到漂流巨像上開演唱會呢？",
  ui_story_5036_50361002_18_dialog_content = "因為在那之後，其他劇場老闆也都拒絕了我租借場地的請求。",
  ui_story_5036_50361002_19_dialog_content = "那妳知道為什麽其他劇場的老闆也拒絕妳嗎?",
  ui_story_5036_50361002_20_dialog_content = "這個，說來話長。",
  ui_story_5036_50361002_21_dialog_content = "那位老闆曾經向《十字街祕聞快訊》的編輯舉發，說妳對他造成了人身傷害。",
  ui_story_5036_50361002_X21_dialog_content = "這是什麽意思，難道歌爾蒂有什麽暴力傾向嗎？",
  ui_story_5036_50361002_22_dialog_content = "他還給編輯老師看了他臉上的傷，鼻青臉腫的，光看就覺得很痛……",
  ui_story_5036_50361002_23_dialog_content = "我才沒有傷害他，反倒是他在隨意傷害無辜的孩子！",
  ui_story_5036_50361002_24_dialog_content = "我直到現在都不願意相信是妳做的，可……可是作為記者，我必須找到證據。",
  ui_story_5036_50361002_25_dialog_content = "妳有什麼能證明自己的清白，指證他的罪行嗎？",
  ui_story_5036_50361002_26_dialog_content = "我當然會說出真相，洗清自己的冤屈。",
  ui_story_5036_50361002_27_dialog_content = "事情要從十多天前說起，那個時候，我正在找可以舉辦演唱會的場地。",
  ui_story_5036_50361002_28_dialog_content = "認真考慮以後，我認為大明星劇場是最適合的，所以決定在那裡舉辦演唱會。",
  ui_story_5036_50361002_29_dialog_content = "為了事先熟悉環境，我安排一場排練，並且進行演唱。",
  ui_story_5036_50361002_30_dialog_content = "啦——♪啦啦啦♪",
  ui_story_5036_50361002_31_dialog_content = "<color=#e8d9bb>啪——！</color>",
  ui_story_5036_50361002_32_dialog_content = "呀！！！",
  ui_story_5036_50361002_33_dialog_content = "救命啊！！！",
  ui_story_5036_50361002_34_dialog_content = "嗯？什麼聲音？",
  ui_story_5036_50361002_35_dialog_content = "這是你們能來的地方？滾！快滾開！",
  ui_story_5036_50361002_36_dialog_content = "你們這群骯髒的小老鼠，別弄髒了我的劇場！",
  ui_story_5036_50361002_37_dialog_content = "啊！",
  ui_story_5036_50361002_38_dialog_content = "弟弟！不可以打我弟弟！",
  ui_story_5036_50361002_39_dialog_content = "你幹什麼呢！",
  ui_story_5036_50361002_40_dialog_content = "這不是大明星歌爾蒂嗎？沒什麼，您不需要擔心。",
  ui_story_5036_50361002_41_dialog_content = "不過是幾個不付票錢就想聽歌的窮小鬼，我馬上把他們趕走。",
  ui_story_5036_50361002_42_dialog_content = "現在不是正式的演唱會，只是排練，我們來這裡聽大姐姐唱歌有什麽問題嗎？",
  ui_story_5036_50361002_43_dialog_content = "只要聽歌，就得付錢。",
  ui_story_5036_50361002_44_dialog_content = "竟然敢回嘴，看我怎麼收拾你！",
  ui_story_5036_50361002_45_dialog_content = "啊——！",
  ui_story_5036_50361002_X45_dialog_content = "救命啊！！！",
  ui_story_5036_50361002_46_dialog_content = "住手！",
  ui_story_5036_50361002_47_dialog_content = "<color=#e8d9bb>匡當！</color>",
  ui_story_5036_50361002_48_dialog_content = "呃啊！咳咳咳……",
  ui_story_5036_50361002_49_dialog_content = "竟然敢動我？我可是大明星劇場的老闆！",
  ui_story_5036_50361002_50_dialog_content = "就算你是老闆，也不能對無辜的孩子動粗！",
  ui_story_5036_50361002_51_dialog_content = "妳知不知道妳在幹什麼？",
  ui_story_5036_50361002_52_dialog_content = "咳咳咳……",
  ui_story_5036_50361002_53_dialog_content = "看來我不能讓妳在大明星劇場開演唱會了，歌爾蒂小姐。",
  ui_story_5036_50361002_54_dialog_content = "……對此，我深表遺憾。",
  ui_story_5036_50361002_55_dialog_content = "妳是為了保護那兩個小孩才出手的，而且只是不小心把他撞倒，沒有使用暴力！？",
  ui_story_5036_50361002_56_dialog_content = "怎麼和外面流傳的完全不一樣！？",
  ui_story_5036_50361002_57_dialog_content = "那些是不可靠的流言蜚語啦！",
  ui_story_5036_50361002_58_dialog_content = "更何況，他跌到的時候是屁股先著地的，根本不是臉！",
  ui_story_5036_50361002_59_dialog_content = "不信的話，可以親自去問問那兩個孩子，當天究竟發生了什麼。",
  ui_story_5036_50361002_60_dialog_content = "（歌爾蒂一直都表現得很有正義感，應該不是會胡亂使用暴力的人。）",
  ui_story_5036_50361002_61_dialog_content = "那妳為什麼不一開始就告訴大家這件事？",
  ui_story_5036_50361002_62_dialog_content = "因為我是偶像，不能向大家展示脆弱的一面。",
  ui_story_5036_50361002_63_dialog_content = "劇場老闆聯合其他老闆一起拒租場地給我，是想破壞我的名聲。",
  ui_story_5036_50361002_64_dialog_content = "我答應粉絲在影鎮舉辦演唱會，他們想讓我沒辦法實現諾言。",
  ui_story_5036_50361002_65_dialog_content = "如果我沒辦法信守承諾，就會讓粉絲們失望。",
  ui_story_5036_50361002_X65_dialog_content = "身為偶像，這樣就是失職！",
  ui_story_5036_50361002_X66_dialog_content = "所以無論如何，我都要如期舉辦這場演唱會。",
  ui_story_5036_50361002_X67_dialog_content = "我要向粉絲們傳達，我不會辜負他們的支持和熱愛！",
  ui_story_5036_50361002_66_dialog_content = "這些傢伙還真是可惡！",
  ui_story_5036_50361002_67_dialog_content = "而唯一的辦法，就是舉辦一場史無前例的演唱會，讓自己被每個人看到。",
  ui_story_5036_50361002_68_dialog_content = "只有提升知名度，才有人願意聽我說話、願意相信我！",
  ui_story_5036_50361002_69_dialog_content = "所以，那時我選擇了隱瞞。因為我不想讓大家看到我困擾的一面。",
  ui_story_5036_50361002_70_dialog_content = "（歌爾蒂竟然是這樣想的嗎……）",
  ui_story_5036_50361002_71_dialog_content = "（她的眼神不像是在騙人，剛剛還從暗鬼的手中救了我。）",
  ui_story_5036_50361002_72_dialog_content = "呼……真是太好了，我差點就輕信流言，把歌爾蒂當成大壞蛋了。",
  ui_story_5036_50361002_73_dialog_content = "關於這件事，我之後會去找那兩個小孩問清楚的。",
  ui_story_5036_50361002_X73_dialog_content = "如果妳說的是真的，我會寫一篇報導，替妳澄清那些關於妳有暴力傾向的傳聞！",
  ui_story_5036_50361002_74_dialog_content = "那真是太好了！",
  ui_story_5036_50361002_75_dialog_content = "那些還是留到冒險結束後再說吧，我們現在還有別的事情要做呢。",
  ui_story_5036_50361002_76_dialog_content = "對哦！PlayerName，我們走到哪裡了？",
  ui_story_5036_50361002_77_dialog_content = "根據我感應到的方向，應該快走到夏米娜德藏龍蛋的地方了。",
  ui_story_5036_50361002_78_dialog_content = "我再感應看看。",
  ui_story_5036_50361002_79_option_content = "感應！",
  ui_story_5036_50361002_80_dialog_content = "嘎嗷——！",
  ui_story_5036_50361002_81_dialog_content = "<color=#e8d9bb>咚——！</color>",
  ui_story_5036_50361002_82_dialog_content = "啊——！",
  ui_story_5036_50361002_83_dialog_content = "怎麼辦，它們馬上就要進來了……",
  ui_story_5036_50361002_84_dialog_content = "即使是巨像上最堅固的房間，也抵擋不住暗鬼嗎？",
  ui_story_5036_50361002_85_dialog_content = "歌頌者號？歌頌者號！",
  ui_story_5036_50361002_86_dialog_content = "<color=#e8d9bb>………………</color>",
  ui_story_5036_50361002_87_dialog_content = "嗚……難道歌頌者號已經……",
  ui_story_5036_50361002_88_dialog_content = "不行，我得振作起來，我必須保護銜尾龍！",
  ui_story_5036_50361002_89_dialog_content = "至少要先把它藏起來！",
  ui_story_5036_50361002_90_dialog_content = "放到牆上的隱藏儲物櫃裡，應該就不會被發現了吧。",
  ui_story_5036_50361002_91_dialog_content = "銜尾龍，你要好好藏在這裡，不可以亂動哦……",
  ui_story_5036_50361002_92_dialog_content = "我……我一定會保護你的！",
  ui_story_5036_50361002_93_dialog_content = "<color=#e8d9bb>咚！！！</color>",
  ui_story_5036_50361002_94_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_5036_50361002_95_dialog_content = "吼……",
  ui_story_5036_50361002_96_dialog_content = "暗鬼……",
  ui_story_5036_50361002_97_dialog_content = "你們……都衝著我來吧！",
  ui_story_5036_50361002_98_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5036_50361002_99_dialog_content = "好痛……",
  ui_story_5036_50361002_100_dialog_content = "身體……好冷……",
  ui_story_5036_50361002_101_dialog_content = "歌頌者號……銜尾龍……你們，還在嗎？",
  ui_story_5036_50361002_102_dialog_content = "我……好想回家……",
  ui_story_5036_50361002_103_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5036_50361002_104_dialog_content = "啾——！",
  ui_story_5036_50361101_1_dialog_content = "……",
  ui_story_5036_50361101_2_dialog_content = "PlayerName？",
  ui_story_5036_50361101_3_dialog_content = "…………",
  ui_story_5036_50361101_4_dialog_content = "PlayerName，你沒事吧？看到什麼了？",
  ui_story_5036_50361101_5_dialog_content = "我……看到了夏米娜德最後的記憶。",
  ui_story_5036_50361101_6_dialog_content = "在銜尾龍變成蛋以後，她和歌頌者號遭遇暗鬼的襲擊。",
  ui_story_5036_50361101_7_dialog_content = "她為了保護銜尾龍的蛋，把蛋藏在了那邊牆上的隱藏儲物櫃裡。",
  ui_story_5036_50361101_8_dialog_content = "然後，夏米娜德自己去引開暗鬼，但是最後，她……",
  ui_story_5036_50361101_9_dialog_content = "……別說了。",
  ui_story_5036_50361101_10_dialog_content = "那個小姑娘，到最後一刻也一直在保護銜尾龍的蛋。",
  ui_story_5036_50361101_11_dialog_content = "她把它保護得很好，雖然有點過頭了？",
  ui_story_5036_50361101_12_dialog_content = "維克，這個時候就別再胡說八道了。",
  ui_story_5036_50361101_13_dialog_content = "我沒有胡說八道啊，不信你們看這裡，這道牆縫裡面。",
  ui_story_5036_50361101_14_dialog_content = "裡面有什麼嗎？",
  ui_story_5036_50361101_15_dialog_content = "哎呀！",
  ui_story_5036_50361101_16_dialog_content = "歌爾蒂，妳看到什麼了？",
  ui_story_5036_50361101_17_dialog_content = "這是什麼？怎麼和牆壁的花紋不一樣？",
  ui_story_5036_50361101_18_dialog_content = "而且這個質地並不是巨像肌材或金屬，更像是……蛋殼。",
  ui_story_5036_50361101_19_dialog_content = "蛋殼？這麼一說，這上面的花紋很像是銜尾龍的蛋。",
  ui_story_5036_50361101_20_dialog_content = "它竟然還在這裡，但是怎麼會這麼大，還把牆都撐裂了！",
  ui_story_5036_50361101_21_dialog_content = "它不是應該只比西瓜大一點嗎？就連小女孩都能輕鬆抱起來。",
  ui_story_5036_50361101_22_dialog_content = "銜尾龍蛋？那不是維克開玩笑說出來的東西嗎？怎麼變成真的了！？",
  ui_story_5036_50361101_23_dialog_content = "維克，這到底是怎麼回事？",
  ui_story_5036_50361101_24_dialog_content = "我不知道～",
  ui_story_5036_50361101_25_dialog_content = "哈？你不是總說自己是神奇動物專家嗎？",
  ui_story_5036_50361101_26_dialog_content = "正因為我是神奇動物專家，所以不會妄下定論。",
  ui_story_5036_50361101_27_dialog_content = "我能判斷出的只有這顆龍蛋早已超過應該孵化的時間，卻還是遲遲沒有孵化。",
  ui_story_5036_50361101_28_dialog_content = "而且蛋裡的銜尾龍還活著，並且在不停生長，蛋才會變得這麼龐大。",
  ui_story_5036_50361101_29_dialog_content = "至於其他的事，不知道就是不知道～",
  ui_story_5036_50361101_30_dialog_content = "銜尾龍數量非常稀少，所以有關它的記錄也寥寥無幾。",
  ui_story_5036_50361101_31_dialog_content = "可以說銜尾龍全身都是謎團呢！",
  ui_story_5036_50361101_32_dialog_content = "我還以為維克之前只是胡說八道，沒想到竟然是真的。",
  ui_story_5036_50361101_33_dialog_content = "這顆龍蛋會是產生怪夢的源頭嗎？",
  ui_story_5036_50361101_34_dialog_content = "很有可能哦～",
  ui_story_5036_50361101_35_dialog_content = "很有可能？",
  ui_story_5036_50361101_36_dialog_content = "畢竟我也沒有證據，只能推測。",
  ui_story_5036_50361101_37_dialog_content = "我之前一直很好奇，銜尾龍這種神奇動物，究竟是怎麼度過變化為蛋的時期。",
  ui_story_5036_50361101_38_dialog_content = "畢竟，一顆蛋是沒有任何攻擊方式或逃跑辦法的。",
  ui_story_5036_50361101_39_dialog_content = "但是現在我有了新的猜想，它在蛋的時期或許能夠使用某種精神能力。",
  ui_story_5036_50361101_40_dialog_content = "比如讓生物做奇怪的夢、出現幻覺幻聽，讓其感到危險，進而不願意在附近逗留。",
  ui_story_5036_50361101_41_dialog_content = "它依靠這種手段，讓危險遠離自身。",
  ui_story_5036_50361101_42_dialog_content = "你的意思是，我們之所以會做怪夢，還感覺不舒服……",
  ui_story_5036_50361101_43_dialog_content = "甚至包括剛才看到的奇怪海報，都是銜尾龍的能力造成的！？",
  ui_story_5036_50361101_44_dialog_content = "嗯，這是我目前想到最合理的解釋～",
  ui_story_5036_50361101_45_dialog_content = "那接下來要做的事就清楚了，得想辦法搬走這顆蛋才行！",
  ui_story_5036_50361101_46_option_content = "這顆蛋？",
  ui_story_5036_50361101_47_option_content = "搬走？",
  ui_story_5036_50361101_48_dialog_content = "嗯！",
  ui_story_5036_50361101_49_dialog_content = "如果不趕快搬走它，銜尾龍的能力會繼續讓大家覺得難受。",
  ui_story_5036_50361101_50_dialog_content = "這樣下去，肯定會影響到演唱會的舉辦。",
  ui_story_5036_50361101_51_dialog_content = "我可不同意～",
  ui_story_5036_50361101_52_dialog_content = "你！",
  ui_story_5036_50361101_53_dialog_content = "這顆龍蛋這麼大，還嵌在牆縫裡。",
  ui_story_5036_50361101_54_dialog_content = "要怎麼把它挖出來，又用什麼把它運走？",
  ui_story_5036_50361101_55_dialog_content = "我會拜託白火傭兵團把它挖出來，用空艇運走。",
  ui_story_5036_50361101_56_dialog_content = "這裡的牆壁這麼結實，等到這顆蛋被挖出來，演唱會都已經結束了。",
  ui_story_5036_50361101_57_dialog_content = "這……",
  ui_story_5036_50361101_58_dialog_content = "更何況，這可是珍奇物種銜尾龍的蛋哦，全世界說不定只有這麼一顆。",
  ui_story_5036_50361101_59_dialog_content = "萬一挖掘的過程中不小心弄破了，銜尾龍會有生命危險。",
  ui_story_5036_50361101_60_dialog_content = "到時候，小姑娘妳擔得起這個責任嗎？",
  ui_story_5036_50361101_61_dialog_content = "我……",
  ui_story_5036_50361101_62_dialog_content = "所以，不如照我所說，這場演唱會乾脆別開了。",
  ui_story_5036_50361101_63_dialog_content = "反正演唱會到哪都能開，不差這一次，不如等銜尾龍孵化出來再——",
  ui_story_5036_50361101_64_dialog_content = "不行！",
  ui_story_5036_50361101_65_dialog_content = "這場演唱會對我有<color=#FFB400>特殊的意義</color>，不能就這樣放棄。",
  ui_story_5036_50361101_66_dialog_content = "我可以在別的方面讓步，唯獨這一點不行！",
  ui_story_5036_50361101_67_dialog_content = "確實，這場演唱會是歌爾蒂與粉絲的約定……",
  ui_story_5036_50361101_68_dialog_content = "（特殊的意義？歌爾蒂看起來很困擾，到底是為什麼呢？）",
  ui_story_5036_50361101_69_dialog_content = "哎呀，這就麻煩了。",
  ui_story_5036_50361101_70_dialog_content = "……",
  ui_story_5036_50361101_71_dialog_content = "（他們兩人陷入僵持了，我得做點什麼。）",
  ui_story_5036_50361101_72_dialog_content = "就沒有別的辦法嗎？",
  ui_story_5036_50361101_73_dialog_content = "比如不用移動蛋也能消除這種精神影響的辦法。",
  ui_story_5036_50361101_74_dialog_content = "對啊，維克，你不是自稱神奇動物專家嗎，能不能想想辦法？",
  ui_story_5036_50361101_75_dialog_content = "唉，果然還是要為難我這個老人家嗎？現在的年輕人真是一代不如一代啊～",
  ui_story_5036_50361101_76_dialog_content = "不過沒關係，我的徒弟們也經常需要我出手相助呢。",
  ui_story_5036_50361101_77_dialog_content = "我會把這句話原封不動地告訴詩燁和菲雅哦？",
  ui_story_5036_50361101_78_dialog_content = "哎呀，我剛才說什麼來著？突然失憶了！",
  ui_story_5036_50361101_79_dialog_content = "別急著耍寶，先說正事。",
  ui_story_5036_50361101_80_dialog_content = "咳咳，辦法倒不是沒有，只是比較麻煩，而且不一定有用。",
  ui_story_5036_50361101_81_dialog_content = "你先說說看，只要能讓演唱會順利舉辦，什麼麻煩我都不怕！",
  ui_story_5036_50361101_82_dialog_content = "PlayerName，你看到的夢境，銜尾龍的蛋會讓夏米娜德感到不舒服嗎？",
  ui_story_5036_50361101_83_dialog_content = "唔，聽你這麼一說，好像還真沒有。",
  ui_story_5036_50361101_84_dialog_content = "這就是關鍵所在了。",
  ui_story_5036_50361101_85_dialog_content = "銜尾龍的精神能力像是一種自我保護手段，應該只會在察覺到危險時使用。",
  ui_story_5036_50361101_86_dialog_content = "如果我們能清除巨像上的威脅，讓它感到安全，應該就能消除這種影響。",
  ui_story_5036_50361101_87_dialog_content = "你是說，要清除巨像上的暗鬼？",
  ui_story_5036_50361101_88_dialog_content = "可以這麼理解～",
  ui_story_5036_50361101_89_dialog_content = "沒問題，這不算什麼！",
  ui_story_5036_50361101_90_dialog_content = "等……等一等。",
  ui_story_5036_50361101_91_dialog_content = "這艘巨像這麼大，只靠我們四個人要清除掉所有的暗鬼，不可能的吧！？",
  ui_story_5036_50361101_92_dialog_content = "確實……",
  ui_story_5036_50361101_93_dialog_content = "而且這方法不一定有效吧？",
  ui_story_5036_50361101_94_dialog_content = "嗯，所以只能先試試看啦。",
  ui_story_5036_50361101_95_dialog_content = "如果只清除附近的暗鬼，堵上牆壁的縫隙，讓暗鬼沒辦法接近龍蛋呢？",
  ui_story_5036_50361101_96_dialog_content = "唔，這樣做應該能獲得同樣的效果吧？",
  ui_story_5036_50361101_97_dialog_content = "可以先試試看。",
  ui_story_5036_50361101_98_dialog_content = "那麼，動手吧！",
  ui_story_5036_50361101_99_dialog_content = "為了演唱會！",
  ui_story_5036_50361102_1_dialog_content = "PlayerName，來幫我一下。",
  ui_story_5036_50361102_2_dialog_content = "把這塊石頭推過去，堵住那邊的牆縫。",
  ui_story_5036_50361102_3_dialog_content = "好！",
  ui_story_5036_50361102_4_dialog_content = "嘿——！",
  ui_story_5036_50361102_5_dialog_content = "好了，這裡應該是最後一處了吧？",
  ui_story_5036_50361102_6_dialog_content = "沒錯，完成得相當漂亮呢。",
  ui_story_5036_50361102_7_dialog_content = "真不愧是由我指導的行動～",
  ui_story_5036_50361102_8_dialog_content = "你明明只是坐在旁邊喊加油吧……",
  ui_story_5036_50361102_9_dialog_content = "畢竟我這老胳膊老腿沒辦法做重勞動啊。",
  ui_story_5036_50361102_10_dialog_content = "陰森的氣息，似乎減弱了……",
  ui_story_5036_50361102_11_dialog_content = "確實，雖然還是能隱隱感覺到，但與剛才相比，已經減少非常多了。",
  ui_story_5036_50361102_12_dialog_content = "看來我的推論是正確的。",
  ui_story_5036_50361102_13_dialog_content = "接下來該怎麼辦？要繼續清除暗鬼嗎？",
  ui_story_5036_50361102_14_dialog_content = "現在這樣應該已經沒問題了，接下來……",
  ui_story_5036_50361102_15_dialog_content = "就只能回去睡一覺，看看還會不會做怪夢啦！",
  ui_story_5036_50361102_16_dialog_content = "所以還是要回去睡覺嗎！",
  ui_story_5036_50361102_17_dialog_content = "沒辦法，關於銜尾龍的資料太少，只能以實踐來驗證！",
  ui_story_5036_50361102_18_dialog_content = "說的也是。",
  ui_story_5036_50361102_19_dialog_content = "現在已經很晚了，大家似乎也都累了。",
  ui_story_5036_50361102_20_dialog_content = "還是先回去休息吧，順便驗證一下成果。",
  ui_story_5036_50361102_21_dialog_content = "如果還是不行的話……到時再想想別的辦法。",
  ui_story_5036_50361102_22_dialog_content = "歌爾蒂這麼努力，一定沒問題的！",
  ui_story_5036_50361102_23_dialog_content = "嗯，謝謝你！",
  ui_story_5036_50361102_24_dialog_content = "那就先回去休息吧，明天早上再見！",
  ui_story_5036_50361102_25_dialog_content = "<color=#e8d9bb>第二天一早·距離演唱會開始還有一天</color>",
  ui_story_5036_50361102_26_dialog_content = "呼哈——還真是難得地睡了個好覺呢。",
  ui_story_5036_50361102_27_dialog_content = "昨天晚上太累了，回到房間就睡了過去，連夢都沒有做。",
  ui_story_5036_50361102_28_dialog_content = "這不是我的手下敗將嗎？",
  ui_story_5036_50361102_29_dialog_content = "如果你剛剛才起床的話，那麼在今天的早起遊戲中，你又輸給我了！",
  ui_story_5036_50361102_30_dialog_content = "是貢露呀，昨天晚上睡得好嗎？",
  ui_story_5036_50361102_31_dialog_content = "是五星級的高品質睡眠哦！",
  ui_story_5036_50361102_32_dialog_content = "而且沒有像前幾天那樣夢到那個空裔小女孩。",
  ui_story_5036_50361102_33_dialog_content = "是嗎？那就好！",
  ui_story_5036_50361102_34_dialog_content = "我還覺得有點遺憾呢，畢竟做怪夢也是一種稀有成就！",
  ui_story_5036_50361102_35_dialog_content = "哈......哈哈……總之，能睡得好就好了。",
  ui_story_5036_50361102_36_dialog_content = "我要去看彩排啦，回頭見。",
  ui_story_5036_50361102_37_dialog_content = "嗯，回頭見！",
  ui_story_5036_50361102_38_dialog_content = "太好了，看起來昨晚的努力沒有白費！",
  ui_story_5036_50361102_39_dialog_content = "趕快把這件事告訴歌爾蒂，讓她放下心來吧。",
  ui_story_5036_50361102_40_dialog_content = "這個時間……嗯，她應該在排練室。",
  ui_story_5036_50361102_41_dialog_content = "PlayerName，你來了啊！",
  ui_story_5036_50361102_42_dialog_content = "怎麼沒有多休息一會？昨天忙到很晚呢。",
  ui_story_5036_50361102_43_dialog_content = "我已經睡得很飽了，不用擔心。",
  ui_story_5036_50361102_44_dialog_content = "對了，我們昨天的努力沒有白費，我剛才問了貢露，她說昨晚沒有做怪夢。",
  ui_story_5036_50361102_45_dialog_content = "嗯！我也問了其他選手，大家都說睡得很好。",
  ui_story_5036_50361102_46_dialog_content = "真是太好了！",
  ui_story_5036_50361102_47_dialog_content = "真是……太好了。",
  ui_story_5036_50361102_48_option_content = "歌爾蒂，妳沒事吧？",
  ui_story_5036_50361102_49_dialog_content = "怎麼看起來這麼疲倦？",
  ui_story_5036_50361102_50_dialog_content = "欸？有嗎？",
  ui_story_5036_50361102_51_dialog_content = "偶像可是一直元氣滿滿、從不疲倦的哦！",
  ui_story_5036_50361102_52_option_content = "妳怎麼這麼疲倦的樣子？",
  ui_story_5036_50361102_53_dialog_content = "欸？有嗎？",
  ui_story_5036_50361102_54_dialog_content = "你一定是看錯了，我現在可是精力十足哦！",
  ui_story_5036_50361102_55_dialog_content = "（剛剛那個神情，我肯定沒看錯。難道說……）",
  ui_story_5036_50361102_56_dialog_content = "妳是不是一直在勉強自己打起精神？",
  ui_story_5036_50361102_57_dialog_content = "……！",
  ui_story_5036_50361102_58_dialog_content = "這種事稍微想想就能知道，畢竟妳昨天也很晚才休息。",
  ui_story_5036_50361102_59_dialog_content = "更何況今天還要早起安排訓練和海選的事，怎麼看都不像是充分休息過的樣子。",
  ui_story_5036_50361102_60_dialog_content = "沒關係哦，因為我是偶像，偶像是——",
  ui_story_5036_50361102_61_option_content = "偶像也是人吧？",
  ui_story_5036_50361102_62_dialog_content = "只要是人就會疲倦，需要休息。",
  ui_story_5036_50361102_63_dialog_content = "雖然我不清楚是什麼原因，讓妳如此重視這場演唱會……",
  ui_story_5036_50361102_64_dialog_content = "但是妳需要先放下工作，好好休息一下。",
  ui_story_5036_50361102_65_dialog_content = "唉。",
  ui_story_5036_50361102_66_dialog_content = "PlayerName幫了我這麼多，說出真相也沒關係吧。",
  ui_story_5036_50361102_67_dialog_content = "啊？妳剛才是不是說了「真相」之類的話？",
  ui_story_5036_50361102_X67_dialog_content = "這場演唱會不只是我對粉絲的承諾，也是我對涉老闆的承諾。",
  ui_story_5036_50361102_68_dialog_content = "其實，之前我和涉簽了一個協議。",
  ui_story_5036_50361102_69_dialog_content = "協議？和涉！？",
  ui_story_5036_50361102_70_dialog_content = "她看中了偶像這份職業的潛力，也看好我的能力，所以決定在我身上投資。",
  ui_story_5036_50361102_71_dialog_content = "她會提供我最大限度的資金支援，但同樣的，我也必須完成她對我的要求。",
  ui_story_5036_50361102_72_dialog_content = "我需要在規定的時間內，在影鎮舉辦一場演唱會，而這場演唱會——",
  ui_story_5036_50361102_73_dialog_content = "必須要將「偶像」的概念和我的名字，傳達給白夜城和影鎮的每一個人。",
  ui_story_5036_50361102_74_dialog_content = "涉不是在坑妳吧？這真的完成的了嗎！？",
  ui_story_5036_50361102_75_dialog_content = "以我原本的人氣，這件事雖然有點難度，但只要好好策劃就不會有問題。",
  ui_story_5036_50361102_76_dialog_content = "但中途遇到的變故，導致我租不到場地。",
  ui_story_5036_50361102_77_dialog_content = "就在我走投無路時，漂流巨像突然出現，真是太幸運了！",
  ui_story_5036_50361102_78_dialog_content = "協議的期限就是明天，這是我最後的機會，這場演唱會，我必須辦好。",
  ui_story_5036_50361102_79_dialog_content = "要是失敗，我就要賠償涉的全部支出，背上巨額債務。",
  ui_story_5036_50361102_80_dialog_content = "而我的偶像之路，恐怕也會走到盡頭吧。",
  ui_story_5036_50361102_81_dialog_content = "沒想到妳竟然承受這樣的壓力，也太努力了吧！？",
  ui_story_5036_50361102_82_dialog_content = "沒關係，這就是我的責任啊。",
  ui_story_5036_50361102_83_dialog_content = "身為偶像，我存在的意義就是為支持我的粉絲帶來歌聲、歡樂與希望。",
  ui_story_5036_50361102_84_dialog_content = "沒有粉絲的愛與支持，就不會有偶像。",
  ui_story_5036_50361102_85_dialog_content = "我收到這麼多來自粉絲的愛，又有什麼理由不拼盡全力地回應他們呢？",
  ui_story_5036_50361102_86_dialog_content = "如果這場演唱會能讓更多人聽到我的歌聲，我一定會全力去辦好！",
  ui_story_5036_50361102_87_dialog_content = "嗯……加油！",
  ui_story_5036_50361102_88_dialog_content = "妳不是一個人在努力，還有我呢！",
  ui_story_5036_50361102_89_dialog_content = "只要有我能幫忙的地方，就叫上我吧。",
  ui_story_5036_50361102_90_dialog_content = "謝謝你，PlayerName！",
  ui_story_5036_50361102_91_dialog_content = "那我們一起辦好演唱會，保護這艘珍貴的歌頌者號吧！",
  ui_story_5036_50361201_1_dialog_content = "<color=#e8d9bb>次日，距離演唱會開始還有十五分鐘</color>",
  ui_story_5036_50361201_2_dialog_content = "演唱會馬上就要開始了，大家都準備好了嗎？",
  ui_story_5036_50361201_3_dialog_content = "準備好了！",
  ui_story_5036_50361201_4_dialog_content = "終於要開始了嗎？早已盼望多時了。",
  ui_story_5036_50361201_5_dialog_content = "（真是，我還要陪這群庶民浪費時間到什麼時候。）",
  ui_story_5036_50361201_6_dialog_content = "表情，崩壞。",
  ui_story_5036_50361201_7_dialog_content = "陰沉的想法，全寫在臉上了。",
  ui_story_5036_50361201_8_dialog_content = "你給我閉嘴。",
  ui_story_5036_50361201_9_dialog_content = "太好了！遊戲終於要開始了！",
  ui_story_5036_50361201_10_dialog_content = "準備好和我一起玩應援遊戲了嗎，小諾諾？",
  ui_story_5036_50361201_11_dialog_content = "準備……好了……",
  ui_story_5036_50361201_12_dialog_content = "怎麼還不開始？我已經等不及要用搖滾樂征服所有觀眾了！",
  ui_story_5036_50361201_13_dialog_content = "妳這個大——笨蛋！這可是偶像演唱會，重點是偶像啦！",
  ui_story_5036_50361201_14_dialog_content = "當然是紅油甜心的芭芭拉我更符合氣氛！",
  ui_story_5036_50361201_15_dialog_content = "妳那種小孩子過家家一樣的曲調，怎麼可能打動人心！",
  ui_story_5036_50361201_16_dialog_content = "妳！",
  ui_story_5036_50361201_17_dialog_content = "她們倆還是這麼吵鬧呢，希望別惹出什麼亂子。",
  ui_story_5036_50361201_18_dialog_content = "是啊，她們可是要一起演唱開場曲呢！",
  ui_story_5036_50361201_19_dialog_content = "原來如此……等等？她們兩個？一起！？",
  ui_story_5036_50361201_20_dialog_content = "真的沒問題嗎！？",
  ui_story_5036_50361201_21_dialog_content = "說實話我也有些擔心，但她們兩個誰都不肯排在對方後面出場。",
  ui_story_5036_50361201_22_dialog_content = "所以，就只好安排她們一同上台表演了。",
  ui_story_5036_50361201_23_dialog_content = "也別太擔心，她們已經信誓旦旦地保證過，會獻上一首不輸給任何人的精彩開場曲了！",
  ui_story_5036_50361201_24_dialog_content = "妳確定她們是信誓旦旦，而不是殺氣騰騰地保證嗎……",
  ui_story_5036_50361201_25_dialog_content = "相信她們吧！或許她們關係不太好，但是想要認真演唱的心情是不用懷疑的。",
  ui_story_5036_50361201_26_dialog_content = "好吧，但願她們在台上能夠好好配合。",
  ui_story_5036_50361201_27_dialog_content = "畢竟這場演唱會攸關能不能留下歌頌者號！",
  ui_story_5036_50361201_28_dialog_content = "PlayerName真的很重視歌頌者號啊。",
  ui_story_5036_50361201_29_dialog_content = "因為它是除了臨空者號和陸行者號以外，唯一還能運作的巨像。",
  ui_story_5036_50361201_30_dialog_content = "每一艘巨像都和空裔密切相關，是空裔們曾經存在過的證明。",
  ui_story_5036_50361201_31_dialog_content = "我希望能完完整整的保留它們。這樣的話，逝去的同胞也會開心吧……",
  ui_story_5036_50361201_32_dialog_content = "更何況，如果能修好它，臨空者號也會有新的夥伴，不用再那麼孤獨了。",
  ui_story_5036_50361201_33_dialog_content = "放心吧，PlayerName，我一定會幫你的！",
  ui_story_5036_50361201_34_dialog_content = "我們也會幫你的！",
  ui_story_5036_50361201_35_dialog_content = "如果真的出了什麼事情，我會維持秩序。",
  ui_story_5036_50361201_36_dialog_content = "果然還是卡蓮最可靠！",
  ui_story_5036_50361201_37_dialog_content = "妳們兩位看起來準備得很充分啊。",
  ui_story_5036_50361201_38_dialog_content = "那當然了，為了這次的演唱會，我們可是一起準備了祕密武器！",
  ui_story_5036_50361201_39_dialog_content = "妳們打算一起演唱哪首歌？",
  ui_story_5036_50361201_40_dialog_content = "我們本來打算一起唱學生時代在同學聚會上一起演過的歌，但排練時總覺得少了點什麼。",
  ui_story_5036_50361201_41_dialog_content = "像是一起旅行時的感動、一起克服困難後的欣慰，或更多類似的情感。",
  ui_story_5036_50361201_42_dialog_content = "沒錯沒錯，我問了卡蓮以後，她也和我有相同的感觸。",
  ui_story_5036_50361201_43_dialog_content = "所以最後我們決定，一起寫一首新歌！",
  ui_story_5036_50361201_44_dialog_content = "我開始期待了！",
  ui_story_5036_50361201_45_dialog_content = "蕾吉娜、芭芭拉、卡蓮、薇絲、維克……",
  ui_story_5036_50361201_46_dialog_content = "咦？維克怎麼不在？",
  ui_story_5036_50361201_47_dialog_content = "維克？我剛才從房間過來的時候，看到他的房間空著。",
  ui_story_5036_50361201_48_dialog_content = "他應該早就來了吧？",
  ui_story_5036_50361201_49_dialog_content = "PlayerName，你也沒看到他嗎？",
  ui_story_5036_50361201_50_dialog_content = "真是的，馬上就要開始演出了，他究竟跑去哪裡了？",
  ui_story_5036_50361201_51_dialog_content = "他會不會又去看銜尾龍的蛋了？",
  ui_story_5036_50361201_52_dialog_content = "那傢伙對神奇動物比對人更用心，還經常隨時隨地倒頭就睡。",
  ui_story_5036_50361201_53_dialog_content = "說不定是在那裡睡過頭了。",
  ui_story_5036_50361201_54_dialog_content = "我去把他找回來吧。",
  ui_story_5036_50361201_55_dialog_content = "真的可以嗎？",
  ui_story_5036_50361201_56_dialog_content = "沒問題，交給我吧。",
  ui_story_5036_50361201_57_dialog_content = "我聽說那件事了，那個地方是在封鎖區裡嗎？",
  ui_story_5036_50361201_58_dialog_content = "那裡太危險了，我和你一起去吧！",
  ui_story_5036_50361201_59_dialog_content = "嗯，我也幫忙。",
  ui_story_5036_50361201_60_dialog_content = "那邊離舞台太遠了，往返一次要很久。",
  ui_story_5036_50361201_61_dialog_content = "妳們快要上台表演了吧？還是留在這裡好好準備吧。",
  ui_story_5036_50361201_62_dialog_content = "你一個人怎麼對付那些暗鬼？",
  ui_story_5036_50361201_63_dialog_content = "不用擔心，前天晚上我、歌爾蒂和維克，已經把通往那邊的沿途暗鬼清理乾淨了。",
  ui_story_5036_50361201_64_dialog_content = "所以我獨自過去也不會有事。",
  ui_story_5036_50361201_65_dialog_content = "好吧，那你快去快回，一定要注意安全。",
  ui_story_5036_50361201_66_dialog_content = "放心吧。",
  ui_story_5036_50361201_67_dialog_content = "那麼，我們也開始準備演唱會吧！",
  ui_story_5036_50361201_68_dialog_content = "如果維克不能準時回來，就要拜託兩位提前上場了。",
  ui_story_5036_50361201_69_dialog_content = "嗯，知道了！",
  ui_story_5036_50361201_70_dialog_content = "我也沒有問題。",
  ui_story_5036_50361201_71_dialog_content = "還沒開始嗎？",
  ui_story_5036_50361201_72_dialog_content = "快了，你看舞台上！",
  ui_story_5036_50361201_73_dialog_content = "這個時刻終於到來了呢，各位，久等了！",
  ui_story_5036_50361201_74_dialog_content = "群星閃耀之刻——天空演唱會，終於要開始了！",
  ui_story_5036_50361201_75_dialog_content = "哦——！！！",
  ui_story_5036_50361201_76_dialog_content = "<color=#e8d9bb>與此同時</color>",
  ui_story_5036_50361201_77_dialog_content = "嗯？那是什麼？",
  ui_story_5036_50361201_78_dialog_content = "從雲層之間穿過，閃亮亮的……是巨像！？",
  ui_story_5036_50361201_79_dialog_content = "好像還有聲音傳過來，說是天空演唱會？",
  ui_story_5036_50361201_80_dialog_content = "大小姐，您可能有所不知，這是最近從永夜地帶駛來的一艘漂流巨像。",
  ui_story_5036_50361201_81_dialog_content = "據說有一名叫歌爾蒂的偶像，會在這艘巨像上舉辦演唱會。",
  ui_story_5036_50361201_82_dialog_content = "這個消息已經在影鎮的各大報紙上流傳開了。",
  ui_story_5036_50361201_83_dialog_content = "是嗎？真有意思。",
  ui_story_5036_50361201_84_dialog_content = "我們去找個好位置，看看他們究竟在幹什麼。",
  ui_story_5036_50361201_85_dialog_content = "是。",
  ui_story_5036_50361201_86_dialog_content = "姐姐，快看天上！是巨像！",
  ui_story_5036_50361201_87_dialog_content = "真的是巨像！",
  ui_story_5036_50361201_88_dialog_content = "巨像上面那個是什麼？是螢幕嗎？好像正在播放什麼……",
  ui_story_5036_50361201_89_dialog_content = "哎呀，那不是那天出手保護我們的大姐姐嗎？",
  ui_story_5036_50361201_90_dialog_content = "真的是她！大姐姐找到開演唱會的地方了！竟然是在巨像上！",
  ui_story_5036_50361201_91_dialog_content = "就算沒有買票，也聽得好清楚，大姐姐好厲害！",
  ui_story_5036_50361201_92_dialog_content = "巨像往那邊飛了，弟弟，我們快跟上！",
  ui_story_5036_50361201_93_dialog_content = "沿著河走，我們去給大姐姐加油！",
  ui_story_5036_50361201_94_dialog_content = "大家的熱情，歌爾蒂已經感受到了哦——！",
  ui_story_5036_50361201_95_dialog_content = "接下來，就由紅油沙漠遠道而來的兩位偶像，為大家獻上火焰般熱情的開場曲吧！",
  ui_story_5036_50361201_96_dialog_content = "讓我們歡迎——蕾吉娜和芭芭拉！",
  ui_story_5036_50361201_97_dialog_content = "♪烈焰——燃盡♪",
  ui_story_5036_50361201_98_dialog_content = "♪為你獻上，我的愛意——♪",
  ui_story_5036_50361201_99_dialog_content = "<size=40>♪奔湧，爆炸，破壞♪</size>",
  ui_story_5036_50361201_100_dialog_content = "<size=45>♪期盼的心跳，與你相遇♪</size>",
  ui_story_5036_50361201_101_dialog_content = "（可惡，這傢伙聲音怎麼這麼大……）",
  ui_story_5036_50361201_102_dialog_content = "（我可不能輸給她！！！）",
  ui_story_5036_50361201_103_dialog_content = "<size=40>♪這就是我的——♪</size>",
  ui_story_5036_50361201_104_dialog_content = "<size=45>♪訴說心願，那就是——♪</size>",
  ui_story_5036_50361201_105_dialog_content = "<size=50>♪搖滾！！！♪</size>",
  ui_story_5036_50361201_106_dialog_content = "<size=50>♪偶像！！！♪</size>",
  ui_story_5036_50361201_107_dialog_content = "這唱得是什麼跟什麼啊？歌詞都混在一起了，聲音還這麼大。",
  ui_story_5036_50361201_108_dialog_content = "一點都聽不清楚，吵死了，真難聽！",
  ui_story_5036_50361201_109_dialog_content = "糟了，這兩人怎麼在舞台上也能吵起來？答應的好好合作呢！？",
  ui_story_5036_50361201_110_dialog_content = "不行，再這樣下去，就要變成演出事故了，我得把她們導回正軌！",
  ui_story_5036_50361201_111_dialog_content = "♪如同沙漠一樣火熱，我怦怦跳動的心臟啊——♪",
  ui_story_5036_50361201_112_dialog_content = "（等等，主持人怎麼突然開始上台演唱了！？）",
  ui_story_5036_50361201_113_dialog_content = "（排練的時候沒有這段啊！）",
  ui_story_5036_50361201_114_dialog_content = "（希望她們能明白我的用意，好運啊，眷顧我吧！）",
  ui_story_5036_50361201_115_dialog_content = "♪想要傳達給你的，這份感情，它的名字是——♪",
  ui_story_5036_50361201_116_dialog_content = "♪是——♪",
  ui_story_5036_50361201_117_dialog_content = "♪是——♪",
  ui_story_5036_50361201_118_dialog_content = "<size=45>♪愛——！！！♪</size>",
  ui_story_5036_50361201_119_dialog_content = "♪永不熄滅！♪",
  ui_story_5036_50361201_120_dialog_content = "♪綿延不絕！♪",
  ui_story_5036_50361201_121_dialog_content = "<size=50>♪如同紅油，熊熊燃燒——♪</size>",
  ui_story_5036_50361201_122_dialog_content = "（成功了！她們兩人的步調終於重新一致了！）",
  ui_story_5036_50361201_123_dialog_content = "（那我也悄悄退場吧。）",
  ui_story_5036_50361201_124_dialog_content = "♪搖滾，衝擊，無路可退♪",
  ui_story_5036_50361201_125_dialog_content = "♪將你的真心，捧在手心♪",
  ui_story_5036_50361201_126_dialog_content = "<size=50>♪我們的歌，響徹——♪</size>",
  ui_story_5036_50361201_127_dialog_content = "哦？漸漸變得不錯聽！",
  ui_story_5036_50361201_128_dialog_content = "歌爾蒂的身姿真耀眼！我可要多拍幾張！",
  ui_story_5036_50361201_129_dialog_content = "完全不同的兩種曲調，竟然也能如此和諧地同時演奏，吸引這麼多人觀看……",
  ui_story_5036_50361201_130_dialog_content = "真是有趣！白夜城從未有過這般演唱會！",
  ui_story_5036_50361201_131_dialog_content = "大小姐，巨像要飛走了。",
  ui_story_5036_50361201_132_dialog_content = "去開我的私人空艇。",
  ui_story_5036_50361201_133_dialog_content = "！？",
  ui_story_5036_50361201_134_dialog_content = "這麼有趣的演唱會，我怎麼會放過它的特等席呢！",
  ui_story_5036_50361201_135_dialog_content = "竟然會在巨像上舉辦演唱會，真是空前未有的創意！",
  ui_story_5036_50361201_136_dialog_content = "人越來越多了。",
  ui_story_5036_50361201_137_dialog_content = "甚至有不少商人為了觀看這場演唱會，專門租船順著金河航行追隨。",
  ui_story_5036_50361201_138_dialog_content = "呵呵，選擇投資這個小姑娘，果然沒錯。",
  ui_story_5036_50361201_139_dialog_content = "維克和PlayerName還沒回來嗎？",
  ui_story_5036_50361201_140_dialog_content = "還沒有。",
  ui_story_5036_50361201_141_dialog_content = "這兩人，真讓人擔心……",
  ui_story_5036_50361201_142_dialog_content = "沒辦法，只能請妳們兩位先上台了。",
  ui_story_5036_50361201_143_dialog_content = "嗯！",
  ui_story_5036_50361201_144_dialog_content = "感謝蕾吉娜和芭芭拉的傾情獻唱！",
  ui_story_5036_50361201_145_dialog_content = "氣氛逐漸嗨起來了，歌爾蒂的心也開始跟著怦怦跳呢！",
  ui_story_5036_50361201_146_dialog_content = "話說回來，這次歌爾蒂有幸請到兩位超——級有名的大人物哦！",
  ui_story_5036_50361201_147_dialog_content = "她們一位是白夜城的騎士，另一位是啟光的軍官。",
  ui_story_5036_50361201_148_dialog_content = "她們沒有因為陣營而產生隔閡，並成為最要好的朋友，與傳說的空裔一起踏上冒險。",
  ui_story_5036_50361201_149_dialog_content = "今天，她們將為大家獻上，以旅途中最美好的回憶共同編織的歌曲。",
  ui_story_5036_50361201_150_dialog_content = "有請卡蓮和薇絲——！",
  ui_story_5036_50361201_151_dialog_content = "人好多啊，PlayerName不在，有點可惜呢……",
  ui_story_5036_50361201_152_dialog_content = "別緊張，我們絕對沒問題的。",
  ui_story_5036_50361201_153_dialog_content = "嗯！那麼，開始吧！",
  ui_story_5036_50361201_154_dialog_content = "♪似乎是，未曾設想的旅程♪",
  ui_story_5036_50361201_155_dialog_content = "♪出現了不存在於地圖的道路♪",
  ui_story_5036_50361201_156_dialog_content = "♪前方存在著什麼呢♪",
  ui_story_5036_50361201_157_dialog_content = "♪這份好奇的心情♪",
  ui_story_5036_50361201_158_dialog_content = "♪與你相遇，同行♪",
  ui_story_5036_50361201_159_dialog_content = "♪也曾短暫分別，又經重逢♪",
  ui_story_5036_50361201_160_dialog_content = "♪最默契的夥伴♪",
  ui_story_5036_50361201_161_dialog_content = "♪從陌生，到熟識♪",
  ui_story_5036_50361201_162_dialog_content = "♪永遠的夥伴，彼此照耀♪",
  ui_story_5036_50361201_163_dialog_content = "♪成為軌跡重合的星♪",
  ui_story_5036_50361201_164_dialog_content = "多虧貢露事先設置的訊號傳輸設備，就算在這裡，也能聽見巨像上的演唱會。",
  ui_story_5036_50361201_165_dialog_content = "這倒是一種全新的娛樂方式，很有參考價值。",
  ui_story_5036_50361201_166_dialog_content = "之後也在地下城內部進行小範圍的試驗，測試一下效果如何，大元帥？",
  ui_story_5036_50361201_167_dialog_content = "好，我准了。",
  ui_story_5036_50361201_168_dialog_content = "欸？是......是！",
  ui_story_5036_50361201_169_dialog_content = "怎麼了，一副吃驚的樣子？",
  ui_story_5036_50361201_170_dialog_content = "我以為您對這種新型娛樂方式的態度會更謹慎。",
  ui_story_5036_50361201_171_dialog_content = "哈哈哈，我當然很謹慎。不過，妳仔細聽。",
  ui_story_5036_50361201_172_dialog_content = "雖然我不太擅長唱歌，但還是能聽出來，此時此刻，薇絲相當開心。",
  ui_story_5036_50361201_173_dialog_content = "這份情感，不正是我們需要的嗎？",
  ui_story_5036_50361201_174_dialog_content = "連這裡都能隱約聽見卡蓮姐姐和薇絲姐姐唱歌的聲音……",
  ui_story_5036_50361201_175_dialog_content = "真好聽啊，不愧是卡蓮姐姐！",
  ui_story_5036_50361201_176_dialog_content = "拉斐爾，妳守在這裡，加強警戒。",
  ui_story_5036_50361201_177_dialog_content = "還有，去命人準備一艘空艇，不要聲張。",
  ui_story_5036_50361201_178_dialog_content = "咦？城主大人現在就要出門嗎？",
  ui_story_5036_50361201_179_dialog_content = "這艘巨像上的風險尚不明確，身為城主，我需親自跟隨查看，以防意外。",
  ui_story_5036_50361201_180_dialog_content = "好......好的！",
  ui_story_5036_50361201_181_dialog_content = "唉……",
  ui_story_5036_50361201_182_dialog_content = "城主大人什麼時候能直接對卡蓮姐姐表達關心呢？",
  ui_story_5036_50361201_183_dialog_content = "<color=#e8d9bb>與此同時·漂流巨像內部</color>",
  ui_story_5036_50361201_184_dialog_content = "這聲音，好像是薇絲和卡蓮在唱歌！",
  ui_story_5036_50361201_185_dialog_content = "已經輪到她們上台了嗎？糟糕，我還是跑得太慢了！",
  ui_story_5036_50361201_186_dialog_content = "明明應該早就走到了才對……",
  ui_story_5036_50361201_187_dialog_content = "不愧是一同冒險的夥伴，配合太完美了！",
  ui_story_5036_50361201_188_dialog_content = "雖然都是叫做偶像，但每個人心中對偶像的定義都是不同的。",
  ui_story_5036_50361201_189_dialog_content = "對一部分的人而言，偶像是為了凝聚人們的力量而存在的。",
  ui_story_5036_50361201_190_dialog_content = "接下來即將登場的是啟光合唱團。",
  ui_story_5036_50361201_191_dialog_content = "他們將為大家帶來激昂澎湃的軍歌——！",
  ui_story_5036_50361201_192_dialog_content = "哦！！！",
  ui_story_5036_50361201_193_dialog_content = "呼，真是辛苦妳們了，薇絲、卡蓮！",
  ui_story_5036_50361201_194_dialog_content = "沒問題，我們還可以！",
  ui_story_5036_50361201_195_dialog_content = "只是經過這麼久了，PlayerName和維克竟然還沒有回來。",
  ui_story_5036_50361201_196_dialog_content = "確實。雖然巨像很大，但只是去找個人，應該不會花這麼長的時間才對。",
  ui_story_5036_50361201_197_dialog_content = "嗯……",
  ui_story_5036_50361201_198_dialog_content = "卡蓮，我們還是去找一找他們吧。",
  ui_story_5036_50361201_199_dialog_content = "我也這麼認為，我們已經結束表演了，為了安全起見，還是去找找他們吧。",
  ui_story_5036_50361201_200_dialog_content = "好吧，妳們也要多加小心，記得在謝幕前回來！",
  ui_story_5036_50361201_201_dialog_content = "好。",
  ui_story_5036_50361201_202_dialog_content = "我們走吧。",
  ui_story_5036_50361201_203_dialog_content = "<color=#e8d9bb>一段時間後</color>",
  ui_story_5036_50361201_204_dialog_content = "啟光合唱團已經演唱完畢，白夜城唱詩班的表演也接近尾聲……",
  ui_story_5036_50361201_205_dialog_content = "PlayerName他們怎麼還沒回來，莫非是遇到麻煩了？",
  ui_story_5036_50361201_206_dialog_content = "真讓人擔心！但是，我又不能離開，馬上就要換我做最後的演唱了！",
  ui_story_5036_50361201_207_dialog_content = "那首歌，我一定要唱出來，讓每一個人都聽見。",
  ui_story_5036_50361201_208_dialog_content = "這樣才能不辜負PlayerName等人和我自己的努力。",
  ui_story_5036_50361201_209_dialog_content = "等唱完這首歌，我就去找他們。",
  ui_story_5036_50361201_210_dialog_content = "演唱會已近尾聲，大家盡興了嗎？",
  ui_story_5036_50361201_211_dialog_content = "還沒有——！",
  ui_story_5036_50361201_212_dialog_content = "謝謝！大家的熱情，歌爾蒂感受到了哦！",
  ui_story_5036_50361201_213_dialog_content = "接下來，就讓歌爾蒂為大家獻唱最後的曲目吧！",
  ui_story_5036_50361201_214_dialog_content = "哦！！！終於到歌爾蒂演唱了嗎！",
  ui_story_5036_50361201_215_dialog_content = "今天，歌爾蒂將為大家帶來一首特別的歌，這首歌的旋律是空裔與巨像溝通時用的。",
  ui_story_5036_50361201_216_dialog_content = "空裔透過一段段這樣的旋律，駕駛巨像，環遊世界。",
  ui_story_5036_50361201_217_dialog_content = "而今，在相隔百年後終於歸來的巨像上，這些旋律將再度響起——！",
  ui_story_5036_50361201_218_dialog_content = "哦——！！！",
  ui_story_5036_50361201_219_dialog_content = "（就是現在了，終於到了最關鍵的時刻。）",
  ui_story_5036_50361201_220_dialog_content = "歌歌子放心飛！蒂蒂人永相隨！",
  ui_story_5036_50361201_221_dialog_content = "（就讓我用這首歌回應粉絲們的熱愛和PlayerName的努力吧！）",
  ui_story_5036_50361201_222_dialog_content = "♪星，閃耀光芒♪",
  ui_story_5036_50361201_223_dialog_content = "♪候鳥也振翅起航♪",
  ui_story_5036_50361201_224_dialog_content = "♪遠航的希冀♪",
  ui_story_5036_50361201_225_dialog_content = "♪指引著它飛行的方向♪",
  ui_story_5036_50361201_226_dialog_content = "歌爾蒂！歌爾蒂！",
  ui_story_5036_50361201_227_dialog_content = "啊……竟然能聽到歌爾蒂小姐的現場演唱……",
  ui_story_5036_50361201_228_dialog_content = "就算經歷再多辛苦，這一趟也值得了！",
  ui_story_5036_50361201_229_dialog_content = "♪期盼的相遇啊♪",
  ui_story_5036_50361201_230_dialog_content = "♪躍動著鼓起勇氣的心♪",
  ui_story_5036_50361201_231_dialog_content = "（咦……突然，好想睡……）",
  ui_story_5036_50361201_232_dialog_content = "（不行，要撐住，我可是還在演唱中啊！）",
  ui_story_5036_50361201_233_dialog_content = "♪前行吧，前行吧♪",
  ui_story_5036_50361201_234_dialog_content = "♪直到遇見你的地方♪",
  ui_story_5036_50361201_235_dialog_content = "（怎麼回事……我的頭，好暈……）",
  ui_story_5036_50361201_236_dialog_content = "啾——！",
  ui_story_5036_50361201_237_dialog_content = "（這聲音是……從哪裡傳來的？）",
  ui_story_5036_50361201_238_dialog_content = "（好睏，但還不能睡……演唱會，還沒有……）",
  ui_story_5036_50361301_1_dialog_content = "<color=#e8d9bb>與此同時·巨像封鎖區</color>",
  ui_story_5036_50361301_2_dialog_content = "怎麼回事啊，感覺又繞起圈子來了？",
  ui_story_5036_50361301_3_dialog_content = "我明明記得之前是走這條路，但怎麼還沒走到？",
  ui_story_5036_50361301_4_dialog_content = "難不成銜尾龍的精神能力又開始產生影響了？",
  ui_story_5036_50361301_5_dialog_content = "走了這麼久，演唱會是不是都要結束了？",
  ui_story_5036_50361301_6_dialog_content = "啊，前面是……終於到了！這次終於走對了！",
  ui_story_5036_50361301_7_dialog_content = "嗯？ PlayerName，你怎麼到這裡來了？",
  ui_story_5036_50361301_8_dialog_content = "難不成是演出太無聊了，所以偷偷跑來這裡睡大覺？",
  ui_story_5036_50361301_9_dialog_content = "我才沒那麼不負責任呢！",
  ui_story_5036_50361301_10_dialog_content = "倒是你，怎麼跑到這裡來了？大家還在等你回去表演呢！",
  ui_story_5036_50361301_11_dialog_content = "表演？哦，你是說要我去唱歌那件事啊。",
  ui_story_5036_50361301_12_dialog_content = "我不行的啦。",
  ui_story_5036_50361301_13_dialog_content = "怎麼會！你明明有天賦，也有歌爾蒂幫你訓練和編舞，你這是要臨陣脫逃嗎？",
  ui_story_5036_50361301_14_dialog_content = "哈哈哈，雖然你誇獎得沒錯，但是我真的不行。",
  ui_story_5036_50361301_15_dialog_content = "你也看到他們訓練了吧？",
  ui_story_5036_50361301_16_dialog_content = "想要上台表演，需要長期的練習，還有就是熱情。很可惜，這兩樣我都沒有。",
  ui_story_5036_50361301_17_dialog_content = "我對開演唱會和當偶像沒什麼興趣，老胳膊老腿也經不起這樣折騰。",
  ui_story_5036_50361301_18_dialog_content = "就算上台表演，也會扯年輕人的後腿。",
  ui_story_5036_50361301_19_dialog_content = "與其自找麻煩，不如做點我能做好的事情，比如看好這顆龍蛋，讓它別給演唱會添亂。",
  ui_story_5036_50361301_20_dialog_content = "沒想到你嘴巴說對演唱會沒興趣，其實還挺在意的。",
  ui_story_5036_50361301_21_dialog_content = "我只是不想欠小孩子人情～",
  ui_story_5036_50361301_22_dialog_content = "你欠的難道還少嗎……",
  ui_story_5036_50361301_23_dialog_content = "咳咳，對自己徒弟當然不算，那是在訓練她們。",
  ui_story_5036_50361301_24_dialog_content = "不過，你在來的路上也感覺到了吧？銜尾龍的精神能力又在發揮作用了。",
  ui_story_5036_50361301_25_dialog_content = "確實，害我迷路超久。",
  ui_story_5036_50361301_26_dialog_content = "這意味銜尾龍又感知到了危險，嘗試自保。",
  ui_story_5036_50361301_27_dialog_content = "我們不是已經清理了這附近的暗鬼，堵住了縫隙嗎？",
  ui_story_5036_50361301_28_dialog_content = "或許是因為光靈們離得太遠了吧。",
  ui_story_5036_50361301_29_dialog_content = "現在正在舉辦演唱會，所有的光靈都集中在離這裡最遠的巨像頭部舞台。",
  ui_story_5036_50361301_30_dialog_content = "萬一這裡出了什麼事，除了我們兩個，沒有人能及時趕來。",
  ui_story_5036_50361301_31_dialog_content = "所以銜尾龍開始憂慮？",
  ui_story_5036_50361301_32_dialog_content = "可能是吧～",
  ui_story_5036_50361301_33_dialog_content = "銜尾龍還真是種膽小的生物，明明已經在巨像上過了這麼多年，卻還是會害怕。",
  ui_story_5036_50361301_34_dialog_content = "正是因為有了相遇，才會害怕別離。",
  ui_story_5036_50361301_35_dialog_content = "我也一個人在巨像上生活了十七年，雖然有臨空者號陪伴，並不覺得孤獨。",
  ui_story_5036_50361301_36_dialog_content = "但如果現在要我和我的夥伴們分開，我肯定是不願意的。",
  ui_story_5036_50361301_37_dialog_content = "說的也是呢。",
  ui_story_5036_50361301_38_dialog_content = "不過，我還是不明白，你剛才說的「添亂」……",
  ui_story_5036_50361301_39_dialog_content = "演唱會已經開始了，這顆龍蛋還能添什麼亂呢？",
  ui_story_5036_50361301_40_dialog_content = "嗯？你還挺敏銳的。",
  ui_story_5036_50361301_41_dialog_content = "我之前也說過，這顆龍蛋由於未知原因遲遲沒有孵化，所以才會長得這麼大。",
  ui_story_5036_50361301_42_dialog_content = "也因為如此，我不知道它什麼時候才會孵化。",
  ui_story_5036_50361301_43_dialog_content = "以現在龍蛋的大小，一旦孵化，銜尾龍的活動恐怕會影響整艘巨像吧。",
  ui_story_5036_50361301_44_dialog_content = "欸……！？",
  ui_story_5036_50361301_45_dialog_content = "這樣的話，這顆龍蛋豈不像是一顆不定時炸彈般危險！？",
  ui_story_5036_50361301_46_dialog_content = "是吧～",
  ui_story_5036_50361301_47_dialog_content = "所以才要好好看守這顆蛋，不僅是為了讓演唱會能順利舉行，也是為了你我小命著想。",
  ui_story_5036_50361301_48_dialog_content = "PlayerName能發現這樣的盲點，說不定很有神奇動物專家的資質。",
  ui_story_5036_50361301_49_dialog_content = "怎麼樣，考不考慮當我的徒弟？",
  ui_story_5036_50361301_50_option_content = "好啊",
  ui_story_5036_50361301_51_dialog_content = "這些神奇動物還是很有意思的，更何況有很多瀕臨滅絕。",
  ui_story_5036_50361301_52_dialog_content = "如果能好好保護的話，一定會有特別的意義吧。",
  ui_story_5036_50361301_53_dialog_content = "不錯的想法哦，PlayerName。不對，或許應該叫你小徒弟？",
  ui_story_5036_50361301_54_dialog_content = "先聲明，我可不會當免費勞力任你到處使喚。",
  ui_story_5036_50361301_55_dialog_content = "嗚嗚，在你眼中，為師像是這麼黑心的人嗎？",
  ui_story_5036_50361301_56_option_content = "還是算了",
  ui_story_5036_50361301_57_dialog_content = "雖然研究神奇動物很有趣，但看看菲雅和詩燁，就知道當你的徒弟有多辛苦了……",
  ui_story_5036_50361301_58_dialog_content = "不僅要照顧動物，還要照顧師父，外出調查也沒有經費……",
  ui_story_5036_50361301_59_dialog_content = "這是人過的日子嗎！？",
  ui_story_5036_50361301_60_dialog_content = "我們都是出於對神奇動物的愛才行動的，不求回報哦～",
  ui_story_5036_50361301_61_dialog_content = "你若不願意，我也不強求。",
  ui_story_5036_50361301_62_dialog_content = "耽誤了這麼多時間，也不知道現在演唱會進行到哪裡了。",
  ui_story_5036_50361301_63_dialog_content = "這樣吧，我先回去和歌爾蒂她們說一聲，免得她們擔心。",
  ui_story_5036_50361301_64_dialog_content = "好，那我繼續在這裡——",
  ui_story_5036_50361301_65_dialog_content = "啾——！",
  ui_story_5036_50361301_66_dialog_content = "這個聲音是？",
  ui_story_5036_50361301_67_dialog_content = "聲音？什麼聲音？難道你出現幻聽了嗎？",
  ui_story_5036_50361301_68_dialog_content = "卡蓮，妳有沒有聽到奇怪的聲音？",
  ui_story_5036_50361301_69_dialog_content = "好像是什麼動物在叫？",
  ui_story_5036_50361301_70_dialog_content = "呃……",
  ui_story_5036_50361301_71_dialog_content = "卡蓮！？妳還好嗎？怎麼……",
  ui_story_5036_50361301_72_dialog_content = "怎麼會……這麼睏……",
  ui_story_5036_50361301_73_dialog_content = "剛才似乎是銜尾龍的……叫聲……",
  ui_story_5036_50361301_74_dialog_content = "（咦？怎麼突然……好睏……）",
  ui_story_5036_50361301_75_dialog_content = "PlayerName？你怎麼了？快醒醒！？",
  ui_story_5036_50361301_76_dialog_content = "沒辦法，只能用那招了！比卡，趁現在把PlayerName口袋裡的白夜幣都吃掉！",
  ui_story_5036_50361301_77_dialog_content = "嗨！",
  ui_story_5036_50361301_78_dialog_content = "噫！？停......快停下！",
  ui_story_5036_50361301_79_dialog_content = "那可是我好不容易存下來的私房錢！！！",
  ui_story_5036_50361301_80_dialog_content = "哎呀，太好了，你清醒過來了。",
  ui_story_5036_50361301_81_dialog_content = "難道你昨晚熬夜了嗎？剛才差點就暈過去了。",
  ui_story_5036_50361301_82_dialog_content = "熬夜？沒有啊，我昨晚很早就休息了。",
  ui_story_5036_50361301_83_dialog_content = "太奇怪了，剛才聽見銜尾龍的叫聲以後，我就突然變得非常睏……",
  ui_story_5036_50361301_84_dialog_content = "你說你聽見了銜尾龍的叫聲？我怎麼沒聽見？",
  ui_story_5036_50361301_85_dialog_content = "我真的聽見了！不信的話，你仔細聽，說不定等等還會出現。",
  ui_story_5036_50361301_86_dialog_content = "好吧，那我來聽聽看。",
  ui_story_5036_50361301_87_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5036_50361301_88_dialog_content = "哪有什麼銜尾龍的叫聲，一定是你聽錯了吧。",
  ui_story_5036_50361301_89_dialog_content = "可是……",
  ui_story_5036_50361301_90_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_5036_50361301_91_dialog_content = "又有什麼聲音！但不像是銜尾龍的叫聲。",
  ui_story_5036_50361301_92_dialog_content = "這個聲音是！",
  ui_story_5036_50361301_93_dialog_content = "你聽到了嗎？",
  ui_story_5036_50361301_94_dialog_content = "<color=#e8d9bb>砰——砰——</color>",
  ui_story_5036_50361301_95_dialog_content = "我聽到了，這次聽得很清楚。",
  ui_story_5036_50361301_96_dialog_content = "這是……心跳聲。",
  ui_story_5036_50361301_97_dialog_content = "從龍蛋中傳出來的。",
  ui_story_5036_50361301_98_dialog_content = "欸！？難道說，銜尾龍要孵化了？",
  ui_story_5036_50361301_99_dialog_content = "竟挑這個時候，真是會為難人啊。",
  ui_story_5036_50361301_100_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5036_50361301_101_dialog_content = "這次又是什麼？",
  ui_story_5036_50361301_102_dialog_content = "小心，PlayerName！",
  ui_story_5036_50361301_103_dialog_content = "有什麼東西在撞擊我們之前堵住的牆縫！",
  ui_story_5036_50361301_104_dialog_content = "<color=#e8d9bb>轟隆——！！！</color>",
  ui_story_5036_50361301_105_dialog_content = "嘎吼——！",
  ui_story_5036_50361301_106_dialog_content = "是暗鬼！維克！",
  ui_story_5036_50361301_107_dialog_content = "小毛球，救命！",
  ui_story_5036_50361302_1_dialog_content = "這裡怎麼有這麼多暗鬼啊！？",
  ui_story_5036_50361302_2_dialog_content = "我們不是已經清掉附近的暗鬼了嗎？",
  ui_story_5036_50361302_3_dialog_content = "這些暗鬼，可能是從更遠的地方過來的。",
  ui_story_5036_50361302_4_dialog_content = "它們突然變得狂躁，或許和銜尾龍的孵化有關。",
  ui_story_5036_50361302_5_dialog_content = "無論如何，必須先告訴歌爾蒂他們這件事。",
  ui_story_5036_50361302_6_dialog_content = "如果銜尾龍真的快孵化，繼續待在巨像上會很危險！",
  ui_story_5036_50361302_7_dialog_content = "要趕快安排大家撤離！",
  ui_story_5036_50361302_8_dialog_content = "確實，繼續留在這裡也不是辦法。",
  ui_story_5036_50361302_9_dialog_content = "銜尾龍一旦孵化，整個房間說不定都會坍塌。",
  ui_story_5036_50361302_10_dialog_content = "我也該開溜了～",
  ui_story_5036_50361302_11_dialog_content = "應該是走這邊，PlayerName，可別掉隊了哦。",
  ui_story_5036_50361302_12_dialog_content = "等一下，那邊好像倒著兩個人？",
  ui_story_5036_50361302_13_dialog_content = "是薇絲和卡蓮！？",
  ui_story_5036_50361302_14_dialog_content = "薇絲、卡蓮，醒一醒！",
  ui_story_5036_50361302_15_dialog_content = "怎麼回事，竟然叫不醒她們。",
  ui_story_5036_50361302_16_dialog_content = "難道這也是銜尾龍的精神能力造成的影響嗎？",
  ui_story_5036_50361302_17_dialog_content = "帶上她們一起跑吧，繼續留在這裡太危險了。",
  ui_story_5036_50361302_18_dialog_content = "好，交給我，我來扶著她們走。",
  ui_story_5036_50361302_19_dialog_content = "嘿——呃！",
  ui_story_5036_50361302_20_dialog_content = "PlayerName得加強鍛鍊了。",
  ui_story_5036_50361302_21_dialog_content = "情況緊急就別幸災樂禍了，快來幫我！",
  ui_story_5036_50361302_22_dialog_content = "我這點力氣恐怕幫不上什麼忙，所以——",
  ui_story_5036_50361302_23_dialog_content = "小毛球，該你上了！",
  ui_story_5036_50361302_24_dialog_content = "嗚啾！",
  ui_story_5036_50361302_25_dialog_content = "原來它可以變大嗎！？",
  ui_story_5036_50361302_26_dialog_content = "那是當然。而且就算變大，它的絨毛也仍保持柔軟。",
  ui_story_5036_50361302_27_dialog_content = "午睡時靠上去非常舒服，你可以摸摸看，首摸免費。",
  ui_story_5036_50361302_28_dialog_content = "還是下次再說吧……",
  ui_story_5036_50361302_29_dialog_content = "總之，小毛球——不對，應該叫大毛球，薇絲和卡蓮就拜託你背著了。",
  ui_story_5036_50361302_30_dialog_content = "嗚啾——！",
  ui_story_5036_50361302_31_dialog_content = "我們繼續走吧，趕快回去、找到大家！",
  ui_story_5036_50361302_32_dialog_content = "這是……",
  ui_story_5036_50361302_33_dialog_content = "全都睡著了啊。",
  ui_story_5036_50361302_34_dialog_content = "那個小姑娘也一個人倒在舞台上。",
  ui_story_5036_50361302_35_dialog_content = "……",
  ui_story_5036_50361302_36_dialog_content = "歌爾蒂！醒醒！",
  ui_story_5036_50361302_37_dialog_content = "怎麼都叫不醒……",
  ui_story_5036_50361302_38_dialog_content = "她的狀況有點奇怪，似乎有光能術的痕跡。",
  ui_story_5036_50361302_39_dialog_content = "這也是銜尾龍造成的？",
  ui_story_5036_50361302_40_dialog_content = "可如果是銜尾龍的話，為什麼我們兩人沒事，其他人卻都陷入了沉睡？",
  ui_story_5036_50361302_41_dialog_content = "因為我們比較特別啊。",
  ui_story_5036_50361302_42_dialog_content = "你是空裔，擁有神奇的感應能力。",
  ui_story_5036_50361302_43_dialog_content = "而我的血脈和銜尾龍有很深的淵源，或許擁有某種抵抗力吧。",
  ui_story_5036_50361302_44_dialog_content = "有什麼辦法可以讓她們醒過來嗎？",
  ui_story_5036_50361302_45_dialog_content = "不知道。",
  ui_story_5036_50361302_46_dialog_content = "怎麼會……你不是說自己和銜尾龍有淵源嗎？為什麼沒辦法。",
  ui_story_5036_50361302_47_dialog_content = "很可惜，我雖然和銜尾龍有淵源，但除了活得久一點外，並沒有別的能力。",
  ui_story_5036_50361302_48_dialog_content = "倒是你可以試試看。",
  ui_story_5036_50361302_49_dialog_content = "你是空裔，你的感應能力或許可以感應到什麼我不知道的事。",
  ui_story_5036_50361302_50_dialog_content = "好吧，也只能先試試了。",
  ui_story_5036_50361401_1_dialog_content = "我好像，睡著了……",
  ui_story_5036_50361401_2_dialog_content = "這裡是空之山谷？難道我又在做夢了嗎？",
  ui_story_5036_50361401_3_dialog_content = "這次的夢好像又和之前不太一樣，夢境似乎也更加清晰了。",
  ui_story_5036_50361401_4_dialog_content = "就連那邊的白塔也能看得非常清楚。",
  ui_story_5036_50361401_5_dialog_content = "等等，那座塔正上方的天空是……",
  ui_story_5036_50361401_6_dialog_content = "龍？",
  ui_story_5036_50361401_7_dialog_content = "這絕對是在做夢吧！",
  ui_story_5036_50361401_8_dialog_content = "怎麼可以這樣，快醒醒，歌爾蒂，演唱會還沒結束呢！",
  ui_story_5036_50361401_9_dialog_content = "聽說在大腿上用力捏一把就能立刻醒過來。",
  ui_story_5036_50361401_10_dialog_content = "我捏！",
  ui_story_5036_50361401_11_dialog_content = "嘶——好痛！",
  ui_story_5036_50361401_12_dialog_content = "怎麼還是沒醒來，難道是我捏得不夠用力嗎？",
  ui_story_5036_50361401_13_dialog_content = "♪啦——啦啦♪",
  ui_story_5036_50361401_14_dialog_content = "好熟悉的歌聲……是那個叫夏米娜德的空裔女孩嗎？",
  ui_story_5036_50361401_15_dialog_content = "♪打濕……翅膀♪",
  ui_story_5036_50361401_16_dialog_content = "好像可以聽清她唱的歌詞了？",
  ui_story_5036_50361401_17_dialog_content = "之前的歌聲都太模糊，只能勉強聽見旋律。",
  ui_story_5036_50361401_18_dialog_content = "♪……故鄉♪",
  ui_story_5036_50361401_19_dialog_content = "歌聲好像是從那邊傳來的。",
  ui_story_5036_50361401_20_dialog_content = "♪只剩下回憶中的剎那♪",
  ui_story_5036_50361401_21_dialog_content = "♪佇立的白塔啊♪",
  ui_story_5036_50361401_22_dialog_content = "♪不見那指引航向的光♪",
  ui_story_5036_50361401_23_dialog_content = "（明明是優美的旋律，但是歌聲傳過來的情感，卻讓人覺得悲傷……）",
  ui_story_5036_50361401_24_dialog_content = "♪徘徊著，徘徊著♪",
  ui_story_5036_50361401_25_dialog_content = "♪思念那夢中的家鄉♪",
  ui_story_5036_50361401_26_dialog_content = "哎呀，竟然會有人來訪這裡。",
  ui_story_5036_50361401_27_dialog_content = "（欸！？她……她和我說話了！？）",
  ui_story_5036_50361401_28_dialog_content = "（之前的夢境都沒出現過這種情況，難道說，這不是夢？）",
  ui_story_5036_50361401_29_dialog_content = "妳……妳好啊，妳是夏米娜德吧？我是歌爾蒂，是一名偶像哦！",
  ui_story_5036_50361401_30_dialog_content = "欸？妳知道我的名字？",
  ui_story_5036_50361401_31_dialog_content = "當然知道！我的朋友PlayerName也是一名空裔，他感應到了妳過去的記憶。",
  ui_story_5036_50361401_32_dialog_content = "是嗎？哈哈，感覺有點不好意思呢。",
  ui_story_5036_50361401_33_dialog_content = "不過，偶像是什麼？",
  ui_story_5036_50361401_34_dialog_content = "偶像是用歌聲帶給別人歡樂和希望的職業哦，而我是專業的偶像！",
  ui_story_5036_50361401_35_dialog_content = "好厲害！我也想成為偶像！",
  ui_story_5036_50361401_36_dialog_content = "我可以教妳！只不過現在不行，我得趕回我的演唱會，繼續我的表演！",
  ui_story_5036_50361401_37_dialog_content = "夏米娜德，妳知不知道我該怎麼做才能離開這裡？",
  ui_story_5036_50361401_38_dialog_content = "對不起，我也不知道該怎麼讓妳離開……",
  ui_story_5036_50361401_39_dialog_content = "畢竟我自己也沒辦法離開這裡。",
  ui_story_5036_50361401_40_dialog_content = "沒辦法離開？",
  ui_story_5036_50361401_41_dialog_content = "（也對，畢竟真正的她已經……）",
  ui_story_5036_50361401_42_dialog_content = "（可如果夏米娜德早已經死了，那我眼前的這個人又是什麼呢？）",
  ui_story_5036_50361401_43_dialog_content = "唔，沒關係！",
  ui_story_5036_50361401_44_dialog_content = "只要去找，總會有辦法的！",
  ui_story_5036_50361401_45_dialog_content = "<color=#e8d9bb>轟隆——</color>",
  ui_story_5036_50361401_46_dialog_content = "咦？那是什麼聲音？",
  ui_story_5036_50361401_47_dialog_content = "是它們！",
  ui_story_5036_50361401_48_dialog_content = "快跑，它們要來了！",
  ui_story_5036_50361401_49_dialog_content = "它們？誰啊？",
  ui_story_5036_50361401_50_dialog_content = "暗鬼！",
  ui_story_5036_50361401_51_dialog_content = "嘎吼——！",
  ui_story_5036_50361401_52_dialog_content = "天啊，真的是暗鬼！而且這麼多！？",
  ui_story_5036_50361401_53_dialog_content = "吼——！",
  ui_story_5036_50361401_54_dialog_content = "究竟是從哪裡冒出來的！？",
  ui_story_5036_50361401_55_dialog_content = "又要來了，它們又來了！歌爾蒂，快躲起來！",
  ui_story_5036_50361401_56_dialog_content = "它們數量這麼多，我們沒地方躲了，只能和它們戰鬥了！",
  ui_story_5036_50361401_57_dialog_content = "製造混亂的暗鬼，我不會讓你們為所欲為！",
  ui_story_5036_50361402_1_dialog_content = "唔——！",
  ui_story_5036_50361402_2_dialog_content = "糟糕，這些暗鬼沒完沒了地冒出來，打都打不完！",
  ui_story_5036_50361402_3_dialog_content = "吼！",
  ui_story_5036_50361402_4_dialog_content = "唔啊！",
  ui_story_5036_50361402_5_dialog_content = "快跑！不用管我！它們過一陣子就會消失！不用管也沒關係！",
  ui_story_5036_50361402_6_dialog_content = "欸？消失？",
  ui_story_5036_50361402_7_dialog_content = "啾——",
  ui_story_5036_50361402_8_dialog_content = "啾——！",
  ui_story_5036_50361402_9_dialog_content = "那隻龍在發光！",
  ui_story_5036_50361402_10_dialog_content = "好耀眼，要看不見了——！",
  ui_story_5036_50361402_11_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5036_50361402_12_dialog_content = "得遠離暗鬼，遠離……咦？暗鬼都去哪裡了？",
  ui_story_5036_50361402_13_dialog_content = "已經沒事了，暗鬼都消失了。",
  ui_story_5036_50361402_13X1_dialog_content = "銜尾龍已經把它們都變沒了！",
  ui_story_5036_50361402_13X2_dialog_content = "對了，我還沒有向妳介紹銜尾龍吧？就是在天上飛的那孩子！",
  ui_story_5036_50361402_14_dialog_content = "消失？難道說，銜尾龍剛才發出的光芒，把暗鬼都消滅了？",
  ui_story_5036_50361402_15_dialog_content = "不，銜尾龍沒有那麼強大的力量，它只是還原了這個夢境。",
  ui_story_5036_50361402_16_dialog_content = "所以這裡果然是夢境！",
  ui_story_5036_50361402_17_dialog_content = "是的，這裡是銜尾龍幫我創造的夢境。",
  ui_story_5036_50361402_18_dialog_content = "既然妳的朋友是空裔，那他應該也看到了吧，我最後經歷的事情……",
  ui_story_5036_50361402_19_dialog_content = "嗯……",
  ui_story_5036_50361402_20_dialog_content = "在感應到我為了保護它而死後，銜尾龍就陷入了深沉的悲傷中。",
  ui_story_5036_50361402_21_dialog_content = "它感應到我想回家的願望，於是在自己的夢中創造了這座空之山谷——還有妳所看到的我。",
  ui_story_5036_50361402_22_dialog_content = "也因為如此，為了維持空之山谷的存在，它不得不長久沉睡。",
  ui_story_5036_50361402_23_dialog_content = "那剛才的暗鬼是？",
  ui_story_5036_50361402_24_dialog_content = "是我的恐懼。",
  ui_story_5036_50361402_25_dialog_content = "我害怕那些暗鬼，所以它們就出現在夢境中，不斷地出現、襲擊我。",
  ui_story_5036_50361402_26_dialog_content = "不過沒關係，有銜尾龍保護我，它會還原夢境，讓所有討厭的暗鬼消失！",
  ui_story_5036_50361402_27_dialog_content = "或許妳可以拜託銜尾龍，讓它送妳出去？",
  ui_story_5036_50361402_28_dialog_content = "好主意！我這就去問問。",
  ui_story_5036_50361402_29_dialog_content = "嗯！對了，在妳離開前，我能不能再和妳說說話？",
  ui_story_5036_50361402_30_dialog_content = "我也很想和妳聊天，但觀眾們肯定還在等我回去。",
  ui_story_5036_50361402_31_dialog_content = "不會很久的！就一個問題，可以嗎？",
  ui_story_5036_50361402_32_dialog_content = "當然可以，請說吧！",
  ui_story_5036_50361402_33_dialog_content = "現在的空之山谷變成什麼樣子了？",
  ui_story_5036_50361402_34_dialog_content = "拜託了，請告訴我！我真的很想知道！",
  ui_story_5036_50361402_35_dialog_content = "欸？空之山谷嗎？",
  ui_story_5036_50361402_36_dialog_content = "抱歉，我沒去過那裡……",
  ui_story_5036_50361402_37_dialog_content = "嗚……",
  ui_story_5036_50361402_38_dialog_content = "妳先別傷心！雖然我沒有去過，但我有一個可靠的空裔夥伴！",
  ui_story_5036_50361402_39_dialog_content = "是妳剛才提到的夥伴嗎？",
  ui_story_5036_50361402_40_dialog_content = "沒錯，他叫PlayerName，是個很了不起的人！",
  ui_story_5036_50361402_41_dialog_content = "在與他相遇之前，我只聽說他是一名駕駛巨像到處旅行的空裔。",
  ui_story_5036_50361402_42_dialog_content = "他和很多人成為了朋友，他們一起遊玩，也一起擊退暗鬼。",
  ui_story_5036_50361402_43_dialog_content = "我曾經很羨慕他的生活，覺得他無憂無慮又自由。",
  ui_story_5036_50361402_44_dialog_content = "但真的認識了他以後，我才知道他過得很辛苦。",
  ui_story_5036_50361402_45_dialog_content = "最初他在地下孤獨一人生活，直到遇見了讓他重見天日的朋友。",
  ui_story_5036_50361402_46_dialog_content = "他作為唯一的空裔不斷努力前行，甚至還重建了已經毀滅的空之山谷。",
  ui_story_5036_50361402_47_dialog_content = "欸？",
  ui_story_5036_50361402_48_dialog_content = "妳剛才說……空之山谷，毀滅了？空裔一族……只剩一人？",
  ui_story_5036_50361402_49_dialog_content = "啊！不是，我不是這個意思，我是說——",
  ui_story_5036_50361402_50_dialog_content = "我的……家……毀滅了……",
  ui_story_5036_50361402_51_dialog_content = "我的家……空之山谷……永遠都回不去了？",
  ui_story_5036_50361402_52_dialog_content = "怎麼會……怎麼會這樣！",
  ui_story_5036_50361402_53_dialog_content = "<color=#e8d9bb>轟隆！</color>",
  ui_story_5036_50361402_54_dialog_content = "<color=#e8d9bb>喀嚓——！</color>",
  ui_story_5036_50361402_55_dialog_content = "夢境開始崩塌了！是因為夏米娜德的情緒變化嗎？",
  ui_story_5036_50361402_56_dialog_content = "請……請妳冷靜一點！",
  ui_story_5036_50361402_57_dialog_content = "我的家……好想回家……嗚！",
  ui_story_5036_50361402_58_dialog_content = "冷靜不下來嗎……",
  ui_story_5036_50361402_59_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_5036_50361402_60_dialog_content = "啾，啾——！",
  ui_story_5036_50361402_61_dialog_content = "崩塌的範圍越來越大了，而且也沒有還原。",
  ui_story_5036_50361402_62_dialog_content = "怎麼辦才好？現在開始跳過所有的7數數還來得及嗎？",
  ui_story_5036_50361402_63_dialog_content = "不……不能站著不動，得行動起來！至少先遠離崩塌的區域才行！",
  ui_story_5036_50361402_64_dialog_content = "那座塔似乎仍很穩固，而且塔頂是最靠近銜尾龍的地方。",
  ui_story_5036_50361402_65_dialog_content = "夏米娜德，我們先走——唔啊！",
  ui_story_5036_50361402_66_dialog_content = "嗚嗚……",
  ui_story_5036_50361402_67_dialog_content = "好痛！她不讓我靠近！？",
  ui_story_5036_50361402_68_dialog_content = "夏米娜德？夏米娜德！請冷靜一點！！！",
  ui_story_5036_50361402_69_dialog_content = "夏米娜德不理我……",
  ui_story_5036_50361402_70_dialog_content = "再這樣下去，夏米娜德和整個夢境都危險了！",
  ui_story_5036_50361402_71_dialog_content = "我得想個辦法，修復這個夢境！",
  ui_story_5036_50361402_72_dialog_content = "希望那隻銜尾龍知道方法！",
  ui_story_5036_50361402_73_dialog_content = "這座塔真高啊，跑了這麼久竟然還沒到頂部！",
  ui_story_5036_50361402_74_dialog_content = "這裡又黑又空曠，到底是做什麼的地方？",
  ui_story_5036_50361402_75_dialog_content = "不行，我不能害怕黑暗！",
  ui_story_5036_50361402_76_dialog_content = "吼……",
  ui_story_5036_50361402_77_dialog_content = "連暗鬼也開始接近這裡了嗎？",
  ui_story_5036_50361402_78_dialog_content = "這也難怪，這座塔是夢境的中心，也是發生崩塌時最穩固的地方。",
  ui_story_5036_50361402_79_dialog_content = "就算是暗鬼也會過來避難吧。",
  ui_story_5036_50361402_80_dialog_content = "可現在不是浪費時間在它們身上的時候，還是先往塔頂跑吧！",
  ui_story_5036_50361402_81_dialog_content = "那邊好像有光，是出口！",
  ui_story_5036_50361402_82_dialog_content = "終於到了！",
  ui_story_5036_50361402_83_dialog_content = "啾，啾！",
  ui_story_5036_50361402_84_dialog_content = "銜尾龍，喂！銜尾龍——！",
  ui_story_5036_50361402_85_dialog_content = "請你復原這個夢境，讓夏米娜德冷靜下來！",
  ui_story_5036_50361402_86_dialog_content = "啾……",
  ui_story_5036_50361402_87_dialog_content = "（銜尾龍看起來也很困擾，難道說，它也沒有辦法嗎？）",
  ui_story_5036_50361402_88_dialog_content = "（那該怎麼辦才好！？）",
  ui_story_5036_50361402_89_dialog_content = "<color=#e8d9bb>轟！！！</color>",
  ui_story_5036_50361402_90_dialog_content = "連天空都開始崩壞了！？",
  ui_story_5036_50361402_91_dialog_content = "啾！啾——！",
  ui_story_5036_50361402_92_dialog_content = "銜尾龍似乎也很痛苦的樣子……",
  ui_story_5036_50361402_93_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_5036_50361402_94_dialog_content = "唔啊！？塔要塌了！？",
  ui_story_5036_50361402_95_dialog_content = "啊——！！！",
  ui_story_5036_50361402_96_dialog_content = "歌爾蒂，快抓住我的手！",
  ui_story_5036_50361402_97_dialog_content = "PlayerName！？",
  ui_story_5036_50361402_98_dialog_content = "你怎麼在這裡！？",
  ui_story_5036_50361402_99_dialog_content = "我和維克發現銜尾龍蛋不對勁，就趕回舞台查看。",
  ui_story_5036_50361402_100_dialog_content = "結果發現大家都睡著了，而且妳還受到了銜尾龍蛋的光能術影響。",
  ui_story_5036_50361402_101_dialog_content = "銜尾龍蛋不對勁？怎麼會這樣！",
  ui_story_5036_50361402_102_dialog_content = "說不定是因為聽到了妳的歌！",
  ui_story_5036_50361402_103_dialog_content = "使用啟動巨像的旋律編寫的歌曲，在銜尾龍聽起來說不定就像起床的鬧鐘一樣！",
  ui_story_5036_50361402_104_dialog_content = "欸！？",
  ui_story_5036_50361402_105_dialog_content = "再閒聊下去，我可要力氣耗盡鬆開手了——",
  ui_story_5036_50361402_106_dialog_content = "你撐住啊！！！",
  ui_story_5036_50361402_107_dialog_content = "哈哈哈，我看起來像是那麼不可靠的大人嗎？",
  ui_story_5036_50361402_108_dialog_content = "好啦，讓我們一起拉歌爾蒂走！",
  ui_story_5036_50361402_109_dialog_content = "歌爾蒂，抓緊我！",
  ui_story_5036_50361402_110_dialog_content = "唔啊！",
  ui_story_5036_50361402_111_dialog_content = "醒......醒過來了！？",
  ui_story_5036_50361402_112_dialog_content = "妳還好嗎？",
  ui_story_5036_50361402_113_dialog_content = "我沒事，只是頭有點暈暈的……",
  ui_story_5036_50361402_114_dialog_content = "轉正，我終於，轉正……啊，欸？我……我做夢了？",
  ui_story_5036_50361402_115_dialog_content = "唔……我是怎麼了？",
  ui_story_5036_50361402_116_dialog_content = "頭好痛，剛才是睡著了嗎？",
  ui_story_5036_50361402_117_dialog_content = "哈欠——早安？還是應該說晚安？",
  ui_story_5036_50361402_118_dialog_content = "竟然在觀眾席上睡著了！？這身衣服得好好清洗……",
  ui_story_5036_50361402_119_dialog_content = "哎呀，大家好像也都醒了。",
  ui_story_5036_50361402_120_dialog_content = "因為夢境恢復正常了？",
  ui_story_5036_50361402_121_dialog_content = "不，因為……",
  ui_story_5036_50361402_122_dialog_content = "銜尾龍要孵化了。",
  ui_story_5036_50361501_1_dialog_content = "<color=#e8d9bb>影鎮·金河沿岸</color>",
  ui_story_5036_50361501_2_dialog_content = "喂，這到底是怎麼回事？這歌手怎麼唱著唱著就睡著了？",
  ui_story_5036_50361501_3_dialog_content = "大姐姐不會有事吧？",
  ui_story_5036_50361501_4_dialog_content = "那個大姐姐那麼強，一定沒問題的！",
  ui_story_5036_50361501_5_dialog_content = "還有，這兩個根本沒見過的傢伙跑上台是在幹什麼？",
  ui_story_5036_50361501_6_dialog_content = "真是莫名其妙，根本在浪費我的時間，走了。",
  ui_story_5036_50361501_7_dialog_content = "先生，請留步。",
  ui_story_5036_50361501_8_dialog_content = "不要這麼早就下結論，因為……這一切都是計畫好了，是節目效果。",
  ui_story_5036_50361501_9_dialog_content = "什麼？",
  ui_story_5036_50361501_10_dialog_content = "這是我們刻意安排的環節，畢竟一直進行歌舞表演，未免過於無聊。",
  ui_story_5036_50361501_11_dialog_content = "所以安排了小插曲，當作給各位觀眾的驚喜。",
  ui_story_5036_50361501_12_dialog_content = "希望各位留步，繼續觀賞，這個驚喜一定會讓各位滿意。",
  ui_story_5036_50361501_13_dialog_content = "好吧，我就信你們一次。",
  ui_story_5036_50361501_14_dialog_content = "感謝支持！為了感謝各位觀眾的信任，我們準備了飲料和零食。",
  ui_story_5036_50361501_15_dialog_content = "還請各位笑納。",
  ui_story_5036_50361501_16_dialog_content = "（總算是勉強安撫了觀眾的情緒。）",
  ui_story_5036_50361501_17_dialog_content = "（歌爾蒂，妳那邊究竟發生了什麼？）",
  ui_story_5036_50361501_18_dialog_content = "（不只是她，PlayerName他們也在那艘巨像上，千萬不要有事啊……）",
  ui_story_5036_50361501_19_dialog_content = "<color=#e8d9bb>與此同時·歌頌者號上</color>",
  ui_story_5036_50361501_20_dialog_content = "你說什麼？銜尾龍要孵化了！？",
  ui_story_5036_50361501_21_dialog_content = "事出突然，來不及解釋了。",
  ui_story_5036_50361501_22_dialog_content = "總之，銜尾龍一旦孵化，整艘巨像很可能因此失去平衡，非常危險。",
  ui_story_5036_50361501_23_dialog_content = "現在最迫切的事是安排撤離。",
  ui_story_5036_50361501_24_dialog_content = "而且最好盡快哦，不然……啊，已經來不及了呢。",
  ui_story_5036_50361501_25_dialog_content = "吼——！！！",
  ui_story_5036_50361501_26_dialog_content = "暗鬼從巨像裡衝出來了！？",
  ui_story_5036_50361501_27_dialog_content = "都醒醒，趕緊部署防禦！",
  ui_story_5036_50361501_28_dialog_content = "是！",
  ui_story_5036_50361501_29_dialog_content = "嘎吼！",
  ui_story_5036_50361501_30_dialog_content = "別想過去！",
  ui_story_5036_50361501_31_dialog_content = "該死！髒東西怎麼越來越多。",
  ui_story_5036_50361501_32_dialog_content = "趕緊抵禦，別管有的沒的了。",
  ui_story_5036_50361501_33_dialog_content = "我知道！",
  ui_story_5036_50361501_34_dialog_content = "<color=#e8d9bb>轟……</color>",
  ui_story_5036_50361501_35_dialog_content = "整艘巨像在搖晃？簡直就像最終首領要出現了一樣！",
  ui_story_5036_50361501_36_dialog_content = "各位，抓穩！巨像裡面好像有什麼東西！",
  ui_story_5036_50361501_37_dialog_content = "啾——！",
  ui_story_5036_50361501_38_dialog_content = "好大的龍！",
  ui_story_5036_50361501_39_dialog_content = "真的孵化了！",
  ui_story_5036_50361501_40_dialog_content = "吼！！！",
  ui_story_5036_50361501_41_dialog_content = "暗鬼們開始攻擊銜尾龍了！？",
  ui_story_5036_50361501_42_dialog_content = "啾——啾——！",
  ui_story_5036_50361501_43_dialog_content = "姐姐，妳看，巨像上面！",
  ui_story_5036_50361501_44_dialog_content = "巨像上……出現了一隻龍！？",
  ui_story_5036_50361501_45_dialog_content = "呀！巨像搖搖晃晃的，看起來像是要掉下來了！",
  ui_story_5036_50361501_46_dialog_content = "<color=#e8d9bb>轟隆！！！</color>",
  ui_story_5036_50361501_47_dialog_content = "糟糕！現在銜尾龍剛破殼，還不能飛！",
  ui_story_5036_50361501_48_dialog_content = "再繼續被暗鬼攻擊，它會抵抗得更猛烈！",
  ui_story_5036_50361501_49_dialog_content = "有沒有什麼辦法能讓它先停下來？",
  ui_story_5036_50361501_50_dialog_content = "用你的感應能力試試？",
  ui_story_5036_50361501_51_dialog_content = "我試試！",
  ui_story_5036_50361501_52_option_content = "「銜尾龍，停下！」",
  ui_story_5036_50361501_53_dialog_content = "啾——！",
  ui_story_5036_50361501_54_dialog_content = "<color=#e8d9bb>轟！！！</color>",
  ui_story_5036_50361501_55_dialog_content = "嗚啊！",
  ui_story_5036_50361501_56_dialog_content = "不行，它完全不聽我的！",
  ui_story_5036_50361501_57_dialog_content = "舞台……被暗鬼包圍了。",
  ui_story_5036_50361501_58_dialog_content = "演唱會……完全毀掉了……",
  ui_story_5036_50361501_59_dialog_content = "歌爾蒂，振作起來！現在還很危險！",
  ui_story_5036_50361501_60_dialog_content = "我知道，可是……",
  ui_story_5036_50361501_61_dialog_content = "沒時間猶豫了。各位，重整陣型，盡量把暗鬼和那條龍隔開！",
  ui_story_5036_50361501_62_dialog_content = "遵命！",
  ui_story_5036_50361501_63_dialog_content = "啟光的各位也不能輸！首領戰開始了！",
  ui_story_5036_50361501_64_dialog_content = "是！！！",
  ui_story_5036_50361501_65_dialog_content = "薇絲和PlayerName，你們掩護一般群眾，先遠離戰鬥區域。",
  ui_story_5036_50361501_66_dialog_content = "聯繫臨空者號和白夜城的空艇，安排撤離！",
  ui_story_5036_50361501_67_dialog_content = "好，交給我吧！",
  ui_story_5036_50361501_68_dialog_content = "嗯！",
  ui_story_5036_50361501_69_dialog_content = "關鍵時刻，白夜城的騎士大人還真是可靠！",
  ui_story_5036_50361501_70_dialog_content = "你也別閒著，去想辦法讓那條龍安靜下來。",
  ui_story_5036_50361501_71_dialog_content = "饒了我吧，我可不擅長戰鬥啊……",
  ui_story_5036_50361501_72_dialog_content = "你這……唉，那你就跟著撤離吧。",
  ui_story_5036_50361501_73_dialog_content = "沒問題！我一定會乖乖撤離的！",
  ui_story_5036_50361501_74_dialog_content = "大家，都到這邊來！",
  ui_story_5036_50361501_75_dialog_content = "PlayerName，臨空者號怎麼樣了？",
  ui_story_5036_50361501_76_dialog_content = "銜尾龍鬧得太厲害了，臨空者號沒辦法進行接駁！",
  ui_story_5036_50361501_77_dialog_content = "如果能讓它安分一下子，哪怕只有一下子……",
  ui_story_5036_50361501_78_dialog_content = "看來一時之間沒辦法讓它安分下來了。",
  ui_story_5036_50361501_79_dialog_content = "白夜城的空艇呢？",
  ui_story_5036_50361501_80_dialog_content = "用不著妳說，我已經在聯絡了。",
  ui_story_5036_50361501_81_dialog_content = "原本演唱會就吸引了不少駕駛空艇來看熱鬧的貴族，現在已經有幾艘空艇投入救援了。",
  ui_story_5036_50361501_82_dialog_content = "城主大人已著手徵調整座白夜城的空艇，但還需要時間。",
  ui_story_5036_50361501_83_dialog_content = "更何況白夜城大多數是小型空艇，要載這麼多人離開，一趟遠遠不夠。",
  ui_story_5036_50361501_84_dialog_content = "要盡力爭取時間才行。",
  ui_story_5036_50361501_85_dialog_content = "呃——！",
  ui_story_5036_50361501_X85_dialog_content = "穩住！",
  ui_story_5036_50361501_87_dialog_content = "<color=#e8d9bb>吱嘎——！</color>",
  ui_story_5036_50361501_88_dialog_content = "卡蓮殿下，暗鬼太多，防線快要撐不住了！",
  ui_story_5036_50361501_89_dialog_content = "唔哇，白夜城的各位，我們最好離這裡遠一點！",
  ui_story_5036_50361501_90_dialog_content = "這條龍掙扎得太劇烈，這艘巨像又太過破舊……",
  ui_story_5036_50361501_91_dialog_content = "巨像的很多部件已經承受不住震動，開始破碎和崩塌了！",
  ui_story_5036_50361501_92_dialog_content = "空艇呢？",
  ui_story_5036_50361501_93_dialog_content = "報告！臨空者號無法接駁，但是白夜城的空艇已經在趕來的路上了！",
  ui_story_5036_50361501_94_dialog_content = "沒辦法，通知各隊，收縮防線，暫時放棄守衛銜尾龍，向人群靠攏！",
  ui_story_5036_50361501_95_dialog_content = "是！",
  ui_story_5036_50361501_96_dialog_content = "卡蓮！",
  ui_story_5036_50361501_97_dialog_content = "我沒事，大家都已經集合過來了嗎？",
  ui_story_5036_50361501_98_dialog_content = "報告殿下，人都在這裡了！",
  ui_story_5036_50361501_99_dialog_content = "最先一批的空艇已經抵達，撤離正在循序展開，但是……",
  ui_story_5036_50361501_100_dialog_content = "需要時間。",
  ui_story_5036_50361501_101_dialog_content = "空艇，太小。人，很多。",
  ui_story_5036_50361501_102_dialog_content = "我會盡量為你們爭取時間。",
  ui_story_5036_50361501_103_dialog_content = "不過要快！這艘巨像隨時有翻覆的可能！",
  ui_story_5036_50361501_104_dialog_content = "嗚……我……",
  ui_story_5036_50361501_105_dialog_content = "歌爾蒂，妳還好嗎？",
  ui_story_5036_50361501_106_dialog_content = "我已經沒事了，雖然，演唱會失敗了……",
  ui_story_5036_50361501_107_dialog_content = "但是，我要保護粉絲們，不能讓他們因為我的演唱會受傷。",
  ui_story_5036_50361501_108_dialog_content = "哪怕……哪怕這是我最後的演唱會！",
  ui_story_5036_50361501_109_dialog_content = "嗯，就讓我們先解決眼前的問題吧！",
  ui_story_5036_50361501_110_dialog_content = "對了，維克，銜尾龍真的不能——維克？",
  ui_story_5036_50361501_111_dialog_content = "他又跑哪裡去了？",
  ui_story_5036_50361501_112_dialog_content = "他剛才沒有和你們一起撤退嗎？",
  ui_story_5036_50361501_113_dialog_content = "我以為他一直跟著，所以沒有注意！",
  ui_story_5036_50361501_114_dialog_content = "哎呀，我果然還是不擅長戰鬥。",
  ui_story_5036_50361501_115_dialog_content = "我好像聽見了維克先生的聲音？",
  ui_story_5036_50361501_116_dialog_content = "他在那裡！",
  ui_story_5036_50361501_117_dialog_content = "不過，既然自稱神奇動物專家，我多少也要拿出點專家的本事吧。",
  ui_story_5036_50361501_118_dialog_content = "他怎麼一個人在那邊？",
  ui_story_5036_50361501_119_dialog_content = "快回來，危險！",
  ui_story_5036_50361501_120_dialog_content = "謝謝關心，不過現在還不行。",
  ui_story_5036_50361501_121_dialog_content = "那邊那些黑漆漆的傢伙們，往這裡看！",
  ui_story_5036_50361501_122_dialog_content = "嗚啾，哈——！",
  ui_story_5036_50361501_123_dialog_content = "吼……",
  ui_story_5036_50361501_124_dialog_content = "對，就是這樣……",
  ui_story_5036_50361501_125_dialog_content = "這裡有一個毫無還手之力的光靈，比銜尾龍更好對付。",
  ui_story_5036_50361501_126_dialog_content = "（再近一點，讓它們遠離銜尾龍。）",
  ui_story_5036_50361501_127_dialog_content = "（憑著泥尊鷹的能力，應該能拖住這些暗鬼足夠的時間。）",
  ui_story_5036_50361501_128_option_content = "維克，快回來！",
  ui_story_5036_50361501_129_dialog_content = "哈哈哈，沒事沒事，不用擔心。",
  ui_story_5036_50361501_130_dialog_content = "最優秀的神奇動物專家，可是能放心地把性命託付給神奇動物夥伴的！",
  ui_story_5036_50361501_131_dialog_content = "吼——！",
  ui_story_5036_50361501_132_dialog_content = "（很好，上鉤了！）",
  ui_story_5036_50361501_133_dialog_content = "（現在只需要喊泥尊鷹出來！）",
  ui_story_5036_50361501_134_dialog_content = "泥尊鷹！",
  ui_story_5036_50361501_135_dialog_content = "咕——咕咕！！！",
  ui_story_5036_50361501_136_dialog_content = "泥尊鷹，你怎麼跑了！？別跑啊——！",
  ui_story_5036_50361501_137_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5036_50361501_138_dialog_content = "啾——！",
  ui_story_5036_50361501_139_dialog_content = "什麼！？",
  ui_story_5036_50361501_140_dialog_content = "<color=#e8d9bb>唰——啪！！！</color>",
  ui_story_5036_50361501_141_dialog_content = "維克！？",
  ui_story_5036_50361501_142_dialog_content = "痛痛痛！",
  ui_story_5036_50361501_143_dialog_content = "（維克竟然被慌張的銜尾龍一尾巴抽飛了！等一下，那個位置是……！）",
  ui_story_5036_50361501_144_dialog_content = "維克，快跑啊！",
  ui_story_5036_50361501_145_dialog_content = "嘶——這條龍下手可真是不知輕重的。",
  ui_story_5036_50361501_146_dialog_content = "PlayerName，你剛才在喊什麼？我沒聽清楚。",
  ui_story_5036_50361501_147_dialog_content = "吼！",
  ui_story_5036_50361501_148_dialog_content = "哎呀……被......被包圍了！？",
  ui_story_5036_50361501_149_dialog_content = "各位暗鬼，我已經老了，一點都不好吃！",
  ui_story_5036_50361501_150_dialog_content = "你們看那邊那個空裔，他細皮嫩肉更年輕，比我好吃多了！",
  ui_story_5036_50361501_151_dialog_content = "吼！！！",
  ui_story_5036_50361501_152_dialog_content = "小毛球救我！！！",
  ui_story_5036_50361501_153_dialog_content = "PlayerName！！！",
  ui_story_5036_50361502_1_dialog_content = "太好了，總算活下來了！",
  ui_story_5036_50361502_2_dialog_content = "雖然吸引暗鬼注意的作戰完全失敗啦。",
  ui_story_5036_50361502_3_dialog_content = "你竟然還有心情笑！",
  ui_story_5036_50361502_4_dialog_content = "如果有作戰計畫，就要先提出來和大家商量啊！",
  ui_story_5036_50361502_5_dialog_content = "抱歉抱歉，我太擔心銜尾龍的安危，所以不小心把這件事忘了。",
  ui_story_5036_50361502_6_dialog_content = "如果銜尾龍沒有突然把我抽飛的話，作戰計畫就成功了～",
  ui_story_5036_50361502_7_dialog_content = "現在不是如不如果的問題吧！",
  ui_story_5036_50361502_8_dialog_content = "還有別的辦法能讓銜尾龍平靜下來嗎？",
  ui_story_5036_50361502_9_dialog_content = "很可惜，除了打倒所有暗鬼以外，我也沒有別的辦法了。",
  ui_story_5036_50361502_10_dialog_content = "難道就不能等到銜尾龍恢復飛行能力，自己離開嗎？",
  ui_story_5036_50361502_11_dialog_content = "情況恐怕沒那麼樂觀，暗鬼的攻勢太猛烈了。",
  ui_story_5036_50361502_12_dialog_content = "繼續纏鬥下去，就算等到銜尾龍恢復飛行能力，它也已經身受重傷飛不起來了。",
  ui_story_5036_50361502_13_dialog_content = "怎麼會……",
  ui_story_5036_50361502_14_dialog_content = "卡蓮殿下，我們收到了來自城主的指示。",
  ui_story_5036_50361502_15_dialog_content = "你說。",
  ui_story_5036_50361502_16_dialog_content = "撤離工作已近完成，白夜城和啟光的高層也做完這艘巨像的危險性評估。",
  ui_story_5036_50361502_17_dialog_content = "大人們決定，令士兵留在此處壓制暗鬼，盡可能穩住那隻龍，維持巨像的平衡。",
  ui_story_5036_50361502_18_dialog_content = "等巨像駛出影鎮的範圍，立刻擊沉。",
  ui_story_5036_50361502_19_dialog_content = "你們打算連著銜尾龍一起擊沉巨像？不可以！",
  ui_story_5036_50361502_20_dialog_content = "這隻銜尾龍說不定是全世界僅存的一隻。它死掉的話，這個物種就會徹底滅絕。",
  ui_story_5036_50361502_21_dialog_content = "我也不希望失去歌頌者號！",
  ui_story_5036_50361502_22_dialog_content = "那你們有什麼更好的辦法嗎？沒有就別在這裡說風涼話。",
  ui_story_5036_50361502_23_dialog_content = "巨像正下方就是影鎮最繁華的地帶，難道要我們置成千上萬光靈的生命於不顧？",
  ui_story_5036_50361502_24_dialog_content = "那麼，如果我拒絕離開巨像呢？",
  ui_story_5036_50361502_25_dialog_content = "維克，難道你想——",
  ui_story_5036_50361502_26_dialog_content = "我是神奇動物專家，自然沒辦法棄銜尾龍於不顧。",
  ui_story_5036_50361502_27_dialog_content = "你們要擊沉這艘巨像的話，就連我也一起擊沉吧～",
  ui_story_5036_50361502_28_dialog_content = "維克先生！？這太危險了！",
  ui_story_5036_50361502_29_dialog_content = "你這傢伙，別胡鬧！",
  ui_story_5036_50361502_30_dialog_content = "（怎麼辦？該怎麼辦才能拯救銜尾龍和這艘巨像？）",
  ui_story_5036_50361502_31_dialog_content = "（一定還有什麼辦法……）",
  ui_story_5036_50361502_32_dialog_content = "透過那些設備，我們的歌聲可以百分之百傳遞到地面的觀眾耳朵裡去哦～",
  ui_story_5036_50361502_33_dialog_content = "真是令人驚訝，這種生物竟然能夠透過空裔操縱巨像的旋律和人交流。",
  ui_story_5036_50361502_34_dialog_content = "使用啟動巨像的旋律編寫的歌曲，在銜尾龍聽起來說不定就像起床的鬧鐘一樣！",
  ui_story_5036_50361502_35_dialog_content = "還有一個辦法，我想試試看！",
  ui_story_5036_50361502_36_dialog_content = "欸？",
  ui_story_5036_50361502_37_dialog_content = "什麼辦法？",
  ui_story_5036_50361502_38_dialog_content = "夏米娜德過去發現，銜尾龍能聽懂空裔用來操縱巨像的旋律。",
  ui_story_5036_50361502_39_dialog_content = "如果能播放關閉巨像的旋律給銜尾龍聽，同時阻擋暗鬼，或許它就能安靜下來！",
  ui_story_5036_50361502_40_dialog_content = "哦？這個主意聽起來不錯啊，PlayerName！",
  ui_story_5036_50361502_41_dialog_content = "PlayerName的感應能力都沒辦法讓銜尾龍聽話，只靠歌聲真的沒問題嗎？",
  ui_story_5036_50361502_42_dialog_content = "嗯……只要音量夠大，應該就能引起它的注意。",
  ui_story_5036_50361502_43_dialog_content = "或許我們可以利用舞台的音響設備。",
  ui_story_5036_50361502_44_dialog_content = "嗯，我需要歌爾蒂的協助，使用她的光能術和那些設備，應該就可以！",
  ui_story_5036_50361502_45_dialog_content = "我？",
  ui_story_5036_50361502_46_dialog_content = "……",
  ui_story_5036_50361502_47_dialog_content = "我知道了。",
  ui_story_5036_50361502_48_dialog_content = "我的演唱會還沒有結束，我的歌也沒有唱完。",
  ui_story_5036_50361502_49_dialog_content = "哪怕未來我沒辦法再以偶像的身分登上舞台，只要還有你，還有我的粉絲……",
  ui_story_5036_50361502_50_dialog_content = "只要你們還需要我，我就會去唱。",
  ui_story_5036_50361502_51_dialog_content = "更何況，巨像的正下方就是影鎮，是我和粉絲們的家園。",
  ui_story_5036_50361502_52_dialog_content = "PlayerName，這種方法，你有多少成功的把握？",
  ui_story_5036_50361502_53_option_content = "我沒有十足的把握……",
  ui_story_5036_50361502_54_option_content = "我想試試！",
  ui_story_5036_50361502_55_dialog_content = "好吧。",
  ui_story_5036_50361502_56_dialog_content = "我會幫你。",
  ui_story_5036_50361502_57_dialog_content = "卡蓮殿下！？您認真的嗎！？",
  ui_story_5036_50361502_58_dialog_content = "我當然是認真的，但我也會做好失敗後的支援。",
  ui_story_5036_50361502_59_dialog_content = "通知各隊！準備作戰！",
  ui_story_5036_50361502_60_dialog_content = "我明白了。騎士，整隊！",
  ui_story_5036_50361502_61_dialog_content = "卡蓮，謝謝妳！",
  ui_story_5036_50361502_62_dialog_content = "我也會一起幫忙的！",
  ui_story_5036_50361502_63_dialog_content = "但是，負責調整設備的工作人員，剛剛似乎已經搭乘空艇撤離了。",
  ui_story_5036_50361502_64_dialog_content = "設備的事不用擔心，別忘記我們也在呢！",
  ui_story_5036_50361502_65_dialog_content = "這些設備雖然經過改裝，但使用方法都是差不多的，就交給我們吧。",
  ui_story_5036_50361502_66_dialog_content = "貢露、希諾普！？",
  ui_story_5036_50361502_67_dialog_content = "PlayerName要去挑戰一個超——困難的成就了吧？",
  ui_story_5036_50361502_68_dialog_content = "這麼好玩的事情，當然要帶我一個！",
  ui_story_5036_50361502_69_dialog_content = "還……還有我！",
  ui_story_5036_50361502_70_dialog_content = "這幾天我一直在採訪，採訪對像也包括負責控制舞台音響的工作人員。",
  ui_story_5036_50361502_71_dialog_content = "設備的使用方法，在採訪的時候我也趁機學了一些！",
  ui_story_5036_50361502_72_dialog_content = "雖然似乎會很危險，但是請帶上我，我會盡力幫助歌爾蒂和你的！",
  ui_story_5036_50361502_73_dialog_content = "謝謝……",
  ui_story_5036_50361502_74_dialog_content = "難得大家達成共識了，真不得了啊，PlayerName。",
  ui_story_5036_50361502_75_dialog_content = "擁有這種能力，該說不愧是名為空裔的神奇動物嗎？",
  ui_story_5036_50361502_76_dialog_content = "等等，我不是神奇動物！",
  ui_story_5036_50361502_77_dialog_content = "哈哈哈，別爭辯了。",
  ui_story_5036_50361502_78_dialog_content = "時間緊迫，我們先去拯救銜尾龍吧！",
  ui_story_5036_50361502_79_dialog_content = "嗯，朝舞台，出發！",
  ui_story_5036_50361601_1_dialog_content = "歌爾蒂，剛才我教妳的旋律都記住了嗎？",
  ui_story_5036_50361601_2_dialog_content = "當然！我記得一清二楚！",
  ui_story_5036_50361601_3_dialog_content = "只是通向舞台的路上，有好多暗鬼……",
  ui_story_5036_50361601_4_dialog_content = "不用擔心那些傢伙，我會帶領大家為你們打開通向舞台的道路。",
  ui_story_5036_50361601_5_dialog_content = "沒錯，戰鬥的事就交給我們吧，妳只管專心唱歌！",
  ui_story_5036_50361601_6_dialog_content = "嗯～雖然我沒辦法戰鬥，但是也會讓小毛球它們幫忙的。",
  ui_story_5036_50361601_7_dialog_content = "嗚啾！",
  ui_story_5036_50361601_8_dialog_content = "謝謝妳願意幫我，歌爾蒂。",
  ui_story_5036_50361601_9_dialog_content = "不用謝。",
  ui_story_5036_50361601_10_dialog_content = "這幾天，PlayerName也一直都在幫我。",
  ui_story_5036_50361601_11_dialog_content = "如果沒有PlayerName的努力，也沒辦法舉辦這場演唱會。",
  ui_story_5036_50361601_12_dialog_content = "可是，演唱會明明都失敗了……",
  ui_story_5036_50361601_13_dialog_content = "儘管如此，PlayerName付出的努力我仍都看到了！",
  ui_story_5036_50361601_14_dialog_content = "這些努力不會隨著演唱會的失敗而消失的。",
  ui_story_5036_50361601_15_dialog_content = "現在，是時候輪到我報答你的付出了！",
  ui_story_5036_50361601_16_dialog_content = "嗯！",
  ui_story_5036_50361601_17_dialog_content = "那麼，出發吧！",
  ui_story_5036_50361601_18_dialog_content = "嗷吼——！",
  ui_story_5036_50361601_19_dialog_content = "暗鬼來了，大家準備戰鬥！",
  ui_story_5036_50361602_1_dialog_content = "終於到達舞台了，設備呢？",
  ui_story_5036_50361602_2_dialog_content = "設備沒有問題！",
  ui_story_5036_50361602_3_dialog_content = "音響最大輸出功率——！",
  ui_story_5036_50361602_4_dialog_content = "吼——！",
  ui_story_5036_50361602_5_dialog_content = "呀！？",
  ui_story_5036_50361602_6_dialog_content = "速射感知！",
  ui_story_5036_50361602_7_dialog_content = "謝……謝謝！",
  ui_story_5036_50361602_8_dialog_content = "不用謝！",
  ui_story_5036_50361602_9_dialog_content = "暗鬼就交給我們吧，你們專心操作設備！",
  ui_story_5036_50361602_10_dialog_content = "只要我們還守在這裡，就不會放任何一隻暗鬼過去。",
  ui_story_5036_50361602_11_dialog_content = "吼！",
  ui_story_5036_50361602_12_dialog_content = "別想跑！",
  ui_story_5036_50361602_13_dialog_content = "好機會，小毛球，攻擊它的背後！",
  ui_story_5036_50361602_14_dialog_content = "嗚啾！",
  ui_story_5036_50361602_15_dialog_content = "吼——",
  ui_story_5036_50361602_16_dialog_content = "哎呀，這傢伙怎麼跑得比我還快，小毛球都追不上。",
  ui_story_5036_50361602_17_dialog_content = "它到處亂跑，真不好對付！",
  ui_story_5036_50361602_18_dialog_content = "堅持住，至少不能讓它在歌爾蒂唱歌的時候搗亂。",
  ui_story_5036_50361602_19_dialog_content = "嗯！",
  ui_story_5036_50361602_20_dialog_content = "（大家都在努力戰鬥，我也要做好我該做的事情。）",
  ui_story_5036_50361602_21_dialog_content = "啾——啾！",
  ui_story_5036_50361602_22_dialog_content = "<color=#e8d9bb>轟隆——！</color>",
  ui_story_5036_50361602_23_dialog_content = "銜尾龍，你也覺得很痛苦吧……",
  ui_story_5036_50361602_24_dialog_content = "但是，請你再稍微忍耐一下，請相信我們會好好保護你的。",
  ui_story_5036_50361602_25_dialog_content = "大家，我要開始唱了！",
  ui_story_5036_50361602_26_dialog_content = "收到！",
  ui_story_5036_50361602_27_dialog_content = "（冷靜下來，歌爾蒂。）",
  ui_story_5036_50361602_28_dialog_content = "（就用這首歌撫平銜尾龍的恐懼，讓它鎮靜下來。）",
  ui_story_5036_50361602_29_dialog_content = "（也用這首歌，向偶像、向舞台告別吧。）",
  ui_story_5036_50361602_30_dialog_content = "銜尾龍，請聽我為你獻上的這首歌吧！",
  ui_story_5036_50361602_31_dialog_content = "♪天地寬廣，星海如波♪",
  ui_story_5036_50361602_32_dialog_content = "♪我們如流星一般誕生，頑皮的孩子♪",
  ui_story_5036_50361602_33_dialog_content = "♪歡樂地遊玩，仍有疲憊的時刻♪",
  ui_story_5036_50361602_34_dialog_content = "♪家的燈火，指引溫暖的歸巢♪",
  ui_story_5036_50361602_35_dialog_content = "請大家按照指示，循序避難！影主會保護大家的安全！",
  ui_story_5036_50361602_36_dialog_content = "♪家的燈火，指引溫暖的歸巢♪",
  ui_story_5036_50361602_37_dialog_content = "姐姐，你聽到了嗎？",
  ui_story_5036_50361602_38_dialog_content = "好像有歌聲傳來了！",
  ui_story_5036_50361602_39_dialog_content = "大小姐，所有避難人員已經從空艇上下來了。",
  ui_story_5036_50361602_40_dialog_content = "好，再次準備出發，去救援下一批受困者！",
  ui_story_5036_50361602_41_dialog_content = "♪家的燈火，指引溫暖的歸巢♪",
  ui_story_5036_50361602_42_dialog_content = "這是……歌聲？",
  ui_story_5036_50361602_43_dialog_content = "好溫柔的歌聲，是從那艘巨像上傳來的？",
  ui_story_5036_50361602_44_dialog_content = "♪疲憊的孩子，請安睡吧♪",
  ui_story_5036_50361602_45_dialog_content = "♪我頌唱這首搖籃曲，守護你的夢♪",
  ui_story_5036_50361602_46_dialog_content = "♪此處即為家園♪",
  ui_story_5036_50361602_47_dialog_content = "啾——！",
  ui_story_5036_50361602_48_dialog_content = "（銜尾龍好像有反應了！）",
  ui_story_5036_50361602_49_dialog_content = "卡蓮，PlayerName！銜尾龍掙扎的力度變小了！",
  ui_story_5036_50361602_50_dialog_content = "太好了，歌聲起作用了！",
  ui_story_5036_50361602_51_dialog_content = "巨像也停止搖晃了，這樣下去可以的！",
  ui_story_5036_50361602_52_dialog_content = "趁現在，一定要擋住暗鬼的進攻！",
  ui_story_5036_50361602_53_dialog_content = "♪此處即為家園♪",
  ui_story_5036_50361602_54_dialog_content = "是歌聲？",
  ui_story_5036_50361602_55_dialog_content = "這首旋律是讓巨像停下來的旋律，像是搖籃曲般溫柔呢。",
  ui_story_5036_50361602_56_dialog_content = "是歌爾蒂在唱歌嗎？但是……",
  ui_story_5036_50361602_57_dialog_content = "♪然而如今家園已不復在♪",
  ui_story_5036_50361602_58_dialog_content = "（我好像聽見夏米娜德在唱歌！？）",
  ui_story_5036_50361602_59_dialog_content = "（她現在一定很悲傷吧。我甚至來不及安慰她……）",
  ui_story_5036_50361602_60_dialog_content = "（或許她只是夢中的幻影，而不是真實存在的某個人。）",
  ui_story_5036_50361602_61_dialog_content = "（但是那份悲傷與孤獨卻是如此真實。）",
  ui_story_5036_50361602_62_dialog_content = "（那麼，我就把這首歌獻給妳吧，夏米娜德。）",
  ui_story_5036_50361602_63_dialog_content = "（希望它能帶走妳的悲傷。）",
  ui_story_5036_50361602_64_dialog_content = "♪然而如今家園已不復在♪",
  ui_story_5036_50361602_65_dialog_content = "♪但仍有少年踏上征程♪",
  ui_story_5036_50361602_66_dialog_content = "♪淚水浸濕長夜♪",
  ui_story_5036_50361602_67_dialog_content = "♪歷經悲歡離合♪",
  ui_story_5036_50361602_68_dialog_content = "♪還能否看見希望的曙光♪",
  ui_story_5036_50361602_69_dialog_content = "♪一定仍在前方等待的光♪",
  ui_story_5036_50361602_70_dialog_content = "速射感知！",
  ui_story_5036_50361602_71_dialog_content = "究竟還有多少……！",
  ui_story_5036_50361602_72_dialog_content = "吼！！！",
  ui_story_5036_50361602_73_dialog_content = "小心，它又來了！",
  ui_story_5036_50361602_74_dialog_content = "不會讓你靠近的！",
  ui_story_5036_50361602_75_dialog_content = "這就是妳的歌嗎，歌爾蒂？",
  ui_story_5036_50361602_76_dialog_content = "這首歌好溫暖，彷彿空之山谷的陽光和微風。",
  ui_story_5036_50361602_77_dialog_content = "原來如此啊，空之山谷雖然遭受毀壞，卻沒有消失，家園……還能再重建。",
  ui_story_5036_50361602_78_dialog_content = "歌爾蒂，妳的歌，我聽到了。",
  ui_story_5036_50361602_79_dialog_content = "所以，我也——",
  ui_story_5036_50361602_80_dialog_content = "♪或許應該嘗試擦乾眼淚♪",
  ui_story_5036_50361602_81_dialog_content = "♪擦乾眼淚，再起航——♪",
  ui_story_5036_50361602_82_dialog_content = "♪將這歌聲，攜向遠方♪",
  ui_story_5036_50361602_83_dialog_content = "謝謝妳，歌爾蒂。",
  ui_story_5036_50361602_84_dialog_content = "來自未來的偶像啊，銜尾龍，還有接下來的事，就拜託妳了。",
  ui_story_5036_50361602_85_dialog_content = "夏米娜德……好像完全消失了。",
  ui_story_5036_50361602_86_dialog_content = "啾——",
  ui_story_5036_50361602_87_dialog_content = "銜尾龍，平靜下來了！",
  ui_story_5036_50361602_88_dialog_content = "成功了！PlayerName，作戰計畫成功了！",
  ui_story_5036_50361602_89_dialog_content = "太好了！",
  ui_story_5036_50361602_90_dialog_content = "但是這邊快撐不住了！",
  ui_story_5036_50361602_91_dialog_content = "呃！",
  ui_story_5036_50361602_92_dialog_content = "吼！！！",
  ui_story_5036_50361602_93_dialog_content = "速射感知！！！",
  ui_story_5036_50361602_94_dialog_content = "吼……吼！！！",
  ui_story_5036_50361602_95_dialog_content = "這傢伙究竟有多頑強啊，承受了這麼多攻擊都還打不倒！？",
  ui_story_5036_50361602_96_dialog_content = "能在這艘巨像上生存的暗鬼，恐怕都不是什麼好對付的傢伙。",
  ui_story_5036_50361602_97_dialog_content = "再堅持一下，銜尾龍應該馬上就能飛起來了！",
  ui_story_5036_50361602_98_dialog_content = "吼——！！！",
  ui_story_5036_50361602_99_dialog_content = "卡蓮小心！",
  ui_story_5036_50361602_100_dialog_content = "啾！",
  ui_story_5036_50361602_101_dialog_content = "<color=#e8d9bb>啪——！！！</color>",
  ui_story_5036_50361602_102_dialog_content = "吼——",
  ui_story_5036_50361602_103_dialog_content = "唔哇！？這，這是！？",
  ui_story_5036_50361602_104_dialog_content = "銜尾龍用尾巴抽飛了那隻暗鬼！",
  ui_story_5036_50361602_105_dialog_content = "啾......啾～",
  ui_story_5036_50361602_106_dialog_content = "它看起來已經不再驚慌了，好像還很高興的樣子！",
  ui_story_5036_50361602_107_dialog_content = "真是幫大忙了，只要沒有那隻暗鬼搗亂，剩下的暗鬼不足為懼。",
  ui_story_5036_50361602_108_dialog_content = "冰花，綻放吧！",
  ui_story_5036_50361602_109_dialog_content = "吼……",
  ui_story_5036_50361602_110_dialog_content = "啾——！",
  ui_story_5036_50361602_111_dialog_content = "<color=#e8d9bb>轟隆——</color>",
  ui_story_5036_50361602_112_dialog_content = "巨像又開始搖晃了！？",
  ui_story_5036_50361602_113_dialog_content = "銜尾龍不是已經平靜下來了嗎？",
  ui_story_5036_50361602_114_dialog_content = "抓穩，銜尾龍似乎要起飛了！",
  ui_story_5036_50361602_115_dialog_content = "啾——",
  ui_story_5036_50361602_116_dialog_content = "啾！！！",
  ui_story_5036_50361602_117_dialog_content = "快看，巨像上的那隻龍飛走了！",
  ui_story_5036_50361602_118_dialog_content = "是真的！大姐姐還在那艘巨像上嗎？她不會有事吧？",
  ui_story_5036_50361602_119_dialog_content = "那位大姐姐可是一位厲害的偶像。",
  ui_story_5036_50361602_120_dialog_content = "不管遇到什麼困難，她一定都會跨越。",
  ui_story_5036_50361602_121_dialog_content = "所以……相信她吧。",
  ui_story_5036_50361602_122_dialog_content = "嗯！",
  ui_story_5036_50361602_123_dialog_content = "我也相信她！",
  ui_story_5036_50361602_124_dialog_content = "好了，你們也快跟著大家一起去避難吧。",
  ui_story_5036_50361602_125_dialog_content = "那條龍離開了，難道說已經結束了嗎？",
  ui_story_5036_50361602_126_dialog_content = "要盡快聯繫他們，確認情況才行。",
  ui_story_5036_50361602_127_dialog_content = "報告，從漂流巨像上撤離的人員已經全部安置妥當了。",
  ui_story_5036_50361602_128_dialog_content = "僅有幾人受了擦傷，沒有重傷者或死者！",
  ui_story_5036_50361602_129_dialog_content = "幸好這次有城主大人乘坐空艇跟隨著漂流巨像。",
  ui_story_5036_50361602_130_dialog_content = "白夜城才能在這麼短的時間內迅速反應，把傷害控制在最低程度。",
  ui_story_5036_50361602_131_dialog_content = "巨像和龍的情況如何？",
  ui_story_5036_50361602_132_dialog_content = "龍已經離開巨像了，但卡蓮姐姐他們還在巨像上。",
  ui_story_5036_50361602_133_dialog_content = "……",
  ui_story_5036_50361602_134_dialog_content = "PlayerName和薇絲姐姐都在，卡蓮姐姐一定會平安無事的！",
  ui_story_5036_50361602_135_dialog_content = "命令空艇繼續協助巨像上的人員撤離。",
  ui_story_5036_50361602_136_dialog_content = "遵命！",
  ui_story_5036_50361602_137_dialog_content = "<color=#e8d9bb>轟隆！</color>",
  ui_story_5036_50361602_138_dialog_content = "嗚啊！？",
  ui_story_5036_50361602_139_dialog_content = "巨像好像正在傾斜！？",
  ui_story_5036_50361602_140_dialog_content = "呀！？",
  ui_story_5036_50361602_141_dialog_content = "銜尾龍的離開，影響了巨像的平衡！",
  ui_story_5036_50361602_142_dialog_content = "巨像開始往更高處飛了！",
  ui_story_5036_50361602_143_dialog_content = "作戰計畫大成功！",
  ui_story_5036_50361602_144_dialog_content = "我們趕快撤離吧，這裡暗鬼太多，不是我們這點兵力能完全應付的！",
  ui_story_5036_50361602_145_dialog_content = "PlayerName！",
  ui_story_5036_50361602_146_dialog_content = "銜尾龍已經飛走了，我們成功了！",
  ui_story_5036_50361602_147_dialog_content = "可喜可賀，可喜可賀！",
  ui_story_5036_50361602_148_option_content = "夏米娜德呢？",
  ui_story_5036_50361602_149_dialog_content = "我剛才好像聽見她在唱歌，而且是和妳合唱。",
  ui_story_5036_50361602_150_dialog_content = "她似乎已經消失了……",
  ui_story_5036_50361602_151_dialog_content = "不是隨著銜尾龍離開，而是徹底消失了。",
  ui_story_5036_50361602_152_dialog_content = "是嗎……",
  ui_story_5036_50361602_153_dialog_content = "嗯，她最後還說，之後就拜託我了。",
  ui_story_5036_50361602_154_dialog_content = "她應該也很想把這首歌唱給整個艾斯特拉大陸的人們聽吧。",
  ui_story_5036_50361602_155_option_content = "歌頌者號怎麼辦？",
  ui_story_5036_50361602_156_dialog_content = "已經沒事了，但是銜尾龍的離去使它的航向產生偏移。",
  ui_story_5036_50361602_157_dialog_content = "這艘巨像開始飛往更高處了。",
  ui_story_5036_50361602_158_dialog_content = "PlayerName，現在沒時間聊天了，還是趕快撤退吧！",
  ui_story_5036_50361602_159_dialog_content = "銜尾龍的離開改變了歌頌者號的航向，重量減輕也讓它的速度加快了。",
  ui_story_5036_50361602_160_dialog_content = "是啊，按照現在的速度，再過十幾分鐘，巨像就會飛到我們無法呼吸的高度。",
  ui_story_5036_50361602_161_dialog_content = "我們還是趕快離開吧！",
  ui_story_5036_50361602_162_dialog_content = "那歌頌者號——",
  ui_story_5036_50361602_163_dialog_content = "歌頌者號……恐怕沒辦法再回來了。",
  ui_story_5036_50361602_164_dialog_content = "就算是貢露前輩，也沒辦法在這麼短的時間內修好歌頌者號的控制系統。",
  ui_story_5036_50361602_165_dialog_content = "那我們的努力，豈不是白費了？",
  ui_story_5036_50361602_166_dialog_content = "才沒有白費呢！",
  ui_story_5036_50361602_167_dialog_content = "就算演唱會最終失敗了，但是我們已經讓大家都看到了歌頌者號上的這場演唱會。",
  ui_story_5036_50361602_168_dialog_content = "更何況，這趟旅行也讓我們知道了它和夏米娜德之間的故事。",
  ui_story_5036_50361602_169_dialog_content = "只要我們不忘記，他們就會永遠存在。",
  ui_story_5036_50361602_170_dialog_content = "……",
  ui_story_5036_50361602_171_option_content = "我們走吧",
  ui_story_5036_50361602_172_option_content = "我會一直記得他們",
  ui_story_5036_50361602_173_dialog_content = "嗯！",
  ui_story_5036_50361602_174_dialog_content = "PlayerName，快要來不及了。",
  ui_story_5036_50361602_175_dialog_content = "我們回去吧。",
  ui_story_5036_50361602_176_dialog_content = "嗯。",
  ui_story_5036_50361602_177_dialog_content = "對不起，歌頌者號……",
  ui_story_5036_50361602_178_dialog_content = "再見。",
  ui_story_5036_50361701_1_dialog_content = "臨空者號，啟動！",
  ui_story_5036_50361701_2_dialog_content = "<color=#e8d9bb>轟隆！</color>",
  ui_story_5036_50361701_3_dialog_content = "歌頌者號越飛越高，向著遙遠的星空飛去了。",
  ui_story_5036_50361701_4_dialog_content = "它一定是去把夏米娜德的歌聲帶給星星們聽了吧。",
  ui_story_5036_50361701_5_dialog_content = "無論如何，我們終於安全了。",
  ui_story_5036_50361701_6_dialog_content = "演唱會雖然失敗了，也沒有成功保住歌頌者號。",
  ui_story_5036_50361701_7_dialog_content = "但大家都平安無事，影鎮的人們也不用再擔心受怕，這樣就很好了。",
  ui_story_5036_50361701_8_dialog_content = "我還是不明白，為什麼銜尾龍會突然孵化？",
  ui_story_5036_50361701_9_dialog_content = "如果它能再晚一點孵化，說不定就不會變成這樣……",
  ui_story_5036_50361701_10_dialog_content = "那個，PlayerName，我想了一下，覺得有可能是我造成的。",
  ui_story_5036_50361701_11_dialog_content = "我在我的夢裡……不，正確地說，是在銜尾龍的夢裡，遇見了夏米娜德。",
  ui_story_5036_50361701_12_dialog_content = "「遇見」？不應該是「夢見」嗎？",
  ui_story_5036_50361701_13_dialog_content = "不，確實是「遇見」。",
  ui_story_5036_50361701_14_dialog_content = "夏米娜德到底是什麼？",
  ui_story_5036_50361701_15_dialog_content = "該不會真的有早已逝去之人，能用某種方法繼續存在吧？",
  ui_story_5036_50361701_16_dialog_content = "感覺有點讓人背脊發涼呢……",
  ui_story_5036_50361701_17_dialog_content = "夢中的夏米娜德，或許是銜尾龍想像出來的也說不定。",
  ui_story_5036_50361701_18_dialog_content = "啊？妳是說，那個夏米娜德並不是真的夏米娜德？",
  ui_story_5036_50361701_19_dialog_content = "嗯。我記得，夢境裡的夏米娜德說過——",
  ui_story_5036_50361701_20_dialog_content = "「它感應到我想回家的願望，於是在自己的夢中創造了這座空之山谷——還有妳所看到的我。」",
  ui_story_5036_50361701_21_dialog_content = "所以我猜，那個夢中的空之山谷，以及我看到的夏米娜德，都是銜尾龍創造的。",
  ui_story_5036_50361701_22_dialog_content = "之前我們在船上之所以會做夢，不只是因為銜尾龍的精神能力。",
  ui_story_5036_50361701_23_dialog_content = "也是因為銜尾龍自己也一直在做夢。",
  ui_story_5036_50361701_24_dialog_content = "我們之前與其說是做了同一個夢，不如說是都看到了銜尾龍的夢境。",
  ui_story_5036_50361701_25_dialog_content = "它為什麼要創造那樣的夢境呢？",
  ui_story_5036_50361701_26_dialog_content = "或許是因為思念和懊悔吧……",
  ui_story_5036_50361701_27_dialog_content = "就算變成了蛋，銜尾龍也依舊能感知到夏米娜德陷入危險的情況。",
  ui_story_5036_50361701_28_dialog_content = "它沒辦法出手相助，卻能感知到夏米娜德想要回家的願望。",
  ui_story_5036_50361701_29_dialog_content = "所以，思念夏米娜德的它創造了那個夢境，創造了一個自己的朋友回到家鄉的夢。",
  ui_story_5036_50361701_30_dialog_content = "銜尾龍為了維持那個夢，遲遲沒有醒來。",
  ui_story_5036_50361701_31_dialog_content = "原來如此，難怪銜尾龍一直沒有孵化！",
  ui_story_5036_50361701_32_dialog_content = "那為什麼這次它又突然孵化了？難不成也和那個夢有關？",
  ui_story_5036_50361701_33_dialog_content = "因為我一不小心說漏嘴了……",
  ui_story_5036_50361701_34_dialog_content = "夏米娜德知道空之山谷已經毀滅以後，陷入了悲傷。",
  ui_story_5036_50361701_35_dialog_content = "夢境也隨之崩塌，不管怎樣都回不到以前的樣子了。",
  ui_story_5036_50361701_36_dialog_content = "我甚至都來不及好好向她道歉。",
  ui_story_5036_50361701_37_dialog_content = "不過，最後她希望我將那首歌唱給大家聽。",
  ui_story_5036_50361701_38_dialog_content = "哪怕以後再也不能當偶像了，我也想去完成她的託付。",
  ui_story_5036_50361701_39_dialog_content = "<color=#e8d9bb>滴滴滴——</color>",
  ui_story_5036_50361701_40_dialog_content = "呃！是涉發來的通訊要求！",
  ui_story_5036_50361701_41_dialog_content = "怎……怎麼辦，接嗎？",
  ui_story_5036_50361701_42_dialog_content = "有種不妙的預感呢～",
  ui_story_5036_50361701_43_dialog_content = "等等，讓我扔一下髮夾來決定！",
  ui_story_5036_50361701_44_dialog_content = "<color=#e8d9bb>叮——</color>",
  ui_story_5036_50361701_45_dialog_content = "仍然是彈頭朝下，是不錯的預兆！",
  ui_story_5036_50361701_46_dialog_content = "真要接通嗎？",
  ui_story_5036_50361701_47_dialog_content = "接通吧，PlayerName。",
  ui_story_5036_50361701_48_dialog_content = "迴避問題是沒有用的，只有面對它才會有轉機！",
  ui_story_5036_50361701_49_dialog_content = "那我接通了——",
  ui_story_5036_50361701_50_dialog_content = "PlayerName？",
  ui_story_5036_50361701_51_dialog_content = "涉女士，我在聽！",
  ui_story_5036_50361701_52_dialog_content = "你們現在在哪裡？情況如何？",
  ui_story_5036_50361701_53_dialog_content = "我們在臨空者號上，大家都在，沒有人受傷。",
  ui_story_5036_50361701_54_dialog_content = "沒人受傷？那就好，那麼……",
  ui_story_5036_50361701_55_dialog_content = "歌爾蒂！",
  ui_story_5036_50361701_56_dialog_content = "嗚——！",
  ui_story_5036_50361701_57_dialog_content = "妳是不是該好好解釋一下，明明志在必得的演唱會是怎麼鬧成現在這樣的？",
  ui_story_5036_50361701_58_dialog_content = "我......我……",
  ui_story_5036_50361701_59_dialog_content = "對不起，我搞砸了……",
  ui_story_5036_50361701_60_dialog_content = "我沒有仔細考察演唱會的場地，沒有發現巨像上有銜尾龍蛋這個隱患。",
  ui_story_5036_50361701_61_dialog_content = "也沒想到銜尾龍會對我的歌產生反應，開始孵化……",
  ui_story_5036_50361701_62_dialog_content = "哎呀，不解釋一下嗎？就算把責任推給銜尾龍也沒關係哦～",
  ui_story_5036_50361701_63_dialog_content = "不，這一切都是我的責任，我會負起責任，也會按照合約的要求賠償。",
  ui_story_5036_50361701_64_dialog_content = "唉……妳可把我害慘了。",
  ui_story_5036_50361701_65_dialog_content = "不僅花了大把的錢做宣傳，巨像一飛走，維修設備和佈置舞台的錢也付之東流。",
  ui_story_5036_50361701_66_dialog_content = "更別提還有額外的開銷，像是演出發生意外時，為了穩住觀眾而付出的費用。",
  ui_story_5036_50361701_67_dialog_content = "對不起……",
  ui_story_5036_50361701_68_dialog_content = "不過您放心，這些費用，我會一一賠償。",
  ui_story_5036_50361701_69_dialog_content = "就算未來不能再做偶像，我也會靠著打工和——",
  ui_story_5036_50361701_70_dialog_content = "嗯？我什麼時候說要妳賠償了？",
  ui_story_5036_50361701_71_dialog_content = "……欸？",
  ui_story_5036_50361701_72_dialog_content = "雖然演唱會確實失敗了，但是，演唱會的效果卻出乎意料的好！",
  ui_story_5036_50361701_73_dialog_content = "妳的歌聲蘊含的情感不只傳達給了銜尾龍，更傳達給了聽眾們！",
  ui_story_5036_50361701_74_dialog_content = "就連那些原本對偶像毫無興趣的人們，也因為這件事知道了妳的名字。",
  ui_story_5036_50361701_75_dialog_content = "已有不少人前來詢問關於「偶像」的事情了！",
  ui_story_5036_50361701_76_dialog_content = "欸！？",
  ui_story_5036_50361701_77_dialog_content = "妳不只完美履行了約定，而且還超乎預期。",
  ui_story_5036_50361701_78_dialog_content = "我……我沒聽錯吧！？",
  ui_story_5036_50361701_79_dialog_content = "不信？妳親耳聽聽看吧。",
  ui_story_5036_50361701_80_dialog_content = "大姐姐！妳聽到了嗎？",
  ui_story_5036_50361701_81_dialog_content = "是你！你和姐姐還好嗎？",
  ui_story_5036_50361701_82_dialog_content = "我們都很好！大姐姐，妳真是太厲害了！",
  ui_story_5036_50361701_83_dialog_content = "不只唱歌好聽，還能讓那條龍乖乖聽話！",
  ui_story_5036_50361701_84_dialog_content = "大家都看到了妳勇敢的身姿，真是太帥了！",
  ui_story_5036_50361701_85_dialog_content = "真的嗎？嘿嘿，聽你這麼說，我很開心！",
  ui_story_5036_50361701_86_dialog_content = "還有其他的人想和妳說話哦！",
  ui_story_5036_50361701_87_dialog_content = "妳就是歌爾蒂嗎？",
  ui_story_5036_50361701_88_dialog_content = "是……是的。請問您是？",
  ui_story_5036_50361701_89_dialog_content = "妳有沒有興趣成為我的私人演唱家？",
  ui_story_5036_50361701_90_dialog_content = "您說什麼！？",
  ui_story_5036_50361701_91_dialog_content = "在親眼見證了妳的行動以後，我認為妳是一個高潔、勇敢、值得信賴的人。",
  ui_story_5036_50361701_92_dialog_content = "成為我的私人演唱家吧！以我的能力，能讓妳站在白夜城最高級的舞台上演唱！",
  ui_story_5036_50361701_93_dialog_content = "謝謝您的好意，可是……",
  ui_story_5036_50361701_94_dialog_content = "不滿意嗎？妳儘管開條件，我會全部滿足妳。",
  ui_story_5036_50361701_95_dialog_content = "不……不是酬勞的問題，而是相較於私人演唱家，我更希望繼續當偶像。",
  ui_story_5036_50361701_96_dialog_content = "因為偶像可以為人們帶來歡樂和希望，無論聽眾是誰。",
  ui_story_5036_50361701_97_dialog_content = "而且，我已經答應一位很重要的偶像前輩，要把我們的歌唱給每一個人聽！",
  ui_story_5036_50361701_98_dialog_content = "是嗎？真是可惜……",
  ui_story_5036_50361701_99_dialog_content = "祝妳順利實現夢想，下次演唱會，我也一定會去觀賞的。",
  ui_story_5036_50361701_100_dialog_content = "感謝您的喜愛！",
  ui_story_5036_50361701_101_dialog_content = "如何，可以確信了吧？",
  ui_story_5036_50361701_102_dialog_content = "是的，我已經沒有任何疑問了！",
  ui_story_5036_50361701_103_dialog_content = "好，那就打起精神來，準備迎接之後的挑戰吧。",
  ui_story_5036_50361701_104_dialog_content = "我已經為妳排滿了行程，就等妳回影鎮後實行了。",
  ui_story_5036_50361701_105_dialog_content = "好的，我馬上就回去！",
  ui_story_5036_50361701_106_dialog_content = "我還聽說妳發掘了一名很有潛力的新人叫做維克，他在嗎？",
  ui_story_5036_50361701_107_dialog_content = "叫我嗎？",
  ui_story_5036_50361701_108_dialog_content = "有興趣成為我旗下的專屬偶像嗎？",
  ui_story_5036_50361701_109_dialog_content = "啊？啊哈哈哈，還是算了吧！",
  ui_story_5036_50361701_110_dialog_content = "受到矚目的生活不適合我，我更喜歡與動物們一起生活。",
  ui_story_5036_50361701_111_dialog_content = "真的不考慮嗎？",
  ui_story_5036_50361701_112_dialog_content = "我能提供最優渥的報酬，以及影鎮生產的最高品質香檳。",
  ui_story_5036_50361701_113_dialog_content = "聽起來頗誘人呢，這樣是不是就不用每天照顧小毛球們，只需要喝酒就——",
  ui_story_5036_50361701_114_dialog_content = "嗚啾！？",
  ui_story_5036_50361701_115_dialog_content = "嗚啾！！！",
  ui_story_5036_50361701_116_dialog_content = "欸！？小毛球，別扯啊，快放開！小毛球——",
  ui_story_5036_50361701_117_dialog_content = "看來有人堅決不同意呢。",
  ui_story_5036_50361701_118_dialog_content = "好吧，這件事留待下次再談吧。",
  ui_story_5036_50361701_119_dialog_content = "那麼，我們一會影鎮見。",
  ui_story_5036_50361701_120_dialog_content = "太好了，真是太好了！",
  ui_story_5036_50361701_121_dialog_content = "我還可以繼續當偶像！",
  ui_story_5036_50361701_122_dialog_content = "恭喜妳，歌爾蒂！",
  ui_story_5036_50361701_123_dialog_content = "雖然這次的演唱會一波三折，但下次我一定會順利舉辦的。",
  ui_story_5036_50361701_124_dialog_content = "到時候記得來聽啊，PlayerName，我會為你保留最好的座位！",
  ui_story_5036_50361701_125_dialog_content = "當然，一言為定！",
  ui_story_5036_50361701_126_dialog_content = "不過，可能要過段時間才行了！",
  ui_story_5036_50361701_127_dialog_content = "等回去以後，我要先把這一次的經歷寫成一首新歌才行！",
  ui_story_5036_50361701_128_dialog_content = "看來，一切都順利落下帷幕了。",
  ui_story_5036_50361701_129_dialog_content = "確實是呢，一旦放鬆下來，就感到有點累了。",
  ui_story_5036_50361701_130_dialog_content = "我已經開始犯睏了，呵欠——",
  ui_story_5036_50361701_131_dialog_content = "哼，要不是有這麼多事，我現在已經在泡熱水澡了。",
  ui_story_5036_50361701_132_dialog_content = "洗不洗澡，問題不大。",
  ui_story_5036_50361701_133_dialog_content = "反正，沒有區別。",
  ui_story_5036_50361701_134_dialog_content = "不過，能見到歌頌者號上罕見的古代科技，真是不錯的經驗！",
  ui_story_5036_50361701_135_dialog_content = "那些螢幕和音響設備真是太有趣了，我的靈感正在不斷湧現！",
  ui_story_5036_50361701_136_dialog_content = "要不要考慮現在就開始研究它們的原理，然後製作幾個相同的裝在王座上呢？",
  ui_story_5036_50361701_137_dialog_content = "妳該不會是想……",
  ui_story_5036_50361701_138_dialog_content = "那樣就能隨時隨地玩遊戲了！",
  ui_story_5036_50361701_139_dialog_content = "果然如此。",
  ui_story_5036_50361701_140_dialog_content = "總之，我先送各位回地上吧！",
  ui_story_5036_50361701_141_dialog_content = "<color=#e8d9bb>一段時間後</color>",
  ui_story_5036_50361701_142_dialog_content = "沒想到已經過了這麼久，天都亮了。",
  ui_story_5036_50361701_143_dialog_content = "終於回到地面了呢，可真不容易啊。是吧，小毛球？",
  ui_story_5036_50361701_144_dialog_content = "嗚啾！",
  ui_story_5036_50361701_145_dialog_content = "明明都是我們在戰鬥，你只負責在旁邊看！",
  ui_story_5036_50361701_146_dialog_content = "怎麼能這麼說呢，我也花了很大的力氣去保護銜尾龍了～",
  ui_story_5036_50361701_147_dialog_content = "算了，看在你確實有拼命的份上，就不和你計較。",
  ui_story_5036_50361701_148_dialog_content = "那我先走了，菲雅和詩燁還在等我這位師父回去講解關於銜尾龍的知識。",
  ui_story_5036_50361701_149_dialog_content = "下次再見啦。",
  ui_story_5036_50361701_150_dialog_content = "再見，維克。",
  ui_story_5036_50361701_151_dialog_content = "路上小心點，別又被綁架了！",
  ui_story_5036_50361701_152_dialog_content = "放心吧，我可是名值得信賴的成年人！",
  ui_story_5036_50361701_153_dialog_content = "我們也要搭空艇回白夜城了。",
  ui_story_5036_50361701_154_dialog_content = "（真是，下次定要讓人提前備好洗澡水……）",
  ui_story_5036_50361701_155_dialog_content = "紅油扳手的，下次再遇上，我會把你們全關進監獄裡。",
  ui_story_5036_50361701_156_dialog_content = "哈？你這傢伙口氣不小啊，有本事就來！",
  ui_story_5036_50361701_157_dialog_content = "空裔，再見。",
  ui_story_5036_50361701_158_dialog_content = "再見！",
  ui_story_5036_50361701_159_dialog_content = "大家都走了嗎？小諾諾，我們也回去吧！",
  ui_story_5036_50361701_160_dialog_content = "好吧。假期已經快結束了，是時候回去工作了。",
  ui_story_5036_50361701_161_dialog_content = "貢露長官不和我們一起搭乘巨像回去嗎？",
  ui_story_5036_50361701_162_dialog_content = "不必啦。我和小諾諾搭車回去，就不影響你們接下來的行程啦。",
  ui_story_5036_50361701_163_dialog_content = "我打算在車上和小諾諾一起研究把螢幕和遊戲機加裝在王座上的可行性！",
  ui_story_5036_50361701_164_dialog_content = "嗯？您剛才說什麼！？",
  ui_story_5036_50361701_165_dialog_content = "我們走吧，小～諾～諾～",
  ui_story_5036_50361701_166_dialog_content = "救……救我！",
  ui_story_5036_50361701_167_dialog_content = "就算是希諾普那般可靠的人，也會有解決不了的問題呢。",
  ui_story_5036_50361701_168_dialog_content = "那我們也回去了。",
  ui_story_5036_50361701_169_dialog_content = "嗯……嗯！",
  ui_story_5036_50361701_170_dialog_content = "我決定了！",
  ui_story_5036_50361701_171_dialog_content = "哈？妳又想到什麼天馬行空的事了？",
  ui_story_5036_50361701_172_dialog_content = "等一回去，我就要說服老大，在陸行者號的腦袋上也加裝一個舞台！",
  ui_story_5036_50361701_173_dialog_content = "聽起來竟然還不錯！？",
  ui_story_5036_50361701_174_dialog_content = "這可是我想到的，我現在就去，要讓老大把舞台修成偶像風格的！",
  ui_story_5036_50361701_175_dialog_content = "給我等等！金屬搖滾才是正道！",
  ui_story_5036_50361701_176_dialog_content = "她們可真熱鬧呢！",
  ui_story_5036_50361701_177_dialog_content = "我們也在這裡道別吧，PlayerName。",
  ui_story_5036_50361701_178_dialog_content = "這次辛苦你了！",
  ui_story_5036_50361701_179_dialog_content = "妳也辛苦了，忙著舉辦演唱會，又戰鬥了那麼長的時間，該好好休息一下了。",
  ui_story_5036_50361701_180_dialog_content = "我可是職業偶像，只要稍微休息一下，就能立刻恢復精神！",
  ui_story_5036_50361701_181_dialog_content = "就請你好好期待我的下一場演唱會吧！",
  ui_story_5036_50361701_182_dialog_content = "我會等妳聯絡的！",
  ui_story_5036_50361701_183_dialog_content = "再見啦！",
  ui_story_5036_50361701_184_dialog_content = "原來歌爾蒂有暴力傾向是謠言，我得報導這件事，替她澄清。",
  ui_story_5036_50361701_185_dialog_content = "喂，是編輯老師嗎？",
  ui_story_5036_50361701_186_dialog_content = "<size=45>珀蘭蒂，怎麼這麼晚才聯絡我！</size>",
  ui_story_5036_50361701_187_dialog_content = "如果沒有什麼能讓我滿意的大新聞，妳就等著被炒吧！",
  ui_story_5036_50361701_188_dialog_content = "我……我把歌爾蒂有暴力傾向的傳聞調查清楚了，是假新聞！",
  ui_story_5036_50361701_189_dialog_content = "……",
  ui_story_5036_50361701_190_dialog_content = "在漂流巨像飛過影鎮的這段長時間裡，妳只調查出這點事？",
  ui_story_5036_50361701_191_dialog_content = "就算是假新聞，也沒辦法吸引到讀者吧？只有這種程度的新聞，報社就要倒閉了。",
  ui_story_5036_50361701_192_dialog_content = "珀蘭蒂，妳太令我失望了，我現在就把妳開除——",
  ui_story_5036_50361701_193_dialog_content = "等一等！不只這樣，我還有漂流巨像演唱會事件的獨家一手資料！",
  ui_story_5036_50361701_194_dialog_content = "什麼？妳說真的？快拿過來！",
  ui_story_5036_50361701_195_dialog_content = "可以是可以，但我有一個要求。",
  ui_story_5036_50361701_196_dialog_content = "是什麼？",
  ui_story_5036_50361701_197_dialog_content = "歌爾蒂的澄清報導和漂流巨像的新聞報導要一起放上！",
  ui_story_5036_50361701_198_dialog_content = "我想讓所有人知道，他們誤會了歌爾蒂！",
  ui_story_5036_50361701_199_dialog_content = "這......這簡直是……",
  ui_story_5036_50361701_200_dialog_content = "<size=45>好吧！</size>",
  ui_story_5036_50361701_201_dialog_content = "我同意，現在，立刻把資料拿過來。",
  ui_story_5036_50361701_202_dialog_content = "我馬上就去！",
  ui_story_5036_50361701_203_dialog_content = "所以廢柴師父用動物餅乾誘拐蒼獅龍，偷偷跑到漂流巨像上調查，結果白忙一場！？",
  ui_story_5036_50361701_204_dialog_content = "害我找蒼獅龍找了好久找不到，還差點被暗鬼偷襲！",
  ui_story_5036_50361701_205_dialog_content = "師父，你打算怎麼賠我？",
  ui_story_5036_50361701_206_dialog_content = "哎呀，雖然確實沒能徹底調查銜尾龍，但我們確實喚醒它了，還獲得了不少情報。",
  ui_story_5036_50361701_207_dialog_content = "銜尾龍的歸來，一定會給艾斯特拉帶來新的變化！",
  ui_story_5036_50361701_208_dialog_content = "相信為師，有了這些情報，下次再找銜尾龍就會變得手到擒來～",
  ui_story_5036_50361701_209_dialog_content = "這句話怎麼這麼耳熟啊？",
  ui_story_5036_50361701_210_dialog_content = "上次他是這麼說的——",
  ui_story_5036_50361701_211_dialog_content = "「相信為師，為師下次一定會賺大錢的。」",
  ui_story_5036_50361701_212_dialog_content = "師姐，妳怎麼記得這麼清楚？",
  ui_story_5036_50361701_213_dialog_content = "因為他上上次也是這麼說的。",
  ui_story_5036_50361701_214_dialog_content = "但是，直到現在，他的財務狀況也沒有任何改善，還越來越窮了。",
  ui_story_5036_50361701_215_dialog_content = "確實呢，神奇動物們上個月的伙食費還沒有付清！",
  ui_story_5036_50361701_216_dialog_content = "嗚嗚，為師在妳們眼中就這麼不中用嗎？",
  ui_story_5036_50361701_217_dialog_content = "要不然呢？",
  ui_story_5036_50361701_218_dialog_content = "為師好傷心！",
  ui_story_5036_50361701_219_dialog_content = "難道大家都認為我還是更適合當偶像嗎？",
  ui_story_5036_50361701_220_dialog_content = "別人幫你鼓掌是在可憐你，你不要恩將仇報。",
  ui_story_5036_50361701_221_dialog_content = "嗚！",
  ui_story_5036_50361701_222_dialog_content = "不過廢柴師父這次總算說對了一次，銜尾龍竟然真的在那艘漂流巨像上。",
  ui_story_5036_50361701_223_dialog_content = "你到底是怎麼知道這件事的？",
  ui_story_5036_50361701_224_dialog_content = "或許對銜尾龍而言，「前往巨像」這件事，本身也是一種「回歸」吧？",
  ui_story_5036_50361701_225_dialog_content = "「回歸」？那是什麼意思？",
  ui_story_5036_50361701_226_dialog_content = "就是說，無論銜尾龍這一物種能活多少年，能重新孵化多少次……",
  ui_story_5036_50361701_227_dialog_content = "在最初的最初，它都是由別的銜尾龍生下的龍蛋。",
  ui_story_5036_50361701_228_dialog_content = "幼年的動物會遵循本能跟隨自己的父母，尋找庇護和依靠。",
  ui_story_5036_50361701_229_dialog_content = "在每個生命週期中，逐漸回歸幼年的銜尾龍也是如此。",
  ui_story_5036_50361701_230_dialog_content = "只不過銜尾龍太過稀少，絕大多數時候，銜尾龍都找不到原本的父母。",
  ui_story_5036_50361701_231_dialog_content = "因此，它們只能去尋找與自身有深厚淵源的巨像。",
  ui_story_5036_50361701_232_dialog_content = "真可憐啊，把巨像當成自己的父母了……",
  ui_story_5036_50361701_233_dialog_content = "既然如此，那有銜尾龍血脈的師父，是否有一天也會去找巨像回歸啊？",
  ui_story_5036_50361701_234_dialog_content = "我的身世還是個謎呢，小孩子不要亂猜～",
  ui_story_5036_50361701_235_dialog_content = "也是，師父這麼廢柴，也不會使用心靈能力，擁有銜尾龍血脈這件事大概只是吹牛呢。",
  ui_story_5036_50361701_236_dialog_content = "這可是真的哦！",
  ui_story_5036_50361701_237_dialog_content = "如果你真有銜尾龍血脈的話，那銜尾龍怎麼沒來找你啊？",
  ui_story_5036_50361701_238_dialog_content = "這不就是要研究的課題嗎？先讓我們——",
  ui_story_5036_50361701_239_dialog_content = "啾——！",
  ui_story_5036_50361701_240_dialog_content = "！？"
}
